window.SORULAR = [{"id": "MRK2-001", "exam": "marka", "topic": "Coğrafi İşaret", "q": "6769 sayılı SMK'ya göre menşe adını mahreç işaretinden ayıran temel unsur aşağıdakilerden hangisidir?", "options": ["Menşe adının tescil edilmeden de korunması, mahreç işaretinin ise yalnızca tescil ile korunması", "Menşe adında amblem kullanımının zorunlu, mahreç işaretinde ise isteğe bağlı olması", "Menşe adında üretim, işleme ve diğer işlemlerin tümünün belirlenen coğrafi alanda gerçekleşmesi gerekirken, mahreç işaretinde bu işlemlerden en az birinin o alanda yapılmasının yeterli olması", "Menşe adına yalnızca üretici gruplarının, mahreç işaretine ise herkesin başvurabilmesi", "Menşe adının en az otuz yıl süreyle kullanılmış olmasının kanıtlanması gerekmesi"], "answer": 2, "why": ["Yanlış. Hem menşe adı hem mahreç işareti koruması tescil yoluyla elde edilir (SMK m.33/1, m.44/1).", "Yanlış. Amblem kullanımı coğrafi işaretlerin tamamı, yani hem menşe adı hem mahreç işareti için zorunludur (SMK m.46/2).", "Doğru. Menşe adında üretim, işleme ve diğer işlemlerin tümü coğrafi alanda gerçekleşir; mahreç işaretinde bunlardan en az birinin o alanda yapılması yeterlidir (SMK m.34/1-a, b).", "Yanlış. Başvuru hakkına sahip olanlar (üretici grupları, kamu kurumları, dernek/vakıf/kooperatifler, tek üretici) her iki tür için aynıdır (SMK m.36/1).", "Yanlış. En az otuz yıllık geleneksel kullanım şartı menşe adı için değil, geleneksel ürün adı için aranır (SMK m.34/3)."], "ref": "SMK m.34"}, {"id": "MRK2-002", "exam": "marka", "topic": "Geleneksel Ürün Adı", "q": "SMK'ya göre menşe adı veya mahreç işareti kapsamına girmeyen bir adın geleneksel ürün adı olarak tanımlanabilmesi için ilgili piyasada ürünü tarif etmek amacıyla geleneksel olarak en az kaç yıl süreyle kullanıldığının kanıtlanması gerekir?", "options": ["10 yıl", "15 yıl", "25 yıl", "50 yıl", "30 yıl"], "answer": 4, "why": ["Yanlış. Kanun on yıllık bir kullanım süresi öngörmemektedir (SMK m.34/3).", "Yanlış. On beş yıl yeterli değildir; aranan asgari süre otuz yıldır (SMK m.34/3).", "Yanlış. Yirmi beş yıl, tescilli tasarımın azami koruma süresidir (SMK m.69/1); geleneksel ürün adında aranan süre otuz yıldır.", "Yanlış. Elli yıl şartı yoktur; Kanun en az otuz yıllık kullanımı yeterli görür (SMK m.34/3).", "Doğru. Geleneksel olarak en az otuz yıl süreyle kullanıldığı kanıtlanan adlar, ek şartlardan en az birini sağlarsa geleneksel ürün adıdır (SMK m.34/3)."], "ref": "SMK m.34/3"}, {"id": "MRK2-003", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Coğrafi işaret ve geleneksel ürün adı tanımlarına ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Coğrafi bir yer adı içermeyen, ancak gerekli şartları taşıyan bir ürünü belirtmek için geleneksel olarak kullanılan ve günlük dilde yerleşmiş adlar da menşe adı veya mahreç işareti olabilir.\nII. Menşe adı, istisnai durumlarda bir ülkeden kaynaklanan ürünleri tanımlayan ad olabilir.\nIII. Geleneksel ürün adı olarak tanımlanabilmek için hem geleneksel üretim yöntemine dayanma hem de geleneksel hammaddeden üretilmiş olma şartlarının birlikte sağlanması gerekir.", "options": ["I ve II", "Yalnız I", "Yalnız III", "II ve III", "I, II ve III"], "answer": 0, "why": ["Doğru. I (SMK m.34/2) ve II (SMK m.34/1-a) doğrudur; III yanlıştır çünkü şartlardan en az birinin sağlanması yeterlidir (SMK m.34/3).", "Yanlış. II de doğrudur; menşe adı istisnai durumlarda ülkeden kaynaklanabilir (SMK m.34/1-a).", "Yanlış. III yanlıştır; m.34/3 'aşağıdaki şartlardan en az birini' sağlamayı yeterli görür.", "Yanlış. III yanlış olduğu için bu seçenek doğru olamaz; ayrıca I de doğrudur (SMK m.34/2).", "Yanlış. III yanlıştır; geleneksel üretim yöntemi/bileşim ile geleneksel hammadde şartları seçimlik olarak aranır (SMK m.34/3)."], "ref": "SMK m.34"}, {"id": "MRK2-004", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Aşağıdakilerden hangisi SMK m.35/1'de sayılan, coğrafi işaret olarak tescil edilmeyecek adlardan biri değildir?", "options": ["Ürünlerin öz adı olmuş adlar", "Ürünün genel özelliğini ifade eden adlar", "Kamu düzenine veya genel ahlaka aykırı adlar", "Kendi ülkesinde korunmayan, koruması sona eren veya kullanılmayan adlar", "Tescilli veya başvurusu yapılmış bir coğrafi işaret ile tamamen veya kısmen eş sesli olan ve tüketiciyi yanıltabilecek adlar"], "answer": 1, "why": ["Yanlış. Ürünlerin öz adı olmuş adlar coğrafi işaret olarak tescil edilmez (SMK m.35/1-b).", "Doğru. 'Ürünün genel özelliğini ifade eden adlar' coğrafi işaret için değil, geleneksel ürün adı için öngörülen bir ret hâlidir (SMK m.35/2-b).", "Yanlış. Kamu düzenine veya genel ahlaka aykırı adlar coğrafi işaret olarak tescil edilmez (SMK m.35/1-ç).", "Yanlış. Yabancı başvurularda kendi ülkesinde korunmayan, koruması sona eren veya kullanılmayan adlar tescil edilmez (SMK m.35/1-d).", "Yanlış. Tescilli/başvurusu yapılmış coğrafi işaretle eş sesli ve tüketiciyi yanıltabilecek adlar tescil edilmez (SMK m.35/1-e)."], "ref": "SMK m.35"}, {"id": "MRK2-005", "exam": "marka", "topic": "Coğrafi İşaret", "q": "SMK'ya göre aşağıdakilerden hangisi coğrafi işaret tescil başvurusunda bulunma hakkına sahip değildir?", "options": ["Aynı ürünün üreticilerinden oluşan üretici grubu", "Ürünün kaynaklandığı coğrafi alanla ilgili kamu kurumu", "Ürünle ilgili olarak üyelerinin ekonomik çıkarlarını korumaya yetkili kooperatif", "Ürünün birden fazla üreticisi bulunan bir bölgede, diğer üreticilerden bağımsız olarak tek başına başvuru yapan bir üretici", "Ürünün tek üreticisi olduğunu ispat eden üretici"], "answer": 3, "why": ["Yanlış. Üretici grupları başvuru hakkına sahiptir (SMK m.36/1-a, m.36/2).", "Yanlış. Ürün veya coğrafi alanla ilgili kamu kurum ve kuruluşları başvuru yapabilir (SMK m.36/1-b).", "Yanlış. Üyelerinin ekonomik çıkarlarını korumaya yetkili dernek, vakıf ve kooperatifler başvuru yapabilir (SMK m.36/1-c).", "Doğru. Tek bir üretici ancak ürünün tek üreticisi olması ve bunu ispat etmesi hâlinde başvurabilir; birden fazla üretici varsa tek başına başvuru hakkı yoktur (SMK m.36/1-ç).", "Yanlış. Ürünün tek üreticisi bu durumu ispat etmek şartıyla başvuru yapabilir (SMK m.36/1-ç)."], "ref": "SMK m.36"}, {"id": "MRK2-006", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Bültende yayımlanan bir coğrafi işaret başvurusuna, tescil talebinin SMK'ya uygun olmadığı iddiasıyla üçüncü kişiler hangi süre içinde itiraz edebilir?", "options": ["Bültende yayımlandığı tarihten itibaren üç ay", "Bültende yayımlandığı tarihten itibaren iki ay", "Bültende yayımlandığı tarihten itibaren altı ay", "Başvuru tarihinden itibaren üç ay", "Bültende yayımlandığı tarihten itibaren bir ay"], "answer": 0, "why": ["Doğru. Üçüncü kişiler ve önceki tarihli hak sahipleri, Bültende yayım tarihinden itibaren üç ay içinde gerekçeli ve yazılı olarak itiraz edebilir (SMK m.40/2).", "Yanlış. İki aylık süre, başvuru yapanın ret kararına karşı bildirim tarihinden itibaren yapacağı itiraz içindir (SMK m.40/1).", "Yanlış. Coğrafi işaret başvurusuna itiraz için altı aylık bir süre öngörülmemiştir (SMK m.40/2).", "Yanlış. Süre başvuru tarihinden değil, Bültende yayım tarihinden başlar (SMK m.40/2).", "Yanlış. Bir aylık süre öngörülmemiştir; süre üç aydır (SMK m.40/2)."], "ref": "SMK m.40/2"}, {"id": "MRK2-007", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Bir dernek tarafından yapılan coğrafi işaret başvurusunun başvuru formunda, başvuru yapanın kimliğine ilişkin bilgiler hiç yer almamaktadır. SMK'ya göre bu durumda aşağıdakilerden hangisi doğrudur?", "options": ["Kurum eksikliğin giderilmesini ister; talep hâlinde iki defayı geçmemek üzere ek süre verilir.", "Başvuru reddedilir; başvuru yapan kararın bildiriminden itibaren iki ay içinde itiraz edebilir.", "Başvuru Bültende yayımlanır ve kimlik eksikliği üçüncü kişilerin itirazı ile ileri sürülebilir.", "Kurum başvuruyu ilgili kurum ve kuruluşların görüşüne sunar.", "Başvuru yapılmamış sayılır; bu karar Kurumun nihai kararı olup itiraza konu olamaz."], "answer": 4, "why": ["Yanlış. Eksiklik giderme ve iki defaya kadar ek süre imkânı, kimlik bilgileri hariç diğer m.37 eksiklikleri içindir (SMK m.38/3).", "Yanlış. Kimlik bilgisi eksikliğinde başvuru reddedilmez, yapılmamış sayılır ve bu karara itiraz edilemez (SMK m.38/2).", "Yanlış. Kimlik bilgisi bulunmayan başvuru yapılmamış sayıldığından yayım aşamasına geçmez (SMK m.38/2, m.38/5).", "Yanlış. Kurumun ilgili kuruluşlardan görüş alması teknik bilgilerin değerlendirilmesi içindir; kimlik eksikliğinin sonucu bu değildir (SMK m.38/4).", "Doğru. Başvuru formunda kimlik bilgisi yoksa başvuru yapılmamış sayılır ve bu karar Kurumun nihai kararı olup m.40 kapsamında itiraza konu olamaz (SMK m.38/2)."], "ref": "SMK m.38/2"}, {"id": "MRK2-008", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Coğrafi işaret ve geleneksel ürün adının hükümsüzlüğüne ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Hükümsüzlük, menfaati olanlar tarafından mahkemeden istenebilir.\nII. Hükümsüzlük davası Türk Patent ve Marka Kurumuna karşı açılır.\nIII. Denetim işlemlerinin SMK m.49'da belirtilen biçimde yerine getirilmemesi hükümsüzlük sebebidir.", "options": ["Yalnız I", "Yalnız II", "I ve III", "II ve III", "I, II ve III"], "answer": 2, "why": ["Yanlış. III de doğrudur; denetimin m.49'a uygun yapılmaması hükümsüzlük sebebidir (SMK m.50/2-c).", "Yanlış. II yanlıştır; dava sicilde tescil ettiren olarak kayıtlı kişiye karşı açılır ve Kurum taraf gösterilmez (SMK m.50/3).", "Doğru. I (SMK m.50/1) ve III (SMK m.50/2-c) doğrudur; II yanlıştır (SMK m.50/3).", "Yanlış. II yanlıştır; hükümsüzlük davalarında Kurum taraf gösterilmez (SMK m.50/3).", "Yanlış. II yanlış olduğundan tüm öncüller doğru değildir (SMK m.50/3)."], "ref": "SMK m.50"}, {"id": "MRK2-009", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Bültende yayımlanan ve süresi içinde itiraz edilmeyen bir coğrafi işaret başvurusunun tescil edilebilmesi için tescil ücretinin ödenmesi ve ödendiğine ilişkin bilginin Kuruma sunulması gereken süre aşağıdakilerden hangisidir?", "options": ["Yayım tarihinden itibaren bir ay", "Bildirim tarihinden itibaren iki ay", "Bildirim tarihinden itibaren üç ay", "Yayım tarihinden itibaren altı ay", "Başvuru tarihinden itibaren bir yıl"], "answer": 1, "why": ["Yanlış. Kanun bir aylık süre öngörmez; süre bildirimden itibaren iki aydır (SMK m.41/1).", "Doğru. Başvuru, bildirim tarihinden itibaren iki ay içinde tescil ücretinin ödenmesi ve bilginin sunulması şartıyla tescil edilir (SMK m.41/1).", "Yanlış. Üç ay, yayıma itiraz süresidir (SMK m.40/2, m.41/1); tescil ücreti süresi iki aydır.", "Yanlış. Altı aylık bir tescil ücreti süresi yoktur (SMK m.41/1).", "Yanlış. Bir yıl, kesinleşen değişikliklerin uygulanması için öngörülen süredir (SMK m.42/2)."], "ref": "SMK m.41/1"}, {"id": "MRK2-010", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Tescilli coğrafi işaretten doğan haklara ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Tescil edilen coğrafi işaret, tescil ettirene inhisari hak sağlar.\nII. Tescil edilen coğrafi işaretlerin ürünün öz adına dönüşmüş olduğu kabul edilmez.\nIII. Coğrafi işaret tescilinin sağladığı haklar, üçüncü kişilere karşı tescilin Bültende yayımlandığı tarih itibarıyla hüküm ifade eder.", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 3, "why": ["Yanlış. I yanlıştır; tescil edilen coğrafi işaret tescil ettirene inhisari hak sağlamaz (SMK m.44/7).", "Yanlış. I yanlıştır (SMK m.44/7); ayrıca III de doğrudur (SMK m.44/3).", "Yanlış. I yanlıştır; coğrafi işaret, şartlara uyan tüm üreticilerin kullanabildiği kolektif bir haktır (SMK m.44/7, m.46/1).", "Doğru. II (SMK m.44/4) ve III (SMK m.44/3) doğrudur; I yanlıştır (SMK m.44/7).", "Yanlış. I yanlış olduğundan tüm öncüller doğru değildir (SMK m.44/7)."], "ref": "SMK m.44"}, {"id": "MRK2-011", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Tescilli coğrafi işaret ve geleneksel ürün adında amblem kullanımına ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Amblem kullanımı coğrafi işaretlerde isteğe bağlı, geleneksel ürün adlarında zorunludur.", "Amblem yalnızca menşe adları için zorunludur; mahreç işaretlerinde kullanılmaz.", "Ürünün niteliği gereği amblem ürün veya ambalaj üzerinde kullanılamıyorsa, coğrafi işaret kullanılamaz.", "Coğrafi işaretler bakımından amblem kullanılması zorunludur; geleneksel ürün adının amblemsiz kullanımı ise SMK hükümlerine tabi değildir.", "Amblemi tüketiciyi yanıltıcı biçimde kullanmak tecavüz sayılmaz; yalnızca coğrafi işaretin kendisinin kullanımı tecavüz oluşturur."], "answer": 3, "why": ["Yanlış. Durum tam tersidir; coğrafi işaretlerde amblem zorunludur (SMK m.46/2), geleneksel ürün adının amblemsiz kullanımı ise Kanuna tabi değildir (SMK m.46/4).", "Yanlış. Amblem zorunluluğu 'coğrafi işaretler' için öngörülmüştür; menşe adı ve mahreç işareti ayrımı yapılmaz (SMK m.46/2).", "Yanlış. Bu durumda amblem ile tescilli işaret, işletmede kolayca görülecek şekilde bulundurulur (SMK m.46/3).", "Doğru. Coğrafi işaretler bakımından amblem kullanımı zorunludur (SMK m.46/2); geleneksel ürün adının amblemsiz kullanımı Kanun hükümlerine tabi değildir (SMK m.46/4).", "Yanlış. Amblemin tüketiciyi yanıltıcı biçimde kullanımı açıkça tecavüz sayılır (SMK m.53/1-ç)."], "ref": "SMK m.46"}, {"id": "MRK2-012", "exam": "marka", "topic": "Coğrafi İşaret", "q": "SMK'ya göre coğrafi işaret ve geleneksel ürün adlarının kullanımının denetimi kapsamında, denetim raporlarının Kuruma sunulma sıklığı ile raporlarda tespit edilen eksikliğin giderilmesi için tescil ettirene verilen süre sırasıyla aşağıdakilerden hangisidir?", "options": ["Altı ayda bir / üç ay", "İki yılda bir / altı ay", "Yılda bir / iki ay", "Üç yılda bir / bir yıl", "Yılda bir / altı ay"], "answer": 4, "why": ["Yanlış. Raporlar altı ayda bir değil, yılda bir sunulur; eksiklik süresi de üç ay değil altı aydır (SMK m.49/3-4).", "Yanlış. Raporların sunulma sıklığı iki yılda bir değil, yılda birdir (SMK m.49/3).", "Yanlış. Sunulma sıklığı doğru olmakla birlikte eksikliği giderme süresi iki ay değil altı aydır (SMK m.49/4).", "Yanlış. Kanunda üç yıllık rapor dönemi veya bir yıllık giderme süresi öngörülmemiştir (SMK m.49/3-4).", "Doğru. Denetim raporları tescilin Bültende yayımından itibaren yılda bir sunulur; eksiklik varsa altı ay içinde giderilmesi istenir (SMK m.49/3-4)."], "ref": "SMK m.49"}, {"id": "MRK2-013", "exam": "marka", "topic": "Coğrafi İşaret", "q": "(X) ibareli marka, aynı ibareden oluşan coğrafi işaretin korunmasından önce peynir ürünleri için iyiniyetle tescil edilmiştir. Daha sonra (X) peyniri coğrafi işaret olarak tescil edilmiştir. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["Coğrafi işaretin hak sahibine verdiği yetkiler, markanın tesciline ve iyiniyetli kullanımına zarar vermez.", "Marka, coğrafi işaretin tescili ile kendiliğinden hükümsüz hâle gelir.", "Marka sahibi, coğrafi işaretin tescilinden itibaren markasını ancak amblemle birlikte kullanabilir.", "Kurum, markayı resen sicilden terkin eder.", "Marka sahibi, markasının yenilenmesini talep edemez."], "answer": 0, "why": ["Doğru. Coğrafi işaretle aynı veya benzer marka, coğrafi işaretin korunmasından önce iyiniyetle tescil edilmişse, coğrafi işaretin verdiği yetkiler markanın tesciline ve iyiniyetli kullanımına zarar vermez (SMK m.48/2).", "Yanlış. Kendiliğinden hükümsüzlük öngörülmemiştir; önceki iyiniyetli tescil korunur (SMK m.48/2).", "Yanlış. Amblem kullanımı coğrafi işaretin kullanım hakkı sahipleri için öngörülmüştür, marka sahibi için değil (SMK m.46/2, m.48/2).", "Yanlış. Kurumun resen terkin yetkisi yoktur; m.48/1'deki hükümsüzlük ise coğrafi işaretin tescilinden sonra yapılan marka başvuruları içindir (SMK m.48/1-2).", "Yanlış. Kanunda böyle bir yenileme yasağı yoktur; iyiniyetli önceki marka tescili zarar görmez (SMK m.48/2)."], "ref": "SMK m.48/2"}, {"id": "MRK2-014", "exam": "marka", "topic": "Coğrafi İşaret", "q": "Tescilli bir coğrafi işareti kullanma hakkına sahip olan bir üretici, coğrafi işarete tecavüz eden bir fiili tescil ettirene noter vasıtasıyla bildirerek dava açılmasını talep etmiştir. Tescil ettiren talebi kabul etmez veya bildirim tarihinden itibaren belirli bir süre içinde dava açmazsa, kullanma hakkı sahibi bildirimi de ekleyerek kendisi dava açabilir. Bu süre aşağıdakilerden hangisidir?", "options": ["Bir ay", "Üç ay", "İki ay", "Altı ay", "Bir yıl"], "answer": 1, "why": ["Yanlış. Kanunda bir aylık süre öngörülmemiştir (SMK m.53/2).", "Doğru. Tescil ettiren talebi kabul etmez veya bildirim tarihinden itibaren üç ay içinde dava açmazsa kullanma hakkı sahibi dava açabilir (SMK m.53/2).", "Yanlış. İki ay, ret kararına itiraz veya tescil ücreti gibi başka işlemlerin süresidir (SMK m.40/1, m.41/1); burada süre üç aydır.", "Yanlış. Altı ay, denetim raporlarındaki eksikliklerin giderilme süresidir (SMK m.49/4).", "Yanlış. Bir yıllık süre öngörülmemiştir; ayrıca ciddi zarar tehlikesinde süreye bağlı kalmaksızın ihtiyati tedbir istenebilir (SMK m.53/2)."], "ref": "SMK m.53/2"}, {"id": "MRK2-015", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre aşağıdakilerden hangisi tasarım hukuku bakımından 'ürün' tanımının kapsamı dışında kalır?", "options": ["Ambalaj", "Grafik semboller", "Tipografik karakterler", "Bilgisayar programları", "Birleşik ürünü oluşturan parçalar"], "answer": 3, "why": ["Yanlış. Ambalaj gibi nesneler ürün tanımına dâhildir (SMK m.55/2).", "Yanlış. Grafik semboller ürün tanımına açıkça dâhil edilmiştir (SMK m.55/2).", "Yanlış. Tipografik karakterler ürün tanımına dâhildir (SMK m.55/2).", "Doğru. Ürün tanımı 'bilgisayar programları hariç olmak üzere' yapılmıştır (SMK m.55/2).", "Yanlış. Birleşik ürün ve bu ürünü oluşturan parçalar ürün tanımına dâhildir (SMK m.55/2-3)."], "ref": "SMK m.55/2"}, {"id": "MRK2-016", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre tasarımın yeniliğine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Tescilli tasarımın aynısı başvuru veya rüçhan tarihinden önce yalnızca Türkiye'de kamuya sunulmamışsa tasarım yeni kabul edilir.", "Yenilik, bilgilenmiş kullanıcı üzerinde bırakılan genel izlenime göre değerlendirilir.", "Tasarımlar sadece küçük ayrıntılarda farklılık gösteriyorsa aynı kabul edilir.", "Tescilsiz tasarımda yenilik, başvuru tarihi esas alınarak değerlendirilir.", "Yenilik değerlendirmesinde tasarımcının seçenek özgürlüğünün derecesi esas ölçüttür."], "answer": 2, "why": ["Yanlış. Mutlak yenilik esastır; aynısının dünyanın herhangi bir yerinde kamuya sunulmamış olması gerekir (SMK m.56/4).", "Yanlış. Bilgilenmiş kullanıcı üzerindeki genel izlenim ölçütü ayırt edici nitelik içindir (SMK m.56/5).", "Doğru. Tasarımlar sadece küçük ayrıntılarda farklılık gösteriyorsa aynı kabul edilir (SMK m.56/4).", "Yanlış. Tescilsiz tasarımda esas alınan tarih, tasarımın kamuya ilk sunulduğu tarihtir (SMK m.56/4-b).", "Yanlış. Seçenek özgürlüğünün derecesi ayırt edici niteliğin değerlendirilmesinde dikkate alınır (SMK m.56/6)."], "ref": "SMK m.56/4"}, {"id": "MRK2-017", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre bir tasarımın ayırt edici niteliğe sahip olup olmadığı değerlendirilirken esas alınan kişi ve ayrıca dikkate alınan husus aşağıdakilerden hangisinde doğru olarak verilmiştir?", "options": ["Ortalama tüketici / ürünün piyasa değeri", "Bilgilenmiş kullanıcı / tasarımcının tasarımı geliştirmede sahip olduğu seçenek özgürlüğünün derecesi", "İlgili sektördeki uzman / tasarımın teknik fonksiyonu", "Tasarımcının kendisi / tasarımın yaratılmasına harcanan emek", "Kurum uzmanı / tasarımın kullanılacağı ürünün Lokarno sınıfı"], "answer": 1, "why": ["Yanlış. Tasarımda ölçüt 'ortalama tüketici' değil 'bilgilenmiş kullanıcı'dır; piyasa değeri ise ölçüt değildir (SMK m.56/5-6).", "Doğru. Genel izlenim bilgilenmiş kullanıcı üzerinden değerlendirilir ve tasarımcının seçenek özgürlüğünün derecesi dikkate alınır (SMK m.56/5-6).", "Yanlış. Ölçüt uzman değildir; teknik fonksiyonun zorunlu kıldığı özellikler ise koruma dışıdır (SMK m.56/5, m.58/4-b).", "Yanlış. Tasarımcının bakış açısı ve harcanan emek kanuni ölçüt değildir (SMK m.56/5-6).", "Yanlış. Ürün adı ve sınıfı koruma kapsamını etkilemez (SMK m.61/3); değerlendirme bilgilenmiş kullanıcıya göre yapılır (SMK m.56/5)."], "ref": "SMK m.56/5-6"}, {"id": "MRK2-018", "exam": "marka", "topic": "Tasarım", "q": "Bir otomobil üreticisi, yalnızca motor bakımı sırasında kaputun açılmasıyla görülebilen bir motor kapağı parçasının tasarımını tescil ettirmek istemektedir. Parça, otomobilin son kullanıcı tarafından normal kullanımında görünmemektedir. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["Bakım sırasında görülebildiği için parça normal kullanımda görünür kabul edilir ve korunur.", "Birleşik ürünün parçaları tasarım olarak hiçbir şekilde korunamaz.", "Parça, bilgilenmiş kullanıcı tarafından görülebildiği sürece yeni ve ayırt edici kabul edilir.", "Parça yalnızca tescilsiz tasarım olarak korunabilir.", "Normal kullanım bakım, servis ve onarım işlerini kapsamadığından parça yeni ve ayırt edici kabul edilemez."], "answer": 4, "why": ["Yanlış. Normal kullanım; bakım, servis veya onarım işleri hariç son kullanıcı tarafından kullanımdır (SMK m.56/3).", "Yanlış. Birleşik ürün parçaları m.56/2'deki şartları taşırsa korunur (SMK m.55/2, m.56/2).", "Yanlış. Ölçüt, parçanın birleşik ürünün normal kullanımında görünür olmasıdır (SMK m.56/2-a).", "Yanlış. Görünürlük şartı tescilli/tescilsiz ayrımı yapılmaksızın yenilik ve ayırt edicilik için aranır (SMK m.56/2).", "Doğru. Parçanın normal kullanımda görünür olması gerekir ve normal kullanım bakım, servis, onarım işlerini kapsamaz (SMK m.56/2-a, m.56/3)."], "ref": "SMK m.56/2-3"}, {"id": "MRK2-019", "exam": "marka", "topic": "Tasarım", "q": "Tasarımın kamuya sunulmasına ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Tasarımın gizlilik şartıyla üçüncü bir kişiye açıklanması kamuya sunma sayılmaz.\nII. Tasarımcının, başvuru tarihinden önceki on iki ay içinde tasarımını kendisinin kamuya sunması, tasarımın yeniliğini ve ayırt edici niteliğini etkilemez.\nIII. Tasarımcı ile olan ilişkinin kötüye kullanımı sonucu bir üçüncü kişinin tasarımı başvurudan önceki on iki ay içinde kamuya sunması, tasarımın yeniliğini ortadan kaldırır.", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 1, "why": ["Yanlış. II de doğrudur; on iki aylık hoşgörü süresi içindeki kendi açıklaması yeniliği etkilemez (SMK m.57/2).", "Doğru. I (SMK m.57/1) ve II (SMK m.57/2) doğrudur; III yanlıştır çünkü ilişkinin kötüye kullanımı sonucu yapılan açıklama da hoşgörü süresi kapsamındadır (SMK m.57/2).", "Yanlış. III yanlıştır; kötüye kullanım sonucu on iki ay içinde yapılan kamuya sunma yenilik ve ayırt ediciliği etkilemez (SMK m.57/2).", "Yanlış. III yanlıştır (SMK m.57/2); I ise doğrudur (SMK m.57/1).", "Yanlış. III yanlış olduğundan tüm öncüller doğru değildir (SMK m.57/2)."], "ref": "SMK m.57"}, {"id": "MRK2-020", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre tescilli bir tasarımın hükümsüzlüğüne ilişkin dava hangi süre içinde açılabilir?", "options": ["Koruma süresince veya tasarım hakkının sona ermesini izleyen beş yıl içinde", "Tescilin yayım tarihinden itibaren üç yıl içinde", "Yalnızca koruma süresi devam ettiği sürece", "Tescil tarihinden itibaren beş yıl içinde", "Tasarımın kamuya ilk sunulduğu tarihten itibaren üç yıl içinde"], "answer": 0, "why": ["Doğru. Hükümsüzlük davası koruma süresince veya tasarım hakkının sona ermesini izleyen beş yıl içinde açılabilir (SMK m.78/3).", "Yanlış. Yayımdan itibaren üç yıllık süre tasarımın gaspı taleplerine ilişkindir (SMK m.71/3).", "Yanlış. Dava, hakkın sona ermesinden sonra da beş yıl içinde açılabilir (SMK m.78/3).", "Yanlış. Süre tescil tarihinden itibaren beş yıl ile sınırlı değildir (SMK m.78/3).", "Yanlış. Üç yıl, tescilsiz tasarımın koruma süresidir (SMK m.69/2); hükümsüzlük davası süresi değildir."], "ref": "SMK m.78/3"}, {"id": "MRK2-021", "exam": "marka", "topic": "Tasarım", "q": "Aşağıdakilerden hangisi SMK'ya göre tasarım koruması kapsamı dışında kalan hâllerden biri değildir?", "options": ["Kamu düzenine veya genel ahlaka aykırı tasarımlar", "Ürünün teknik fonksiyonunun zorunlu kıldığı görünüm özellikleri", "Başka bir ürüne mekanik olarak monte edilmesi için belirli biçim ve boyutlarda üretilmesi zorunlu ürünlerin görünüm özellikleri", "Paris Sözleşmesi m.6 mükerrer 2 kapsamındaki hükümranlık alametlerinin uygunsuz kullanımını içeren tasarımlar", "Yeni ve ayırt edici olmak kaydıyla, modüler bir sistemde birimlerin birbirleriyle çeşitli biçimlerde bağlantı kurmasını sağlayan tasarımlar"], "answer": 4, "why": ["Yanlış. Kamu düzeni veya genel ahlaka aykırı tasarımlar koruma dışıdır (SMK m.58/4-a).", "Yanlış. Teknik fonksiyonun zorunlu kıldığı görünüm özellikleri koruma dışıdır (SMK m.58/4-b).", "Yanlış. Mekanik bağlantı için zorunlu biçim ve boyutlar koruma dışıdır (SMK m.58/4-c).", "Yanlış. Hükümranlık alametlerinin uygunsuz kullanımını içeren tasarımlar koruma dışıdır (SMK m.58/4-ç).", "Doğru. Modüler sistem tasarımları, m.56 şartlarını karşılamak kaydıyla korumadan yararlanır (SMK m.58/5)."], "ref": "SMK m.58"}, {"id": "MRK2-022", "exam": "marka", "topic": "Tasarım", "q": "A, yeni ve ayırt edici bir çanta tasarımını tescil ettirmeden ilk kez Türkiye'de bir fuarda kamuya sunmuştur. Bir yıl sonra B, A'nın tasarımını makul yollarla bilmesi mümkün olmaksızın, bağımsız olarak genel izlenim itibarıyla ayırt edilemeyecek kadar benzer bir çanta tasarlamış ve satışa sunmuştur. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["A, tescilsiz tasarımın üç yıllık koruma süresi dolmadığından B'nin satışlarını her koşulda engelleyebilir.", "A'nın tasarımı Türkiye'de kamuya sunulduğundan koruma süresi beş yıldır ve B'ye karşı dava açabilir.", "B'nin tasarımı kopyalanmış kabul edilmez; A, tescilsiz tasarımına dayanarak B'nin fiillerini engelleyemez.", "Tescilsiz tasarım hiçbir şekilde koruma sağlamadığından A'nın talep hakkı yoktur.", "B, ancak tasarımı A'dan önce tescil ettirirse sorumluluktan kurtulur."], "answer": 2, "why": ["Yanlış. Tescilsiz tasarım yalnızca kopyalamaya karşı koruma sağlar; bağımsız yapılan tasarım kopya sayılmaz (SMK m.59/2).", "Yanlış. Tescilsiz tasarımın koruma süresi kamuya ilk sunulduğu tarihten itibaren üç yıldır (SMK m.69/2).", "Doğru. Korunan tasarımı makul yollarla bilmesi mümkün olmayan tasarımcının bağımsız tasarımı kopyalanmış kabul edilmez (SMK m.59/2).", "Yanlış. Türkiye'de ilk kez kamuya sunulan tasarım tescilsiz tasarım olarak korunur (SMK m.55/4, m.69/2).", "Yanlış. B'nin sorumlu olmaması tescile değil, tasarımın bağımsız olarak yapılmış olmasına dayanır (SMK m.59/2)."], "ref": "SMK m.59/2"}, {"id": "MRK2-023", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre birleşik ürünün görünümüne bağımlı olan parçaların, birleşik ürüne orijinal görünümünü yeniden kazandırmak üzere onarım amacıyla ve kaynağı konusunda yanıltıcı olmamak şartıyla kullanılması, tasarımın piyasaya ilk sürüldüğü tarihten itibaren ne kadar süre sonra tasarım hakkının ihlali sayılmaz?", "options": ["Bir yıl", "İki yıl", "Beş yıl", "Üç yıl", "On yıl"], "answer": 3, "why": ["Yanlış. Kanun bir yıllık süre öngörmez (SMK m.59/4).", "Yanlış. İki yıllık bir süre öngörülmemiştir (SMK m.59/4).", "Yanlış. Beş yıl, tescilli tasarımın her bir koruma dönemidir (SMK m.69/1); onarım istisnası için süre üç yıldır.", "Doğru. Bu parçaların onarım amacıyla piyasaya ilk sürülme tarihinden üç yıl sonra kullanılması ihlal sayılmaz; Bakanlıkça yayımlanan eşdeğer parçalar için ise üç yıl içinde de kullanım ihlal sayılmaz (SMK m.59/4-5).", "Yanlış. On yıllık bir süre öngörülmemiştir (SMK m.59/4)."], "ref": "SMK m.59/4"}, {"id": "MRK2-024", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre tasarım başvurusunda yayımın ertelenmesi talebinde bulunulabilecek azami süre ve bu sürenin başlangıcı aşağıdakilerden hangisidir?", "options": ["Başvuru veya varsa rüçhan tarihinden başlamak üzere otuz ay", "Tescil tarihinden başlamak üzere otuz ay", "Başvuru tarihinden başlamak üzere on sekiz ay", "Başvuru veya varsa rüçhan tarihinden başlamak üzere on iki ay", "Tescil tarihinden başlamak üzere yirmi dört ay"], "answer": 0, "why": ["Doğru. Başvuru sahibi, başvuruyla birlikte, başvuru veya varsa rüçhan tarihinden başlamak üzere otuz ay süreyle yayım erteleme talebinde bulunabilir (SMK m.66/1).", "Yanlış. Süre tescil tarihinden değil, başvuru veya rüçhan tarihinden başlar (SMK m.66/1).", "Yanlış. Süre on sekiz ay değil otuz aydır (SMK m.66/1).", "Yanlış. On iki ay, tasarımdaki hoşgörü süresidir (SMK m.57/2); erteleme süresi otuz aydır.", "Yanlış. Ne başlangıç tarihi ne de süre doğrudur (SMK m.66/1)."], "ref": "SMK m.66/1"}, {"id": "MRK2-025", "exam": "marka", "topic": "Tasarım", "q": "Tasarımda yayımın ertelenmesine ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Yayım erteleme talebi başvuruyla birlikte yapılır.\nII. Yayım erteleme süresi içinde tecavüz davası açılabilmesi için sicil kaydındaki ve başvuru dosyasındaki bilgilerin davalı tarafa bildirilmiş olması şarttır.\nIII. Yayım erteleme talebi çoklu başvurudaki tasarımların yalnızca bir kısmı için yapılamaz.", "options": ["Yalnız I", "Yalnız III", "I ve II", "II ve III", "I, II ve III"], "answer": 2, "why": ["Yanlış. II de doğrudur (SMK m.66/5).", "Yanlış. III yanlıştır; m.66 hükümleri çoklu başvurudaki tasarımların bir kısmı hakkında da uygulanabilir (SMK m.66/7).", "Doğru. I (SMK m.66/1) ve II (SMK m.66/5) doğrudur; III yanlıştır (SMK m.66/7).", "Yanlış. III yanlıştır (SMK m.66/7); I ise doğrudur (SMK m.66/1).", "Yanlış. III yanlış olduğundan tüm öncüller doğru değildir (SMK m.66/7)."], "ref": "SMK m.66"}, {"id": "MRK2-026", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre üçüncü kişilerin bir tasarım tesciline itirazına ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Üçüncü kişiler, başvurunun Bültende yayımından itibaren iki ay içinde başvuruya itiraz eder.", "Üçüncü kişiler, tasarım tescilinin yayım tarihinden itibaren üç ay içinde, ücretini ödeyerek tescil belgesinin verilmesine itiraz edebilir.", "Üçüncü kişilerin itirazı, kararın bildirim tarihinden itibaren iki ay içinde yapılır.", "Üçüncü kişiler tasarım tesciline Kurum nezdinde itiraz edemez; yalnızca hükümsüzlük davası açabilir.", "Üçüncü kişiler, tescil tarihinden itibaren altı ay içinde ücretsiz olarak itiraz edebilir."], "answer": 1, "why": ["Yanlış. Tasarımda itiraz tescilin yayımından sonra yapılır ve süre üç aydır (SMK m.65/1, m.67/2).", "Doğru. Üçüncü kişiler tescilin yayım tarihinden itibaren üç ay içinde ücretini ödeyerek tescil belgesinin verilmesine itiraz edebilir (SMK m.67/2).", "Yanlış. Bildirimden itibaren iki aylık süre, başvuru sahibinin m.64 kararlarına karşı itirazı içindir (SMK m.67/1).", "Yanlış. Üçüncü kişiler Kurum nezdinde itiraz edebilir; itiraz Kurul tarafından incelenir (SMK m.67/2, m.68/1).", "Yanlış. Süre üç aydır ve ücret ödenmezse itiraz yapılmamış sayılır (SMK m.67/2-3)."], "ref": "SMK m.67/2"}, {"id": "MRK2-027", "exam": "marka", "topic": "Tasarım", "q": "SMK m.64/6 uyarınca Kurumun tasarım tescil taleplerini resen reddetme sebepleri arasında aşağıdakilerden hangisi yer almaz?", "options": ["Tasarım veya ürün tanımına uygun olmama", "Kamu düzenine veya genel ahlaka aykırılık", "Ayırt edici niteliğe sahip olmama", "Yeni olmadığının tespit edilmesi", "Başvurunun SMK m.3 kapsamına girmeyen kişilerce yapılmış olması"], "answer": 2, "why": ["Yanlış. Tasarım veya ürün tanımına uygun olmayan talepler reddedilir (SMK m.64/6-a).", "Yanlış. Kamu düzenine veya genel ahlaka aykırı talepler reddedilir (SMK m.64/6-b).", "Doğru. Ayırt edici nitelik eksikliği resen ret sebepleri arasında sayılmamıştır; ancak üçüncü kişi itirazı veya hükümsüzlük davası ile ileri sürülebilir (SMK m.64/6, m.67/2, m.77/1-a).", "Yanlış. Yeni olmadığı tespit edilen tasarımlar Kurumca reddedilir (SMK m.64/6-d).", "Yanlış. m.3 kapsamına girmeyen gerçek veya tüzel kişilerce yapılan talepler reddedilir (SMK m.64/6-c)."], "ref": "SMK m.64/6"}, {"id": "MRK2-028", "exam": "marka", "topic": "Tasarım", "q": "SMK'ya göre tasarımların koruma süresine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Tescilli tasarım: tescil tarihinden itibaren 10 yıl, toplam 20 yıl; tescilsiz tasarım: 3 yıl", "Tescilli tasarım: başvuru tarihinden itibaren 5 yıl, toplam 25 yıl; tescilsiz tasarım: 5 yıl", "Tescilli tasarım: başvuru tarihinden itibaren 10 yıl, süresiz yenilenebilir; tescilsiz tasarım: 3 yıl", "Tescilli tasarım: başvuru tarihinden itibaren 5 yıl, toplam 25 yıl; tescilsiz tasarım: kamuya ilk sunulduğu tarihten itibaren 3 yıl", "Tescilli tasarım: yayım tarihinden itibaren 5 yıl, toplam 15 yıl; tescilsiz tasarım: 1 yıl"], "answer": 3, "why": ["Yanlış. Tescilli tasarımın koruma süresi başvuru tarihinden itibaren beş yıldır ve toplam yirmi beş yıla kadar uzatılabilir (SMK m.69/1).", "Yanlış. Tescilsiz tasarımın koruma süresi beş yıl değil üç yıldır (SMK m.69/2).", "Yanlış. On yıllık ve süresiz yenilenen koruma markalara özgüdür; tasarımda azami süre yirmi beş yıldır (SMK m.69/1).", "Doğru. Tescilli tasarım başvuru tarihinden itibaren beş yıl korunur, beşer yıllık dönemlerle toplam yirmi beş yıla uzatılabilir; tescilsiz tasarım kamuya ilk sunulduğu tarihten itibaren üç yıl korunur (SMK m.69/1-2).", "Yanlış. Süre yayım tarihinden başlamaz; azami süre yirmi beş, tescilsiz koruma üç yıldır (SMK m.69/1-2)."], "ref": "SMK m.69"}, {"id": "MRK2-029", "exam": "marka", "topic": "Madrid Protokolü", "q": "Madrid Protokolü kapsamında yapılan uluslararası marka başvurusuna ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Uluslararası başvuru ancak menşe ofisinde tescil edilmiş bir markaya dayanılarak yapılabilir; ulusal başvuru esas alınamaz.", "Uluslararası başvuru, menşe ofisi aracılığı olmaksızın doğrudan WIPO Uluslararası Bürosuna yapılmak zorundadır.", "Uluslararası tescilin koruma süresi beş yıldır ve beşer yıllık dönemler hâlinde yenilenir.", "Uluslararası başvuru, menşe ofisindeki bir ulusal başvuruya veya tescile dayanılarak yapılabilir ve menşe ofisi aracılığıyla Uluslararası Büroya iletilir.", "Uluslararası başvuru, tek bir başvuru ile yalnızca bir akit tarafın belirlenmesine imkân verir."], "answer": 3, "why": ["Yanlış. Yalnızca tescile dayanma şartı Madrid Anlaşması'nın özelliğidir; Protokol ulusal başvuruya dayanmaya da izin verir.", "Yanlış. Madrid sisteminde uluslararası başvuru menşe ofisi aracılığıyla yapılır.", "Yanlış. Madrid sisteminde uluslararası tescilin koruma süresi on yıldır ve on yıllık dönemler hâlinde yenilenir.", "Doğru. Protokol, menşe ofisindeki başvuruya veya tescile (esas başvuru/tescil) dayanmaya izin verir ve başvuru menşe ofisi üzerinden Uluslararası Büroya sunulur.", "Yanlış. Madrid sisteminin temel amacı, tek başvuru ile birden çok akit tarafın belirlenebilmesidir."], "ref": "Madrid Protokolü"}, {"id": "MRK2-030", "exam": "marka", "topic": "Madrid Protokolü", "q": "Madrid Protokolü kapsamında uluslararası tescil, esas başvuru veya esas tescile uluslararası tescil tarihinden itibaren kaç yıl süreyle bağımlıdır?", "options": ["3 yıl", "5 yıl", "7 yıl", "10 yıl", "1 yıl"], "answer": 1, "why": ["Yanlış. Üç yıl bağımlılık süresi değildir; merkezi saldırı riski beş yıl sürer.", "Doğru. Uluslararası tescil, tescil tarihinden itibaren beş yıl boyunca esas başvuru/tescile bağımlıdır (Madrid Protokolü m.6/3).", "Yanlış. Yedi yıllık bir bağımlılık süresi öngörülmemiştir.", "Yanlış. On yıl, uluslararası tescilin koruma süresidir; bağımlılık süresi beş yıldır.", "Yanlış. Bir yıl (12 ay) ret bildirimi için kural süredir; bağımlılık süresi beş yıldır."], "ref": "Madrid Protokolü m.6"}, {"id": "MRK2-031", "exam": "marka", "topic": "Madrid Protokolü", "q": "Türk şirketi (A), TÜRKPATENT'teki tescilli markasına dayanarak Madrid Protokolü kapsamında uluslararası tescil elde etmiştir. Uluslararası tescil tarihinden altı yıl sonra, bu tarihe kadar hakkında herhangi bir işlem başlatılmamış olan esas tescil, Türkiye'de kullanmama nedeniyle iptal edilmiştir. Bu durumda uluslararası tescil bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Uluslararası tescil, beş yıllık bağımlılık süresi dolduğundan esas tescilin iptalinden etkilenmez.", "Uluslararası tescil, esas tescilin iptal edildiği ölçüde tüm belirlenmiş ülkelerde iptal edilir.", "Uluslararası tescil, yalnızca Türkiye dışındaki belirlenmiş ülkelerde geçerli kalır ve üç ay içinde dönüştürülmesi gerekir.", "Uluslararası tescil askıya alınır ve A'nın yeni bir esas başvuru yapması gerekir.", "Uluslararası tescil, esas tescilin iptalinden itibaren üç ay içinde kendiliğinden sona erer."], "answer": 0, "why": ["Doğru. Bağımlılık uluslararası tescil tarihinden itibaren beş yıl sürer; bu süre içinde başlatılmış bir işlem yoksa, sonradan esas tescilin düşmesi uluslararası tescili etkilemez (Madrid Protokolü m.6/2-3).", "Yanlış. Merkezi saldırı sonucu iptal, ancak beş yıllık süre içinde esas hakkın düşmesi veya bu süre içinde başlatılan işlemler sonucunda gerçekleşir.", "Yanlış. Bağımlılık süresi sona erdiğinden ortada iptal edilmiş bir uluslararası tescil yoktur; dönüştürmeye gerek bulunmaz.", "Yanlış. Madrid sisteminde böyle bir askıya alma ve yeni esas başvuru zorunluluğu öngörülmemiştir.", "Yanlış. Beş yıllık süre dolduktan sonra uluslararası tescil esas tescilden bağımsızdır."], "ref": "Madrid Protokolü m.6"}, {"id": "MRK2-032", "exam": "marka", "topic": "Madrid Protokolü", "q": "Esas başvurunun bağımlılık süresi içinde reddedilmesi nedeniyle (merkezi saldırı) uluslararası tescili iptal edilen marka sahibi, belirlenmiş akit taraflarda dönüştürme (transformation) yoluyla ulusal/bölgesel başvuru yapmak istemektedir. Aşağıdakilerden hangisi doğrudur?", "options": ["Dönüştürme başvurusu iptal tarihinden itibaren bir yıl içinde yapılmalıdır ve yeni başvuru tarihi esas alınır.", "Dönüştürme yalnızca menşe ofisinin bulunduğu ülkede yapılabilir.", "Dönüştürme başvurusu iptal tarihinden itibaren altı ay içinde yapılmalı ve yalnızca rüçhan tarihi korunur.", "Merkezi saldırı ile iptal edilen uluslararası tescil için dönüştürme imkânı bulunmamaktadır.", "Dönüştürme başvurusu iptal tarihinden itibaren üç ay içinde yapılırsa, ilgili akit tarafta uluslararası tescil tarihinde (varsa rüçhan tarihiyle) yapılmış sayılır."], "answer": 4, "why": ["Yanlış. Dönüştürme süresi bir yıl değil üç aydır ve uluslararası tescil tarihi korunur (Madrid Protokolü m.9quinquies).", "Yanlış. Dönüştürme, uluslararası tescilin geçerli olduğu belirlenmiş akit taraflarda yapılır.", "Yanlış. Süre üç aydır ve uluslararası tescil tarihi de korunur (Madrid Protokolü m.9quinquies).", "Yanlış. Dönüştürme, Protokol'ün merkezi saldırının olumsuz sonuçlarını hafifletmek için öngördüğü bir imkândır (Madrid Protokolü m.9quinquies).", "Doğru. İptal tarihinden itibaren üç ay içinde yapılan dönüştürme başvurusu, uluslararası tescil tarihinde ve varsa rüçhan tarihiyle yapılmış sayılır (Madrid Protokolü m.9quinquies)."], "ref": "Madrid Protokolü m.9quinquies"}, {"id": "MRK2-033", "exam": "marka", "topic": "Madrid Protokolü", "q": "Madrid sisteminde, uluslararası tescilden sonra korumanın başvuruda belirlenmemiş yeni bir akit tarafa genişletilmesi için yapılan işlem aşağıdakilerden hangisidir?", "options": ["Dönüştürme", "İkame (replacement)", "Sonradan belirleme", "Merkezi saldırı", "Bölünme"], "answer": 2, "why": ["Yanlış. Dönüştürme, merkezi saldırı ile iptal edilen uluslararası tescilin ulusal başvurulara çevrilmesidir.", "Yanlış. İkame, uluslararası tescilin aynı marka için önceden var olan ulusal tescilin yerini almasıdır.", "Doğru. Sonradan belirleme (subsequent designation) ile uluslararası tescilin koruması sonradan yeni akit taraflara genişletilir.", "Yanlış. Merkezi saldırı, beş yıllık süre içinde esas başvuru/tescilin düşürülmesiyle uluslararası tescilin iptal edilmesidir.", "Yanlış. Bölünme, bir başvurunun mal/hizmetler bakımından ayrılmasıdır; koruma alanını yeni ülkeye genişletmez."], "ref": "Madrid Protokolü"}, {"id": "MRK2-034", "exam": "marka", "topic": "Madrid Protokolü", "q": "Madrid Protokolü'ne göre belirlenmiş bir akit tarafın ofisi, uluslararası tescile ilişkin geçici ret bildirimini kural olarak hangi süre içinde yapmalıdır; akit tarafın beyanı hâlinde bu süre en fazla ne kadar olabilir?", "options": ["6 ay / 12 ay", "12 ay / 24 ay", "18 ay / 30 ay", "12 ay / 18 ay", "3 ay / 6 ay"], "answer": 3, "why": ["Yanlış. Altı ay/on iki ay, Lahey sistemindeki tasarım ret süreleridir; Madrid'de kural süre bir yıldır.", "Yanlış. Beyanla uzatılan süre yirmi dört ay değil on sekiz aydır.", "Yanlış. Kural süre on sekiz ay değil on iki aydır.", "Doğru. Ret bildirimi kural olarak bir yıl (12 ay) içinde yapılır; beyanda bulunan akit taraflar için süre 18 aydır (itiraz kaynaklı retler bu sürenin sonrasında da bildirilebilir) (Madrid Protokolü m.5/2).", "Yanlış. Üç ay/altı ay Madrid sisteminde ret süreleri değildir."], "ref": "Madrid Protokolü m.5/2"}, {"id": "MRK2-035", "exam": "marka", "topic": "Madrid Protokolü", "q": "Madrid sistemi ve SMK'daki ilgili düzenlemeye ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Uluslararası tescil on yıl süreyle geçerlidir ve on yıllık dönemler hâlinde yenilenebilir.\nII. Türkiye'nin belirlendiği bir uluslararası başvuru, Kuruma doğrudan yapılan bir başvuruyla aynı sonuçları doğurur.\nIII. Uluslararası başvuru, kendisinden daha önce Kuruma sunulmuş ancak başvuru veya rüçhan tarihi daha sonra olan bir marka başvurusu nedeniyle reddedilebilir.", "options": ["Yalnız I", "Yalnız II", "I ve III", "I, II ve III", "I ve II"], "answer": 4, "why": ["Yanlış. II de doğrudur (SMK m.14/1).", "Yanlış. I de doğrudur; uluslararası tescil on yıl geçerlidir ve on yıllık dönemlerle yenilenir.", "Yanlış. III yanlıştır; uluslararası başvuru, tarihi kendisinden sonra olan ancak Kuruma daha önce sunulmuş başvuru nedeniyle reddedilemez (SMK m.14/2).", "Yanlış. III yanlış olduğundan tüm öncüller doğru değildir (SMK m.14/2).", "Doğru. I (Madrid Protokolü) ve II (SMK m.14/1) doğrudur; III yanlıştır (SMK m.14/2)."], "ref": "SMK m.14"}, {"id": "MRK2-036", "exam": "marka", "topic": "Nice Anlaşması", "q": "Nice Anlaşması ve SMK'daki sınıflandırma hükümlerine ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Nice sınıflandırması 45 sınıftan oluşur; 1-34. sınıflar mallara ilişkindir.\nII. 35-45. sınıflar hizmetlere ilişkindir.\nIII. Mal veya hizmetlerin aynı sınıfta yer alması benzer olduklarına karine teşkil eder.", "options": ["I ve II", "Yalnız I", "Yalnız III", "II ve III", "I, II ve III"], "answer": 0, "why": ["Doğru. Nice sınıflandırmasında 45 sınıf vardır; 1-34 mal, 35-45 hizmet sınıflarıdır. III yanlıştır (SMK m.11/4).", "Yanlış. II de doğrudur; 35-45. sınıflar hizmet sınıflarıdır.", "Yanlış. III yanlıştır; aynı sınıfta yer alma benzerliğe, farklı sınıfta yer alma da benzememeye karine teşkil etmez (SMK m.11/4).", "Yanlış. III yanlıştır (SMK m.11/4).", "Yanlış. III yanlış olduğundan tüm öncüller doğru değildir (SMK m.11/4)."], "ref": "SMK m.11/3-4; Nice Anlaşması"}, {"id": "MRK2-037", "exam": "marka", "topic": "Viyana Anlaşması", "q": "Markaların şekil (figüratif) unsurlarının uluslararası sınıflandırılmasını düzenleyen anlaşma aşağıdakilerden hangisidir?", "options": ["Nice Anlaşması", "Lokarno Anlaşması", "Viyana Anlaşması", "Lahey Anlaşması", "Strazburg Anlaşması"], "answer": 2, "why": ["Yanlış. Nice Anlaşması markaların tescili amacıyla mal ve hizmetlerin sınıflandırılmasına ilişkindir (SMK m.11/3).", "Yanlış. Lokarno Anlaşması endüstriyel tasarımların sınıflandırılmasına ilişkindir (SMK m.61/5).", "Doğru. Viyana Anlaşması markaların şekil unsurlarının uluslararası sınıflandırmasını (kategori, bölüm, kısım) düzenler.", "Yanlış. Lahey Anlaşması endüstriyel tasarımların uluslararası tescil sistemidir.", "Yanlış. Strazburg Anlaşması patentlerin uluslararası sınıflandırmasına (IPC) ilişkindir."], "ref": "Viyana Anlaşması"}, {"id": "MRK2-038", "exam": "marka", "topic": "Lokarno Anlaşması", "q": "SMK'ya göre çoklu tasarım başvurusuna ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Çoklu başvuruda tasarımların uygulandığı ürünlerin farklı Lokarno sınıflarında yer alması serbesttir.", "Çoklu başvuruda, süslemeler hariç olmak üzere, tasarımın kullanıldığı veya uygulandığı her bir ürünün Lokarno sınıflandırmasına göre aynı sınıfa dâhil olması gerekir.", "Çoklu başvuruyu oluşturan tasarımlar bir bütün olarak değerlendirilir; biri hükümsüz olursa tamamı hükümsüz olur.", "Tasarım ürünleri Nice Anlaşmasına göre sınıflandırılır.", "Başvuruda belirtilen ürün sınıfı tasarımın koruma kapsamını belirler."], "answer": 1, "why": ["Yanlış. Süslemeler hariç, ürünlerin aynı sınıfa dâhil olması gerekir (SMK m.61/7).", "Doğru. Çoklu başvurularda süslemeler hariç her bir ürünün aynı sınıfa dâhil olması gerekir; sınıflandırmada Lokarno Anlaşması uygulanır (SMK m.61/5, m.61/7).", "Yanlış. Çoklu başvuru veya tescili oluşturan tasarımlar ayrı ayrı değerlendirilir (SMK m.61/8).", "Yanlış. Tasarımlarda Lokarno Anlaşması uygulanır; Nice markalar içindir (SMK m.61/5, m.11/3).", "Yanlış. Ürün adı, sınıfı ve tarifnamedeki bilgiler koruma kapsamını etkilemez (SMK m.61/3)."], "ref": "SMK m.61/5, 61/7"}, {"id": "MRK2-039", "exam": "marka", "topic": "Lahey Anlaşması", "q": "Endüstriyel tasarımların uluslararası tesciline ilişkin Lahey sistemi hakkında aşağıdakilerden hangisi yanlıştır?", "options": ["Uluslararası başvuru WIPO Uluslararası Bürosuna doğrudan yapılabilir.", "Tek bir uluslararası başvuru ile birden çok akit tarafta koruma talep edilebilir.", "Tek başvuruda, aynı Lokarno sınıfına ait olmak kaydıyla 100'e kadar tasarım yer alabilir.", "Uluslararası tescil beşer yıllık dönemler hâlinde yenilenebilir.", "Uluslararası başvuru yapılabilmesi için menşe ülkede önceden yapılmış bir ulusal tasarım başvurusu veya tescili bulunması zorunludur."], "answer": 4, "why": ["Yanlış (ifade doğru). Lahey sisteminde başvuru doğrudan Uluslararası Büroya yapılabilir.", "Yanlış (ifade doğru). Lahey sistemi tek başvuru ile birden çok akit tarafta koruma sağlar.", "Yanlış (ifade doğru). Bir uluslararası başvuru, aynı Lokarno sınıfına ait olmak kaydıyla 100'e kadar tasarım içerebilir.", "Yanlış (ifade doğru). Lahey sisteminde uluslararası tescil beşer yıllık dönemler hâlinde yenilenir.", "Doğru (ifade yanlış). Madrid sisteminin aksine Lahey sisteminde esas ulusal başvuru/tescil şartı yoktur."], "ref": "Lahey Anlaşması"}, {"id": "MRK2-040", "exam": "marka", "topic": "Lahey Anlaşması", "q": "Madrid sistemi ile Lahey sistemi karşılaştırıldığında, aşağıdakilerden hangisi Madrid sistemine özgü olup Lahey sisteminde bulunmayan bir özelliktir?", "options": ["Uluslararası tescilin belirli bir süre esas başvuru/tescile bağımlı olması ve merkezi saldırı riski", "Uluslararası tescilin WIPO Uluslararası Bürosunca tutulan sicile kaydedilmesi", "Belirlenen akit tarafın ofisinin belirli bir süre içinde ret bildiriminde bulunabilmesi", "Uluslararası tescilin yenilenebilmesi", "Tek başvuru ile birden çok ülkede koruma talep edilebilmesi"], "answer": 0, "why": ["Doğru. Beş yıllık bağımlılık ve merkezi saldırı Madrid sistemine özgüdür; Lahey sisteminde esas başvuru şartı ve buna bağlı merkezi saldırı yoktur.", "Yanlış. Her iki sistemde de uluslararası tescil WIPO Uluslararası Bürosunca kaydedilir.", "Yanlış. Her iki sistemde de belirlenen ofislerin belirli süre içinde ret bildirme imkânı vardır (Madrid'de 12/18 ay, Lahey'de 6/12 ay).", "Yanlış. Her iki sistemde de uluslararası tescil yenilenebilir (Madrid'de 10 yıl, Lahey'de 5 yıllık dönemler).", "Yanlış. Tek başvuru ile çok ülkede koruma her iki sistemin ortak özelliğidir."], "ref": "Madrid Protokolü m.6; Lahey Anlaşması"}, {"id": "MRK-001", "exam": "marka", "topic": "Marka Olabilecek İşaretler", "q": "6769 sayılı SMK m.4'e göre bir işaretin marka olabilmesi için aranan iki temel şart aşağıdakilerden hangisidir?", "options": ["Ayırt edici olması ve grafik olarak gösterilebilir olması", "Yeni olması ve sanayiye uygulanabilir olması", "Mal veya hizmetleri diğer teşebbüslerinkinden ayırt edebilmesi ve korumanın konusunun açık ve kesin olarak anlaşılmasını sağlayacak şekilde sicilde gösterilebilir olması", "Başvuru tarihinden önce Türkiye'de kullanılmış olması ve ayırt edici olması", "Yalnızca sözcük veya şekilden oluşması ve sicilde gösterilebilir olması"], "answer": 2, "why": ["SMK m.4/1 'grafik gösterim' değil, korumanın konusunun açık ve kesin anlaşılmasını sağlayacak şekilde 'sicilde gösterilebilirlik' ölçütünü benimser.", "Yenilik ve sanayiye uygulanabilirlik patent koruma şartlarıdır; m.4/1 marka için böyle bir şart aramaz.", "Doğru. m.4/1 ayırt edicilik ile sicilde açık ve kesin şekilde gösterilebilirlik şartlarını arar (SMK m.4/1).", "Marka koruması tescil yoluyla elde edilir (m.7/1); önceden kullanım şartı yoktur. Kullanım yalnızca m.5/2'deki kazanılmış ayırt edicilikte önem taşır.", "m.4/1 sözcük ve şekille sınırlı değildir; renkler, harfler, sayılar, sesler ve mal/ambalaj biçimi dâhil her tür işaret marka olabilir."], "ref": "SMK m.4"}, {"id": "MRK-002", "exam": "marka", "topic": "Marka Olabilecek İşaretler", "q": "SMK m.4/1'de marka olabilecek işaretler örnek olarak sayılmıştır. Aşağıdakilerden hangisi bu hükümde açıkça sayılan işaret türleri arasında yer almaz?", "options": ["Kişi adları dâhil sözcükler", "Sesler", "Renkler", "Malların veya ambalajlarının biçimi", "Kokular"], "answer": 4, "why": ["m.4/1'de 'kişi adları dâhil sözcükler' açıkça sayılmıştır.", "Sesler m.4/1'de açıkça sayılan işaretlerdendir.", "Renkler m.4/1'de açıkça sayılmıştır.", "m.4/1 'malların veya ambalajlarının biçimi'ni açıkça sayar; üç boyutlu markalar bu kapsamdadır.", "Doğru. Koku m.4/1'de açıkça sayılmamıştır; ancak hüküm 'her tür işaret' ifadesini kullandığından, m.4 şartlarını sağlayan bir işaret yine marka olabilir (SMK m.4/1)."], "ref": "SMK m.4"}, {"id": "MRK-003", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "Süt ürünleri (Sınıf 29) için yapılan ve yalnızca 'TAZE VE YAĞLI' ibaresinden oluşan bir marka başvurusu, aşağıdaki ret nedenlerinden hangisine en doğrudan şekilde girer?", "options": ["SMK m.5/1-c: Malların cins, vasıf, kalite gibi özelliklerini münhasıran veya esas unsur olarak belirten işaretler", "SMK m.5/1-ç: Önceki tarihli marka ile aynı veya ayırt edilemeyecek kadar benzer işaretler", "SMK m.5/1-e: Teknik bir sonucu elde etmek için zorunlu olan şekiller", "SMK m.5/1-h: Dinî değerleri veya sembolleri içeren işaretler", "SMK m.6/1: Karıştırılma ihtimali"], "answer": 0, "why": ["Doğru. İbare malın vasfını ve niteliğini doğrudan tanımlar; bu tür tanımlayıcı işaretler m.5/1-c kapsamında reddedilir.", "m.5/1-ç önceki tarihli bir tescil veya başvuru ile aynılık hâlini düzenler; olayda böyle bir önceki marka yoktur.", "m.5/1-e malın şekli veya başka bir özelliğine ilişkin işaretleri düzenler; tanımlayıcı bir sözcük işareti bu kapsamda değildir.", "İbarede dinî bir değer veya sembol bulunmadığından m.5/1-h uygulanmaz.", "m.6/1 nispi ret nedenidir ve önceki marka sahibinin itirazını gerektirir; tanımlayıcılıkla ilgisi yoktur."], "ref": "SMK m.5/1-c"}, {"id": "MRK-004", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "Başvuru tarihinden önce kullanılmış ve bu kullanım sonucunda başvuruya konu mal veya hizmetler bakımından ayırt edici nitelik kazanmış bir markanın tescili, SMK m.5/1'in hangi bentlerine göre reddedilemez?", "options": ["(a), (b) ve (c) bentleri", "(b), (c) ve (ç) bentleri", "(c), (d) ve (e) bentleri", "(b), (c) ve (d) bentleri", "(b), (d) ve (f) bentleri"], "answer": 3, "why": ["(a) bendi m.4'e göre marka olamayacak işaretleri kapsar; m.5/2 bu bende atıf yapmaz.", "(ç) bendindeki önceki markayla aynılık engeli kullanımla aşılamaz; bu engel ancak m.5/3'teki noter onaylı muvafakatname ile aşılır.", "(e) bendi (doğası gereği, teknik sonuç için zorunlu veya asli değer veren şekiller) m.5/2 kapsamında değildir.", "Doğru. m.5/2 uyarınca kullanımla kazanılan ayırt edicilik yalnızca (b) ayırt edici olmama, (c) tanımlayıcılık ve (d) ticaret alanında herkesçe kullanılma ret nedenlerini aşar.", "(f) bendindeki halkı yanıltıcılık kullanımla giderilemez; m.5/2 yalnızca (b), (c) ve (d) bentlerini sayar."], "ref": "SMK m.5/2"}, {"id": "MRK-005", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "Bir marka başvurusunun SMK m.5/1-ç bendine göre reddedilmemesi için önceki marka sahibinin muvafakati hangi şekilde Kuruma sunulmalıdır?", "options": ["Taraflarca imzalanmış adi yazılı muvafakatname ile", "Başvurunun tesciline açıkça muvafakat edildiğini gösteren noter onaylı belge ile", "Önceki marka sahibinin Kurum nezdinde sözlü beyanı ile", "Mahkemeden alınacak tespit kararı ile", "Muvafakate gerek yoktur; Kurum (ç) bendini yalnızca itiraz üzerine uygular"], "answer": 1, "why": ["m.5/3 adi yazılı şekli yeterli görmez; belgenin noter onaylı olması gerekir.", "Doğru. m.5/3 uyarınca önceki marka sahibinin açık muvafakatini gösteren noter onaylı belgenin sunulması hâlinde başvuru (ç) bendine göre reddedilemez.", "Sözlü beyan kanunda öngörülmemiştir; m.5/3 noter onaylı belge arar.", "Muvafakat için mahkeme kararı gerekmez; noter onaylı belge yeterlidir (m.5/3).", "m.5/1-ç mutlak ret nedenidir ve Kurumca m.16/1 uyarınca resen incelenir; muvafakatname bu nedenle önem taşır."], "ref": "SMK m.5/3"}, {"id": "MRK-006", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "SMK m.5/1-ç bendi ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Kurum, başvuruyu mutlak ret nedenleri yönünden incelerken bu bendi resen uygular.\nII. Başvurunun yayımından sonra üçüncü kişiler, başvurunun bu bende göre tescil edilemeyeceğine ilişkin görüş sunabilir.\nIII. Önceki marka sahibinin noter onaylı muvafakatnamesi sunulursa başvuru bu bende göre reddedilemez.", "options": ["Yalnız I", "Yalnız II", "I ve III", "II ve III", "I, II ve III"], "answer": 2, "why": ["I doğrudur (m.16/1) ancak III de doğrudur (m.5/3); bu seçenek eksiktir.", "II yanlıştır; m.17/1 üçüncü kişi görüşlerinde m.5/1-ç bendini açıkça hariç tutar.", "Doğru. Kurum m.16/1 uyarınca m.5'i resen inceler; m.5/3 noter onaylı muvafakatnameyi (ç) bendine karşı engel kaldırıcı sayar. II ise m.17/1'deki '(ç) bendi hariç' ifadesi nedeniyle yanlıştır.", "II yanlıştır (m.17/1 (ç) bendini hariç tutar); bu nedenle seçenek doğru olamaz.", "II, m.17/1 nedeniyle yanlış olduğundan öncüllerin tamamı doğru değildir."], "ref": "SMK m.5/1-ç, m.5/3, m.17"}, {"id": "MRK-007", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "X şirketi, yalnızca belirli bir teknik sonucu elde etmek için zorunlu olan üç boyutlu bir ürün şeklini marka olarak tescil ettirmek istemektedir. Şirket, bu şekli başvuru tarihinden önce 15 yıl boyunca yoğun biçimde kullandığını ve tüketicilerin şekli kendisiyle özdeşleştirdiğini ispat etmektedir. Bu durumda aşağıdakilerden hangisi doğrudur?", "options": ["Kazanılmış ayırt edicilik ispatlandığından başvuru tescil edilir.", "Başvuru ancak üçüncü kişilerin itirazı üzerine reddedilebilir.", "Başvuru m.5/1-b'ye göre reddedilir; ancak beş yıllık kullanım ispatlanırsa tescil edilir.", "Şekil markaları SMK'ya göre hiçbir şekilde tescil edilemez.", "Başvuru m.5/1-e uyarınca reddedilir; kullanım yoluyla kazanılan ayırt edicilik bu bent bakımından tescile imkân vermez."], "answer": 4, "why": ["m.5/2 (e) bendine atıf yapmaz; uzun süreli kullanım fonksiyonel şekil engelini ortadan kaldırmaz.", "m.5/1-e mutlak ret nedenidir; Kurum bunu itiraz beklemeksizin m.16/1 uyarınca resen inceler.", "Ret dayanağı (e) bendidir; ayrıca SMK kazanılmış ayırt edicilik için beş yıl gibi asgari bir süre öngörmez.", "m.4/1 malların veya ambalajlarının biçimini marka olabilecek işaretler arasında açıkça sayar; şekil markası kural olarak mümkündür.", "Doğru. m.5/2 kazanılmış ayırt edicilik istisnasını yalnızca (b), (c) ve (d) bentleri için tanır; teknik sonuç için zorunlu şekiller (e bendi) bu istisnadan yararlanamaz."], "ref": "SMK m.5/1-e, m.5/2"}, {"id": "MRK-008", "exam": "marka", "topic": "Mutlak Ret Nedenleri", "q": "Aşağıdakilerden hangisi SMK m.5'te düzenlenen mutlak ret nedenlerinden biri değildir?", "options": ["Tescilli coğrafi işaretten oluşan veya tescilli coğrafi işaret içeren işaretler", "Başkasına ait ticaret unvanını içeren işaretler", "Dinî değerleri veya sembolleri içeren işaretler", "Mal veya hizmetin niteliği, kalitesi veya coğrafi kaynağı konusunda halkı yanıltacak işaretler", "Kamu düzenine veya genel ahlaka aykırı işaretler"], "answer": 1, "why": ["m.5/1-i bendinde mutlak ret nedeni olarak sayılmıştır.", "Doğru. Başkasına ait kişi ismi, ticaret unvanı, fotoğraf, telif hakkı veya diğer fikri mülkiyet hakkını içeren işaretler m.6/6'da nispi ret nedeni olarak düzenlenmiştir; hak sahibinin itirazı gerekir.", "m.5/1-h bendinde mutlak ret nedeni olarak sayılmıştır.", "m.5/1-f bendinde mutlak ret nedeni olarak sayılmıştır.", "m.5/1-ı bendinde mutlak ret nedeni olarak sayılmıştır."], "ref": "SMK m.5, m.6/6"}, {"id": "MRK-009", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "Tescilli bir markanın koruma süresi yenilenmediği için sona ermiştir. Üçüncü bir kişi, bu markayla aynı işaret için aynı mallarda başvuru yapmıştır. SMK m.6/8'e göre önceki marka sahibinin itirazının kabul edilebilmesi için aşağıdakilerden hangisi gereklidir?", "options": ["Başvurunun koruma süresinin sona ermesinden itibaren iki yıl içinde yapılmış olması ve markanın bu iki yıllık süre içinde kullanılmış olması", "Başvurunun üç yıl içinde yapılmış olması; kullanım şartı aranmaz", "Başvurunun altı ay içinde yapılmış olması; kullanım şartı aranmaz", "Başvurunun beş yıl içinde yapılmış olması ve markanın Türkiye'de tanınmış olması", "Başvurunun bir yıl içinde yapılmış olması ve marka sahibinin yenileme ücretini sonradan ödemiş olması"], "answer": 0, "why": ["Doğru. m.6/8: yenilenmeme nedeniyle sona ermeden itibaren iki yıl içinde yapılan başvuru, markanın bu iki yıl içinde kullanılmış olması şartıyla itiraz üzerine reddedilir.", "Üç yıllık süre m.6/7'de ortak marka ve garanti markası için öngörülmüştür; m.6/8 ise iki yıl ve kullanım şartı arar.", "Altı ay m.23/2'deki ek ücretli yenileme süresidir; m.6/8'deki süre iki yıldır ve kullanım şartı vardır.", "m.6/8'de beş yıllık süre ve tanınmışlık şartı yoktur; süre iki yıl, şart bu sürede kullanımdır.", "m.6/8'de bir yıllık süre veya sonradan ücret ödeme şartı öngörülmemiştir."], "ref": "SMK m.6/8"}, {"id": "MRK-010", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "Ortak markanın veya garanti markasının yenilenmeme sebebiyle koruma süresinin sona ermesinden itibaren kaç yıl içinde yapılan, bu markayla aynı veya benzer olan ve aynı veya benzer mal veya hizmetleri içeren marka başvurusu, önceki hak sahibinin itirazı üzerine reddedilir?", "options": ["1 yıl", "2 yıl", "3 yıl", "5 yıl", "10 yıl"], "answer": 2, "why": ["SMK'da bu durum için bir yıllık süre öngörülmemiştir; m.6/7'deki süre üç yıldır.", "İki yıllık süre m.6/8'de bireysel tescilli markalar için öngörülmüştür; ortak ve garanti markaları için süre üç yıldır.", "Doğru. m.6/7 uyarınca ortak marka veya garanti markası için bu süre üç yıldır.", "Beş yıl, kullanmama (m.9/1) ve sessiz kalma (m.25/6) hükümlerindeki süredir; m.6/7'deki süre üç yıldır.", "On yıl markanın koruma süresidir (m.23/1); m.6/7'deki süre üç yıldır."], "ref": "SMK m.6/7"}, {"id": "MRK-011", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "Tanınmış markalara ilişkin SMK m.6 hükümleri bakımından aşağıdaki ifadelerden hangileri doğrudur?\nI. Paris Sözleşmesinin 1 inci mükerrer 6 ncı maddesi anlamında tanınmış markaya dayalı itiraz (m.6/4), aynı veya benzer mal veya hizmetler bakımından ileri sürülebilir.\nII. m.6/5'e dayalı itirazda, başvurunun farklı mal veya hizmetler için yapılmış olması itirazın kabulüne engel değildir.\nIII. m.6/5'e dayalı itirazın kabulü için önceki markanın yalnızca yurt dışında tanınmış olması yeterlidir; Türkiye'deki tanınmışlık düzeyi aranmaz.", "options": ["Yalnız II", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 1, "why": ["II doğrudur ancak I de doğrudur; m.6/4 açıkça 'aynı veya benzer mal veya hizmetler bakımından' ifadesini kullanır.", "Doğru. m.6/4 aynı veya benzer mal ve hizmetlerle sınırlıdır; m.6/5 ise aynı, benzer veya farklı mal ve hizmetlerde uygulanır. III yanlıştır, çünkü m.6/5 markanın 'Türkiye'de ulaştığı tanınmışlık düzeyi'ni esas alır.", "III yanlıştır; m.6/5 tanınmışlığın Türkiye'deki düzeyini arar.", "III, m.6/5'teki 'Türkiye'de ulaştığı tanınmışlık düzeyi' ifadesine aykırı olduğundan yanlıştır.", "III yanlış olduğundan öncüllerin tamamı doğru değildir."], "ref": "SMK m.6/4, m.6/5"}, {"id": "MRK-012", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "SMK'ya göre kötüniyetle yapılan marka başvuruları ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Kurum tarafından resen incelenerek reddedilir.", "Yalnızca tescilden sonra mahkemede hükümsüzlük davası yoluyla ileri sürülebilir.", "Yalnızca önceki tarihli tescilli marka sahibi tarafından ileri sürülebilir.", "İtiraz üzerine reddedilir; kötüniyet nispi ret nedenleri arasında düzenlenmiştir.", "Üçüncü kişi görüşü (m.17) yoluyla ileri sürülürse Kurum başvuruyu reddetmek zorundadır."], "answer": 3, "why": ["Kötüniyet m.5'te değil m.6/9'da düzenlenmiştir; Kurum bunu resen değil itiraz üzerine inceler.", "m.6/9 yayıma itiraz aşamasında ileri sürülebilir; tescilden sonra ise m.25/1 uyarınca hükümsüzlük sebebi olur. Dava yoluyla sınırlı değildir.", "m.6/9 itiraz edenin tescilli marka sahibi olmasını aramaz; yayıma itiraz 'ilgili kişiler' tarafından yapılabilir (m.18/1).", "Doğru. m.6/9: 'Kötüniyetle yapılan marka başvuruları itiraz üzerine reddedilir.'", "m.17/1'e göre görüşler yalnızca m.5/1 kapsamındaki ((ç) bendi hariç) nedenlere dayanabilir; m.6/9 bu kapsamda değildir."], "ref": "SMK m.6/9"}, {"id": "MRK-013", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "Almanya'da tescilli 'ALFA' markasının sahibi A şirketinin Türkiye distribütörü B, A'nın izni olmaksızın ve haklı bir sebebe dayanmaksızın 'ALFA' markasını kendi adına Türkiye'de tescil ettirmiştir. A şirketinin bu durumda mahkemeden talep edebilecekleri bakımından aşağıdakilerden hangisi SMK'ya en uygundur?", "options": ["Yalnızca tescilin hükümsüzlüğünü talep edebilir; devir talep edemez.", "Ancak Türkiye'de tescilli bir markası varsa talepte bulunabilir.", "Markanın kullanımının yasaklanmasını talep edebileceği gibi tescilin kendisine devredilmesini de talep edebilir.", "Talebini Kuruma yapmalıdır; mahkemeye başvuramaz.", "Yalnızca tazminat talep edebilir."], "answer": 2, "why": ["m.10/1 tescilin devrini talep imkânını açıkça tanır; hükümsüzlük tek seçenek değildir.", "m.10/1 ve m.6/2'de A'nın Türkiye'de tescilli markasının bulunması şartı aranmaz; korunan, marka sahibi ile ticari vekil arasındaki ilişkidir.", "Doğru. m.10/1: ticari vekil veya temsilci adına izinsiz tescilde, haklı sebep yoksa marka sahibi mahkemeden kullanımın yasaklanmasını ve tescilin kendisine devrini talep edebilir.", "m.10/1 bu talepler için açıkça 'mahkemeden' ifadesini kullanır.", "m.10/1 kullanımın yasaklanması ve tescilin devri taleplerini düzenler; A'nın talepleri tazminatla sınırlı değildir."], "ref": "SMK m.6/2, m.10"}, {"id": "MRK-014", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "SMK m.6/3'e göre tescilsiz bir marka veya ticaret sırasında kullanılan bir başka işarete dayanılarak bir marka başvurusuna itiraz edilebilmesi için bu işaret üzerindeki hakkın hangi tarihten önce elde edilmiş olması gerekir?", "options": ["Başvurunun Bültende yayımlandığı tarihten önce", "İtiraz tarihinden önce", "Başvuru tarihinden en az beş yıl önce", "İtiraza konu markanın tescil tarihinden önce", "Başvuru tarihinden veya varsa rüçhan tarihinden önce"], "answer": 4, "why": ["Yayım tarihi ölçüt değildir; m.6/3 başvuru veya rüçhan tarihini esas alır.", "m.6/3 itiraz tarihini değil, itiraza konu başvurunun başvuru veya rüçhan tarihini esas alır.", "m.6/3'te beş yıllık asgari süre yoktur; beş yıl m.19/2'deki kullanım ispatına ilişkindir.", "Tescil tarihi değil, başvuru veya varsa rüçhan tarihi esas alınır (m.6/3).", "Doğru. m.6/3 hakkın 'başvuru tarihinden veya varsa rüçhan tarihinden önce' elde edilmiş olmasını arar."], "ref": "SMK m.6/3"}, {"id": "MRK-015", "exam": "marka", "topic": "Nispi Ret Nedenleri", "q": "Aşağıdakilerden hangisi SMK m.6/6 kapsamında, hak sahibinin itirazı üzerine marka başvurusunun reddine yol açabilecek haklar arasında sayılmaz?", "options": ["Tescilli bir coğrafi işaret", "Başkasına ait kişi ismi", "Başkasına ait ticaret unvanı", "Başkasına ait fotoğraf", "Başkasına ait telif hakkı"], "answer": 0, "why": ["Doğru. Tescilli coğrafi işaretten oluşan veya bunu içeren işaretler m.5/1-i'de mutlak ret nedeni olarak düzenlenmiştir; m.6/6'da sayılmaz.", "Kişi ismi m.6/6'da açıkça sayılmıştır.", "Ticaret unvanı m.6/6'da açıkça sayılmıştır.", "Fotoğraf m.6/6'da açıkça sayılmıştır.", "Telif hakkı m.6/6'da sayılmıştır; ayrıca 'herhangi bir fikri mülkiyet hakkı' da kapsama dâhildir."], "ref": "SMK m.6/6, m.5/1-i"}, {"id": "MRK-016", "exam": "marka", "topic": "Başvuru Şartları ve Başvuru Tarihi", "q": "Bir marka başvurusunda aşağıdaki eksikliklerden hangisinin sonradan giderilmesi, başvuru tarihinin eksikliğin giderildiği tarih, saat ve dakikaya kaymasına yol açmaz?", "options": ["Marka örneğinin bulunmaması", "Mal veya hizmet listesinin bulunmaması", "Başvuru ücretinin ödendiğini gösterir bilginin bulunmaması", "Marka örneğinde kullanılan Latin alfabesi dışındaki harflerin Latin alfabesindeki karşılığının verilmemesi", "Başvuru sahibinin kimliğine ilişkin bilgileri içeren başvuru formunun eksik olması"], "answer": 3, "why": ["m.11/1-b eksikliğidir; m.15/2 uyarınca başvuru tarihi eksikliğin giderildiği an itibarıyla kesinleşir.", "m.11/1-c eksikliğidir; m.15/2'ye göre başvuru tarihini etkiler.", "m.11/1-ç eksikliğidir; m.15/2'ye göre başvuru tarihini etkiler.", "Doğru. Bu eksiklik m.11/1-f kapsamındadır; m.15/2'ye göre (d), (e) ve (f) bentlerine ilişkin eksiklikler başvuru tarihinin kesinleşmesini etkilemez.", "m.11/1-a eksikliğidir; m.15/2'ye göre başvuru tarihi eksikliğin giderildiği tarihe kayar."], "ref": "SMK m.11/1, m.15/2"}, {"id": "MRK-017", "exam": "marka", "topic": "Başvuru Şartları ve Başvuru Tarihi", "q": "Kurumun şeklî inceleme sonucunda marka başvurusunda eksiklik tespit etmesi hâlinde başvuru sahibine verilen süre ve bu süre içinde eksikliğin giderilmemesinin sonucu aşağıdakilerden hangisinde doğru olarak verilmiştir?", "options": ["Bir ay; başvuru reddedilir", "İki ay; başvuru işlemden kaldırılır", "Üç ay; başvuru işlemden kaldırılır", "İki ay; başvuru eksiklik giderilene kadar askıya alınır", "Altı ay; başvuru reddedilir"], "answer": 1, "why": ["Süre bir ay değil iki aydır; sonuç da 'ret' değil 'işlemden kaldırma'dır (m.15/1, m.15/3).", "Doğru. m.15/1 eksikliğin giderilmesi için iki ay süre verir; m.15/3'e göre süresinde giderilmeyen başvuru işlemden kaldırılır.", "Üç ay m.13/1'deki rüçhan hakkı belgesinin sunulma süresidir; şeklî eksiklik süresi iki aydır.", "Kanunda askıya alma öngörülmemiştir; süresinde giderilmeyen başvuru işlemden kaldırılır (m.15/3).", "Altı ay m.32/6'daki teknik şartnamenin düzeltilmesi süresidir; şeklî eksiklik süresi iki aydır."], "ref": "SMK m.15"}, {"id": "MRK-018", "exam": "marka", "topic": "Başvuru Şartları ve Başvuru Tarihi", "q": "Marka başvurusuna ilişkin aşağıdaki ifadelerden hangileri SMK'ya göre doğrudur?\nI. Her başvuruyla sadece bir markanın tescili talep edilebilir.\nII. Mal veya hizmetlerin aynı sınıfta yer alması, benzer olduklarına karine teşkil eder.\nIII. Marka başvurusu, başvuru sahibinin talebi üzerine, tescil edilene kadar mal veya hizmetler bakımından iki ya da daha fazla başvuruya bölünebilir.", "options": ["Yalnız III", "I ve II", "II ve III", "I, II ve III", "I ve III"], "answer": 4, "why": ["III doğrudur (m.11/5) ancak I de doğrudur (m.11/2); seçenek eksiktir.", "II yanlıştır; m.11/4'e göre aynı sınıfta yer alma benzerliğe karine teşkil etmez.", "II yanlıştır (m.11/4); ayrıca I doğru olduğu hâlde seçenekte yer almaz.", "II, m.11/4'e aykırı olduğundan öncüllerin tamamı doğru değildir.", "Doğru. m.11/2 tek marka kuralını, m.11/5 tescile kadar bölünmeyi düzenler; m.11/4 ise aynı sınıfta yer almanın benzerlik karinesi olmadığını öngörür."], "ref": "SMK m.11"}, {"id": "MRK-019", "exam": "marka", "topic": "Rüçhan Hakkı", "q": "Paris Sözleşmesine taraf bir ülkede usulüne uygun ilk marka başvurusunu yapan kişi, aynı marka ve aynı mal/hizmetler için Türkiye'de rüçhan hakkından yararlanmak istemektedir. Aşağıdakilerden hangisi doğrudur?", "options": ["Türkiye başvurusunu ilk başvuru tarihinden itibaren on iki ay içinde yapmalıdır.", "Rüçhan hakkı belgesini Türkiye başvuru tarihinden itibaren altı ay içinde Kuruma vermelidir.", "Türkiye başvurusunu ilk başvuru tarihinden itibaren altı ay içinde yapmalı ve ilk başvuru yapılan devletin yetkili makamından rüçhan hakkı belgesi almalıdır.", "Rüçhan talebini başvurudan sonra tescile kadar her zaman yapabilir.", "Altı aylık süre içinde kullanılmayan rüçhan hakkı Kurum kararıyla bir kez uzatılabilir."], "answer": 2, "why": ["Marka için rüçhan süresi on iki ay değil altı aydır (m.12/1).", "Rüçhan belgesi başvuru tarihinden itibaren üç ay içinde verilmelidir; aksi hâlde talep yapılmamış sayılır (m.13/1).", "Doğru. m.12/1: marka rüçhan süresi ilk başvuru tarihinden itibaren altı aydır ve rüçhan hakkı belgesi alınması şarttır.", "m.13/1'e göre rüçhan hakkı başvuruyla birlikte, talep ücreti ödenerek belirtilir.", "m.12/1'e göre bu süre içinde kullanılmayan rüçhan hakları düşer; uzatma öngörülmemiştir."], "ref": "SMK m.12/1, m.13/1"}, {"id": "MRK-020", "exam": "marka", "topic": "Rüçhan Hakkı", "q": "Rüçhan hakkı talebiyle yapılan bir marka başvurusunda rüçhan hakkı belgesi, başvuru tarihinden itibaren hangi süre içinde Kuruma verilmezse rüçhan hakkı talebi yapılmamış sayılır?", "options": ["2 ay", "3 ay", "4 ay", "6 ay", "1 yıl"], "answer": 1, "why": ["İki ay şeklî eksikliklerin giderilmesi (m.15/1) ve yayıma itiraz (m.18/1) süresidir; rüçhan belgesi için süre üç aydır.", "Doğru. m.13/1: belge başvuru tarihinden itibaren üç ay içinde verilmezse rüçhan hakkı talebi yapılmamış sayılır.", "Kanunda dört aylık bir süre yoktur; süre üç aydır (m.13/1).", "Altı ay rüçhan hakkının kendi süresidir (m.12/1); belgenin sunulma süresi üç aydır.", "Bir yıl marka rüçhanına ilişkin bir süre değildir; m.13/1 üç ay öngörür."], "ref": "SMK m.13/1"}, {"id": "MRK-021", "exam": "marka", "topic": "Rüçhan Hakkı", "q": "Bir işletme, markasını taşıyan ürünleri Türkiye'de açılan uluslararası bir sergide, serginin resmî açılış tarihinden önce, 1 Mart'ta markayla birlikte görünür şekilde sergiye koymuştur. Sergi 15 Mart'ta resmî olarak açılmıştır. Sergi rüçhanı süresi ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Altı aylık süre, malların sergiye konulduğu 1 Mart tarihinden itibaren başlar.", "Altı aylık süre, serginin resmî açılış tarihi olan 15 Mart'tan itibaren başlar.", "On iki aylık süre, 1 Mart'tan itibaren başlar.", "Üç aylık süre, serginin kapanış tarihinden itibaren başlar.", "Sergi rüçhanından yalnızca yabancı ülkelerde açılan sergiler için yararlanılabilir."], "answer": 0, "why": ["Doğru. m.12/3 teşhir tarihinden itibaren altı ay öngörür; m.12/4'e göre resmî açılıştan önce görünür şekilde teşhirde süre malların sergiye konulduğu tarihten başlar.", "m.12/4, resmî açılıştan önce teşhir hâlinde sürenin malların sergiye konulduğu tarihten başlayacağını öngörür.", "Marka için sergi rüçhanı süresi altı aydır (m.12/3).", "Kanunda kapanış tarihi veya üç aylık süre öngörülmemiştir (m.12/3-4).", "m.12/3 Türkiye'de açılan ulusal veya uluslararası sergileri açıkça kapsar."], "ref": "SMK m.12/3-4"}, {"id": "MRK-022", "exam": "marka", "topic": "Rüçhan Hakkı", "q": "Bir marka başvurusu için birden fazla rüçhan hakkı talep edilmesi durumunda rüçhan hakkı hangi tarih itibarıyla başlar?", "options": ["En son rüçhan tarihi itibarıyla", "Türkiye'deki başvuru tarihi itibarıyla", "Birden fazla rüçhan hakkı talep edilemez.", "Başvuru sahibinin seçeceği rüçhan tarihi itibarıyla", "Geçerli olan ilk rüçhan tarihi itibarıyla"], "answer": 4, "why": ["m.13/3 son tarihi değil, geçerli olan ilk rüçhan tarihini esas alır.", "Rüçhanın amacı önceki tarihten yararlanmaktır; m.13/3 geçerli ilk rüçhan tarihini esas alır.", "m.13/3 birden fazla rüçhan talebini açıkça mümkün kılar.", "Kanun seçim hakkı tanımaz; geçerli olan ilk rüçhan tarihi esas alınır (m.13/3).", "Doğru. m.13/3: birden fazla rüçhan talebinde rüçhan hakkı geçerli olan ilk rüçhan tarihi itibarıyla başlar."], "ref": "SMK m.13/3"}, {"id": "MRK-023", "exam": "marka", "topic": "Üçüncü Kişi Görüşleri", "q": "SMK m.17'de düzenlenen üçüncü kişilerin görüşleri ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Görüşler, başvurunun yayımlanmasından sonra markanın tesciline kadar sunulabilir.", "Görüşler yazılı ve gerekçeli olmalıdır.", "Görüşler, m.5/1-ç bendi hariç m.5/1'deki diğer bentlere dayandırılabilir.", "Görüş sunan kişi, Kurum nezdindeki işlemlere taraf olur ve verilen karara itiraz edebilir.", "Kurum görüşleri yerinde bulursa başvuruyu kısmen veya tamamen reddeder."], "answer": 3, "why": ["Doğru ifadedir; m.17/1 görüş sunma imkânını yayımdan tescile kadar tanır.", "Doğru ifadedir; m.17/1 'yazılı ve gerekçeli görüş' arar.", "Doğru ifadedir; m.17/1 (ç) bendini hariç tutar.", "Yanlış ifade budur. m.17/1'e göre görüş sunan kişiler Kurum nezdinde işlemlere taraf olamaz.", "Doğru ifadedir (m.17/2)."], "ref": "SMK m.17"}, {"id": "MRK-024", "exam": "marka", "topic": "Yayıma İtiraz", "q": "Bültende yayımlanan bir marka başvurusuna yapılacak yayıma itirazla ilgili aşağıdakilerden hangisi doğrudur?", "options": ["İtiraz süresi yayımdan itibaren üç aydır.", "İtiraz, yayımdan itibaren iki ay içinde yazılı ve gerekçeli yapılmalı; itiraz ücreti de aynı süre içinde ödenmeli ve ödendiğine ilişkin bilgi Kuruma sunulmalıdır.", "İtiraz gerekçeleri, itiraz süresi geçtikten sonra da sunulabilir.", "Yayıma itiraz yalnızca m.6'daki nispi ret nedenlerine dayandırılabilir.", "İtiraz ücreti, Kurumun sonradan vereceği süre içinde ödenebilir."], "answer": 1, "why": ["SMK m.18/1'deki yayıma itiraz süresi üç ay değil, iki aydır.", "Doğru. m.18/1 iki aylık itiraz süresini, m.18/2 yazılı-gerekçeli itiraz ile ücretin süre içinde ödenmesi ve bilginin sunulması zorunluluğunu düzenler.", "m.18/2: gerekçelerin iki aylık süre içinde sunulmaması hâlinde itiraz yapılmamış sayılır.", "m.18/1 itirazın m.5 veya m.6'ya dayandırılabileceğini öngörür.", "m.18/2 ücretin itiraz süresi içinde ödenmesini ve bilginin aynı süre içinde sunulmasını zorunlu kılar."], "ref": "SMK m.18"}, {"id": "MRK-025", "exam": "marka", "topic": "Kullanım İspatı", "q": "A'nın 'BETA' markası 1 Mart 2019 tarihinde Türkiye'de tescil edilmiştir. B, 1 Şubat 2024 tarihinde benzer mallar için 'BETTA' markası başvurusu yapmış; A, m.6/1'e dayanarak yayıma itiraz etmiştir. B, A'nın markasını kullandığını ispat etmesini talep etmektedir. SMK m.19/2'ye göre aşağıdakilerden hangisi doğrudur?", "options": ["A'nın markası B'nin başvuru tarihinde en az beş yıldır tescilli olmadığından A'dan kullanım ispatı istenemez.", "Kurum, B'nin talebi üzerine A'dan son beş yıldaki kullanımını ispat etmesini ister.", "Kullanım ispatı B'nin talebi olmasa da Kurum tarafından resen istenir.", "Beş yıllık süre itiraz tarihine göre hesaplanır; bu nedenle ispat istenebilir.", "A'nın itirazı, kullanım ispatı yapılmadığından doğrudan reddedilir."], "answer": 0, "why": ["Doğru. m.19/2 kullanım ispatını, itiraz gerekçesi markanın itiraza konu başvurunun başvuru veya rüçhan tarihinde Türkiye'de en az beş yıldır tescilli olması şartına bağlar; 1.3.2019 ile 1.2.2024 arası beş yılı doldurmaz.", "Beş yıllık tescil şartı gerçekleşmediğinden kullanım ispatı istenemez (m.19/2).", "m.19/2'ye göre kullanım ispatı ancak başvuru sahibinin talebi üzerine istenir; ayrıca olayda beş yıllık tescil şartı da yoktur.", "Yayıma itirazda ölçüt itiraz tarihi değil, itiraza konu başvurunun başvuru veya rüçhan tarihidir (m.19/2). Dava tarihi ölçütü hükümsüzlük ve tecavüz davalarındaki def'iler içindir (m.25/7, m.29/2).", "Kullanım ispatı istenemeyeceğinden ispat edilememe sonucu da doğmaz; itiraz esastan incelenir."], "ref": "SMK m.19/2"}, {"id": "MRK-026", "exam": "marka", "topic": "Karara İtiraz", "q": "Kurumun marka başvurusuna ilişkin kararına karşı Kurum nezdinde yapılacak itirazla ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Kararlardan zarar gören taraflar, kararlara karşı Kurum nezdinde itiraz edebilir.", "İtiraz, kararın bildirim tarihinden itibaren iki ay içinde yazılı ve gerekçeli olarak yapılır.", "Şeklî eksiklik içermeyen itirazlar Kurul tarafından incelenir.", "Kurul, itiraz hakkında yaptığı inceleme sonucunda Kurumun nihai kararını verir.", "İtiraz süresi geçtikten sonra da itiraz gerekçeleri değiştirilebilir ve yeni gerekçeler eklenebilir."], "answer": 4, "why": ["Doğru ifadedir (m.20/1).", "Doğru ifadedir (m.20/2).", "Doğru ifadedir (m.21/1).", "Doğru ifadedir (m.21/4).", "Yanlış ifade budur. m.20/2'nin son cümlesine göre itiraz süresinden sonra gerekçeler değiştirilemez ve yeni gerekçe eklenemez."], "ref": "SMK m.20, m.21"}, {"id": "MRK-027", "exam": "marka", "topic": "Tescil", "q": "Bir marka, yayıma itiraz aşaması tamamlanmadan sehven tescil edilmiştir. SMK m.22/2'ye göre aşağıdakilerden hangisi doğrudur?", "options": ["Tescil kesinleşmiştir; eksiklik ancak hükümsüzlük davasıyla ileri sürülebilir.", "İşlemler yeniden başlatılır ve tekrar tescil kararı verilirse tescil ücreti yeniden alınır.", "Marka tescilli marka olarak kabul edilmez ve işlemler tamamlanmayan aşamadan devam ettirilir; ancak tescil tarihinden itibaren iki yıl geçmişse tescil durumu bu eksiklikten etkilenmez.", "Tescil tarihinden itibaren beş yıl geçmişse tescil durumu etkilenmez.", "Bu durum Bültende yayımlanmaz, yalnızca taraflara bildirilir."], "answer": 2, "why": ["m.22/2, markanın tescilli kabul edilmeyeceğini ve işlemlere tamamlanmayan aşamadan devam edileceğini öngörür.", "m.22/2: tekrar tescil kararı verilirse daha önce ödenen tescil ücreti tekrar talep edilmez.", "Doğru. m.22/2 aşamalardan biri tamamlanmadan yapılan tescili tescilli marka saymaz; ancak tescil tarihinden itibaren iki yıl geçmişse tescil durumu etkilenmez.", "m.22/2'deki süre beş yıl değil iki yıldır.", "m.22/2 bu durumun Bültende yayımlanmasını öngörür."], "ref": "SMK m.22/2"}, {"id": "MRK-028", "exam": "marka", "topic": "Koruma Süresi ve Yenileme", "q": "Başvuru tarihi 20 Nisan 2016 olan ve 2017 yılında tescil edilen bir markanın koruma süresi ve yenilenmesi ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Koruma süresi tescil tarihinden itibaren on yıl olarak hesaplanır.", "Yenileme talebi koruma süresinin bitiminden önceki bir yıl içinde yapılmalıdır.", "Süre kaçırılırsa ek ücretle bir yıl içinde yenileme yapılabilir.", "Koruma süresi 20 Nisan 2026'da sona erer; yenileme bu tarihten önceki altı ay içinde, bu süre kaçırılırsa sona erme tarihinden itibaren altı ay içinde ek ücretle yapılabilir.", "Yenileme yirmi yıllık dönemler hâlinde yapılır."], "answer": 3, "why": ["m.23/1'e göre süre tescil tarihinden değil, başvuru tarihinden itibaren on yıldır.", "Yenileme süresi sona ermeden önceki altı aydır (m.23/2).", "Ek ücretli yenileme süresi bir yıl değil, altı aydır (m.23/2).", "Doğru. m.23/1 koruma süresini başvuru tarihinden itibaren on yıl olarak belirler; m.23/2 sona ermeden önceki altı ay ile sonrasındaki altı aylık ek ücretli süreyi düzenler.", "m.23/1: koruma süresi onar yıllık dönemler hâlinde yenilenir."], "ref": "SMK m.23"}, {"id": "MRK-029", "exam": "marka", "topic": "Koruma Süresi ve Yenileme", "q": "Marka yenilemesine ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Marka, tescil kapsamındaki mal veya hizmetlerin bir kısmı için de yenilenebilir.\nII. Ortak markanın yenilenmesi için gruba dâhil işletmelerin tümünün birlikte talepte bulunması gerekir.\nIII. Yenileme, önceki koruma süresinin sona erdiği tarihi izleyen günden itibaren hüküm ifade eder.", "options": ["Yalnız I", "Yalnız III", "I ve II", "I ve III", "I, II ve III"], "answer": 3, "why": ["I doğrudur (m.23/3) ancak III de doğrudur (m.23/5); seçenek eksiktir.", "III doğrudur (m.23/5) ancak I de doğrudur (m.23/3); seçenek eksiktir.", "II yanlıştır; m.23/4 ortak markanın yenilenmesi için gruba dâhil işletmelerden birinin talebini yeterli sayar.", "Doğru. m.23/3 kısmi yenilemeye izin verir, m.23/5 yenilemenin izleyen günden itibaren etkili olacağını öngörür. II ise m.23/4'e aykırıdır; tüm işletmelerin birlikte hareketi tescil ve vazgeçme için aranır (m.32/3).", "II yanlış olduğundan öncüllerin tamamı doğru değildir (m.23/4)."], "ref": "SMK m.23"}, {"id": "MRK-030", "exam": "marka", "topic": "Marka Hakkının Kapsamı", "q": "Marka tescilinden doğan hakların üçüncü kişilere karşı hüküm ifade etmesi ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Haklar başvuru tarihinden itibaren hüküm ifade eder ve başvuru sahibi tescilden önce tecavüz nedeniyle hüküm alabilir.", "Haklar tescilin yayım tarihi itibarıyla hüküm ifade eder; ancak başvurunun Bültende yayımından sonraki fiiller için başvuru sahibi tazminat davası açabilir, mahkeme ise tescilin yayımından önce karar veremez.", "Başvurunun Bültende yayımından önceki fiiller için de tazminat davası açılabilir.", "Başvuru sahibi, tescil yayımlanana kadar hiçbir dava açamaz.", "Haklar, tescil ücretinin ödendiği tarihten itibaren hüküm ifade eder."], "answer": 1, "why": ["m.7/4 başlangıç olarak tescilin yayım tarihini esas alır; mahkeme tescilin yayımından önce karar veremez.", "Doğru. m.7/4 bu üç kuralı birlikte düzenler.", "m.7/4 tazminat davasını başvurunun Bültende yayımlanmasından sonra gerçekleşen fiillerle sınırlar.", "m.7/4 başvurunun yayımından sonraki fiiller için tescil öncesinde de tazminat davası açılmasına izin verir.", "Kanun ücretin ödendiği tarihi değil, marka tescilinin yayım tarihini esas alır (m.7/4)."], "ref": "SMK m.7/4"}, {"id": "MRK-031", "exam": "marka", "topic": "Marka Hakkının Kapsamı", "q": "SMK m.7/3'e göre marka sahibinin yasaklatabileceği kullanım biçimleri arasında aşağıdakilerden hangisi sayılmamıştır?", "options": ["İşaretin ticaret unvanı veya işletme adı olarak kullanılması", "İşareti taşıyan malın ithal ya da ihraç edilmesi", "İşaretin bir kişi tarafından tamamen kişisel ve ticari olmayan amaçla kullanılması", "İşaretin hukuka uygun olmayan şekilde karşılaştırmalı reklamlarda kullanılması", "İşaretin internet ortamında ticari etki yaratacak biçimde anahtar sözcük olarak kullanılması"], "answer": 2, "why": ["m.7/3-e bendinde açıkça sayılmıştır.", "m.7/3-c bendinde açıkça sayılmıştır.", "Doğru. m.7/3 yalnızca işaretin 'ticaret alanında' kullanılması hâlinde yasaklanabilecek fiilleri sayar; ticari olmayan kişisel kullanım bu kapsamda değildir.", "m.7/3-f bendinde açıkça sayılmıştır.", "m.7/3-d bendinde, kullananın hakkı veya meşru bağlantısı olmaması şartıyla sayılmıştır."], "ref": "SMK m.7/3"}, {"id": "MRK-032", "exam": "marka", "topic": "Hakkın Sınırlandırılması", "q": "SMK m.7/5'e göre marka sahibi, üçüncü kişilerin dürüstçe ve ticari hayatın olağan akışı içinde yaptığı bazı kullanımları engelleyemez. Aşağıdakilerden hangisi bu kapsamda değildir?", "options": ["Bir gerçek kişinin kendi adını belirtmesi", "Malın kalitesi, miktarı veya coğrafi kaynağına ilişkin açıklama yapılması", "Yedek parça ürünlerinde malın kullanım amacını belirtmek için markanın kullanılması", "Hizmetin sunuluş zamanına ilişkin açıklama yapılması", "Bir tüzel kişinin, başkasına ait tescilli markayla aynı olan ibareyi ticaret unvanı olarak kullanması"], "answer": 4, "why": ["m.7/5-a kapsamındadır; marka sahibi engelleyemez.", "m.7/5-b kapsamındadır.", "m.7/5-c kapsamındadır; aksesuar, yedek parça ve eşdeğer parçalar özellikle sayılmıştır.", "m.7/5-b kapsamındadır.", "Doğru. m.7/5-a yalnızca gerçek kişilerin kendi ad veya adreslerini belirtmesini kapsar; işaretin ticaret unvanı olarak kullanılması ise m.7/3-e'ye göre yasaklanabilir."], "ref": "SMK m.7/5"}, {"id": "MRK-033", "exam": "marka", "topic": "Markanın Kullanılması", "q": "SMK m.9'a göre aşağıdakilerden hangileri markanın kullanılması olarak kabul edilir?\nI. Markanın ayırt edici karakteri değiştirilmeden farklı unsurlarla kullanılması\nII. Markanın sadece ihracat amacıyla mal veya ambalajlarında kullanılması\nIII. Markanın, marka sahibinin izni ile üçüncü bir kişi tarafından kullanılması", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 4, "why": ["II (m.9/2-b) ve III (m.9/3) de kullanım sayılır; seçenek eksiktir.", "III de kullanım sayılır; m.9/3 izinli kullanımı marka sahibinin kullanımı olarak kabul eder.", "II de kullanım sayılır (m.9/2-b).", "I de kullanım sayılır (m.9/2-a).", "Doğru. m.9/2-a, m.9/2-b ve m.9/3 bu üç hâli açıkça kullanım olarak kabul eder."], "ref": "SMK m.9"}, {"id": "MRK-034", "exam": "marka", "topic": "İptal", "q": "Tescil tarihinden itibaren beş yıl içinde haklı bir sebep olmaksızın Türkiye'de ciddi biçimde kullanılmayan bir markanın iptali ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["İptal talebi Kuruma yapılır; iptal talebinde bulunulacağı düşünülerek talepten önceki üç ay içinde gerçekleştirilen kullanım dikkate alınmaz.", "İptal talebi mahkemede dava yoluyla ileri sürülür.", "Beş yıllık süre dolduktan sonra, iptal talebinden önce başlayan ciddi kullanım iptal talebinin reddine yol açmaz.", "İptal kararı her durumda markanın tescil tarihinden itibaren geriye etkili olarak hüküm doğurur.", "İptal hâlleri markanın bir kısım mal veya hizmetine ilişkin olsa bile marka tümüyle iptal edilir."], "answer": 0, "why": ["Doğru. m.26/1-a ve m.26/2 uyarınca iptale talep üzerine Kurum karar verir; m.26/4 talepten önceki üç ay içinde iptal talebi düşünülerek yapılan kullanımı dikkate almaz.", "m.26/1 iptale Kurumun karar vereceğini öngörür; mahkeme yetkisi hükümsüzlük içindir (m.25/1).", "m.26/4'e göre beş yıllık sürenin dolması ile talep tarihi arasındaki ciddi kullanımda (son üç aydaki iptal talebi düşünülerek yapılan kullanım hariç) iptal talebi reddedilir.", "m.27/2'ye göre iptal kararı kural olarak iptal talebinin Kuruma sunulduğu tarihten itibaren etkilidir.", "m.26/5 kısmi iptali öngörür; yalnızca ilgili mal veya hizmetler yönünden iptal kararı verilir."], "ref": "SMK m.26, m.27/2"}, {"id": "MRK-035", "exam": "marka", "topic": "İptal", "q": "İptal talebinin tebliğ edildiği marka sahibinin, talebe ilişkin delillerini ve cevaplarını Kuruma sunma süresi ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Süre iki aydır; ek süre verilemez.", "Süre bir aydır; ek süre ancak Kurul kararıyla iki aya kadar verilebilir.", "Süre üç aydır; Kurum duruşma yaparak karar verir.", "Süre bir aydır; bu süre içinde talep edilirse Kurum bir aya kadar ek süre verir.", "Süre on beş gündür; bir kez on beş gün ek süre verilir."], "answer": 3, "why": ["m.26/7'de süre bir aydır ve talep hâlinde bir aya kadar ek süre verilir.", "Ek süreyi Kurum verir ve ek süre bir aya kadardır (m.26/7).", "Süre bir aydır ve Kurum dosya üzerinden karar verir (m.26/7).", "Doğru. m.26/7: marka sahibi bir ay içinde cevap ve delillerini sunar; bu süre içinde talep edilirse Kurum bir aya kadar ek süre verir.", "Kanunda on beş günlük süre yoktur; süre bir ay, ek süre bir aya kadardır (m.26/7)."], "ref": "SMK m.26/7"}, {"id": "MRK-036", "exam": "marka", "topic": "Hükümsüzlük", "q": "Önceki tarihli marka sahibi, sonraki tarihli bir markanın kullanıldığını bildiği veya bilmesi gerektiği hâlde bu duruma birbirini izleyen kaç yıl boyunca sessiz kalırsa, sonraki tarihli marka tescili kötüniyetli olmadıkça, markasını hükümsüzlük gerekçesi olarak ileri süremez?", "options": ["1 yıl", "3 yıl", "4 yıl", "5 yıl", "10 yıl"], "answer": 3, "why": ["Kanunda bir yıllık süre öngörülmemiştir; m.25/6 beş yıl arar.", "Üç yıl m.6/7'deki ortak ve garanti markalarına ilişkin süredir; sessiz kalma süresi beş yıldır.", "Dört yıllık bir süre öngörülmemiştir (m.25/6).", "Doğru. m.25/6: birbirini izleyen beş yıl sessiz kalma, sonraki tarihli marka tescili kötüniyetli değilse hükümsüzlük talebine engeldir.", "On yıl markanın koruma süresidir (m.23/1), sessiz kalma süresi değildir."], "ref": "SMK m.25/6"}, {"id": "MRK-037", "exam": "marka", "topic": "Hükümsüzlük ve İptalin Etkisi", "q": "Hükümsüzlük ve iptal kararlarının etkisi bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Hükümsüzlük kararı, kararın kesinleştiği tarihten itibaren ileriye etkilidir.", "İptal kararı her durumda markanın tescil tarihinden itibaren etkilidir.", "Hükümsüzlük kararı marka başvuru tarihinden itibaren etkilidir; iptal kararı ise kural olarak iptal talebinin Kuruma sunulduğu tarihten itibaren etkilidir.", "Hükümsüzlük kararının geriye etkisi, karardan önce kurulmuş ve uygulanmış sözleşmeleri de ortadan kaldırır.", "Hükümsüzlük ve iptal kararları yalnızca taraflar arasında hüküm doğurur."], "answer": 2, "why": ["m.27/1: hükümsüzlük başvuru tarihinden itibaren etkilidir ve koruma hiç doğmamış sayılır.", "m.27/2: iptal kural olarak talep tarihinden itibaren etkilidir; talep üzerine iptal hâlinin doğduğu daha önceki tarihten itibaren etkili olabilir.", "Doğru. m.27/1 hükümsüzlüğün başvuru tarihinden itibaren etkili olduğunu, m.27/2 iptalin kural olarak talep tarihinden itibaren etkili olduğunu düzenler.", "m.27/3-b bu sözleşmelerin etkilenmeyeceğini öngörür; hakkaniyet gereği bedel iadesi m.27/4'te saklıdır.", "m.27/5: kesinleşmiş hükümsüzlük ve iptal kararları herkese karşı hüküm doğurur."], "ref": "SMK m.27"}, {"id": "MRK-038", "exam": "marka", "topic": "Hükümsüzlük", "q": "Marka hükümsüzlüğü ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Cumhuriyet savcıları markanın hükümsüzlüğünü mahkemeden isteyebilir.\nII. Hükümsüzlük davasında Kurum davalı olarak gösterilir.\nIII. m.5/1'in (b), (c) veya (d) bentlerine aykırı olarak tescil edilmiş marka, hükümsüzlük talebinden önce kullanım sonucunda ayırt edici nitelik kazanmışsa hükümsüz kılınamaz.", "options": ["I ve III", "Yalnız I", "I ve II", "II ve III", "I, II ve III"], "answer": 0, "why": ["Doğru. m.25/2 Cumhuriyet savcılarına dava hakkı tanır; m.25/4 kazanılmış ayırt ediciliği hükümsüzlüğe engel sayar. II yanlıştır, çünkü m.25/3'e göre hükümsüzlük davalarında Kurum taraf gösterilmez.", "III de doğrudur (m.25/4); seçenek eksiktir.", "II yanlıştır; m.25/3 Kurumun taraf gösterilmeyeceğini öngörür.", "II yanlıştır (m.25/3); ayrıca doğru olan I seçenekte yer almaz.", "II yanlış olduğundan öncüllerin tamamı doğru değildir."], "ref": "SMK m.25"}, {"id": "MRK-039", "exam": "marka", "topic": "Hakkın Sona Ermesi", "q": "Marka hakkından vazgeçme ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Marka sahibi, tescil kapsamındaki mal veya hizmetlerin bir kısmından vazgeçebilir.", "Vazgeçme, Kuruma yapılan yazılı bildirimin tarihi itibarıyla hüküm doğurur.", "Sicile kaydedilmiş lisans sahiplerinin izni olmadıkça marka sahibi marka hakkından vazgeçemez.", "Vazgeçme yazılı olarak Kuruma bildirilir ve marka hakkının sona erdiği Bültende yayımlanır.", "Marka başvurusu, tescilden önce başvuru sahibi tarafından geri çekilebilir."], "answer": 1, "why": ["Doğru ifadedir (m.28/3).", "Yanlış ifade budur. m.28/3'e göre vazgeçme, sicile kayıt tarihi itibarıyla hüküm doğurur.", "Doğru ifadedir (m.28/4).", "Doğru ifadedir (m.28/3).", "Doğru ifadedir (m.28/5)."], "ref": "SMK m.28"}, {"id": "MRK-040", "exam": "marka", "topic": "Lisans", "q": "Sözleşmede aksine bir hüküm bulunmayan bir marka lisans sözleşmesi bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Lisans inhisari olmayan lisanstır ve lisans alan, haklarını üçüncü kişilere devredemez veya alt lisans veremez.", "Lisans inhisari lisanstır; lisans veren markayı kendisi kullanamaz.", "Lisans alan, lisanstan doğan haklarını serbestçe üçüncü kişilere devredebilir.", "Lisans veren, lisans alanın üreteceği malların kalitesine ilişkin hiçbir önlem almak zorunda değildir.", "Lisans, yalnızca markanın tescilli olduğu mal veya hizmetlerin tamamı için verilebilir."], "answer": 0, "why": ["Doğru. m.24/2'ye göre aksi kararlaştırılmamışsa lisans inhisari değildir; m.24/3'e göre lisans alan haklarını devredemez ve alt lisans veremez.", "m.24/2: aksi kararlaştırılmamışsa lisans inhisari değildir.", "m.24/3: aksi kararlaştırılmadıkça lisans alan haklarını devredemez.", "m.24/4: lisans veren, mal veya hizmet kalitesini garanti altına alacak önlemleri alır.", "m.24/1: lisans, mal veya hizmetlerin bir kısmı ya da tamamı için verilebilir."], "ref": "SMK m.24"}, {"id": "MRK-041", "exam": "marka", "topic": "Tecavüz", "q": "Tescilli marka sahibi A, B aleyhine marka hakkına tecavüz davası açmıştır. B, A'nın markasını kullanmadığını def'i olarak ileri sürmektedir. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["Kullanmama def'i yalnızca Kurum nezdindeki yayıma itiraz sürecinde ileri sürülebilir.", "m.19/2'deki kullanım ispatı def'i tecavüz davasında ileri sürülebilir ve beş yıllık kullanım süresinin belirlenmesinde dava tarihi esas alınır.", "Beş yıllık süre, B'nin işareti kullanmaya başladığı tarihe göre belirlenir.", "Beş yıllık süre, A'nın markasının başvuru tarihine göre belirlenir.", "Def'i ancak B ayrıca Kuruma iptal talebinde bulunmuşsa dinlenebilir."], "answer": 1, "why": ["m.29/2 bu def'inin tecavüz davalarında da ileri sürülebileceğini açıkça düzenler.", "Doğru. m.29/2 m.19/2 hükmünün tecavüz davalarında def'i olarak ileri sürülebileceğini ve beş yıllık sürede dava tarihinin esas alınacağını düzenler.", "m.29/2: beş yıllık sürenin belirlenmesinde dava tarihi esas alınır.", "m.29/2 başvuru tarihini değil, dava tarihini esas alır.", "m.29/2 böyle bir ön şart öngörmez."], "ref": "SMK m.29/2, m.19/2"}, {"id": "MRK-042", "exam": "marka", "topic": "Cezai Hükümler", "q": "SMK m.30/1'e göre başkasına ait marka hakkına iktibas veya iltibas suretiyle tecavüz ederek mal üreten veya satan kişi için öngörülen yaptırım aşağıdakilerden hangisidir?", "options": ["Bir yıldan üç yıla kadar hapis ve yirmi bin güne kadar adli para cezası", "İki yıldan dört yıla kadar hapis ve beş bin güne kadar adli para cezası", "Bir yıldan üç yıla kadar hapis ve beş bin güne kadar adli para cezası", "Altı aydan iki yıla kadar hapis", "Yalnızca idari para cezası"], "answer": 0, "why": ["Doğru. m.30/1 bu fiiller için bir yıldan üç yıla kadar hapis ve yirmi bin güne kadar adli para cezası öngörür.", "Bu yaptırım m.30/3'te yetkisiz devir, lisans veya rehin suretiyle tasarruf için öngörülmüştür.", "Bu yaptırım m.30/2'de marka koruması olduğunu belirten işareti yetkisiz kaldırma için öngörülmüştür.", "m.30/1'deki hapis cezası bir yıldan üç yıla kadardır ve yanında yirmi bin güne kadar adli para cezası vardır.", "m.30/1 idari para cezası değil, hapis ve adli para cezası öngörür."], "ref": "SMK m.30"}, {"id": "MRK-043", "exam": "marka", "topic": "Cezai Hükümler", "q": "SMK m.30'da düzenlenen marka suçları ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Bu suçların soruşturulması ve kovuşturulması şikâyete bağlıdır.\nII. Cezaya hükmedebilmek için markanın Türkiye'de tescilli olması şarttır.\nIII. Taklit malı satan kişinin, malı nereden temin ettiğini bildirerek üretenlerin ortaya çıkarılmasını ve üretilmiş mallara elkonulmasını sağlaması hâlinde hakkında cezaya hükmolunmaz.", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 4, "why": ["II (m.30/5) ve III (m.30/7) de doğrudur; seçenek eksiktir.", "III de doğrudur; m.30/7 bu hâlde cezaya hükmolunmayacağını düzenler.", "II de doğrudur; m.30/5 markanın Türkiye'de tescilli olmasını şart koşar.", "I de doğrudur; m.30/6 suçların şikâyete bağlı olduğunu öngörür.", "Doğru. m.30/6 şikâyete bağlılığı, m.30/5 Türkiye'de tescil şartını, m.30/7 ise kaynağı bildirerek üretenlerin ortaya çıkarılmasını sağlayan satıcının cezalandırılmamasını düzenler."], "ref": "SMK m.30"}, {"id": "MRK-044", "exam": "marka", "topic": "Garanti ve Ortak Marka", "q": "Garanti markası ve ortak marka ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Ortak markayı kullanmaya yetkili olan gruba dâhil işletmeler tek başına dava açmaya yetkilidir.", "Teknik şartnamede yapılacak değişiklikler Kurumca onaylanmadıkça uygulanamaz.", "Ortak markanın tescili ve ortak marka hakkından vazgeçilmesi için gruba dâhil işletmelerin tümü birlikte hareket eder.", "Garanti markası sahibi, markayı kendi ürettiği mallarda da kullanabilir.", "Kurumun bildirimine rağmen marka sahibi altı ay içinde teknik şartnameyi düzeltmezse tescil talebi reddedilir."], "answer": 3, "why": ["Doğru ifadedir (m.32/4).", "Doğru ifadedir (m.32/5).", "Doğru ifadedir (m.32/3).", "Yanlış ifade budur. m.31/2 garanti markasının, marka sahibinin veya ona iktisaden bağlı işletmenin mal veya hizmetlerinde kullanılmasını yasaklar.", "Doğru ifadedir (m.32/6)."], "ref": "SMK m.31, m.32"}, {"id": "MRK-045", "exam": "marka", "topic": "Devir", "q": "Marka devri ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Marka ancak işletmeyle birlikte devredilebilir.", "Devir sözleşmesi adi yazılı şekilde yapılsa da geçerlidir.", "Devir sözleşmesinin geçerliliği noter tarafından onaylanmış şekilde yapılmasına bağlıdır ve marka, tescil edildiği mal veya hizmetlerin bir kısmı için de devredilebilir.", "Sicile kaydedilmeyen devir, iyiniyetli üçüncü kişilere karşı da ileri sürülebilir.", "Marka başvuruları tescil edilmeden devredilemez."], "answer": 2, "why": ["m.148/2: hukuki işlemler işletmeden bağımsız olarak gerçekleştirilebilir.", "m.148/4 devir sözleşmelerinde noter onayını geçerlilik şartı olarak arar.", "Doğru. m.148/4 devir sözleşmelerinde noter onayını geçerlilik şartı yapar; m.148/6 markanın mal veya hizmetlerin tümü veya bir kısmı için devredilebileceğini düzenler.", "m.148/5: sicile kaydedilmeyen hukuki işlemlerden doğan haklar iyiniyetli üçüncü kişilere karşı ileri sürülemez.", "m.148/8: bu maddedeki hükümler başvurularda da uygulanır; başvuru da devredilebilir."], "ref": "SMK m.148"}, {"id": "ORT-001", "exam": "ortak", "topic": "Hukuki Yaptırımlar", "q": "6769 sayılı SMK m.149 uyarınca sınai mülkiyet hakkı tecavüze uğrayan hak sahibinin mahkemeden talep edebileceği hususlar arasında aşağıdakilerden hangisi yer almaz?", "options": ["Tecavüz edene idari para cezası verilmesi", "Fiilin tecavüz olup olmadığının tespiti", "Muhtemel tecavüzün önlenmesi", "Elkonulan ürün, cihaz ve makineler üzerinde kendisine mülkiyet hakkı tanınması", "Haklı sebep veya menfaat varsa kesinleşmiş kararın masrafı karşı tarafa ait olmak üzere ilanı"], "answer": 0, "why": ["SMK m.149'da sayılan talepler hukuki taleplerdir; tecavüz edene idari para cezası verilmesi bu talepler arasında yer almaz (SMK m.149/1).", "Tespit talebi açıkça düzenlenmiştir (SMK m.149/1-a).", "Önleme talebi kanunda sayılmıştır (SMK m.149/1-b).", "Bu talep (d) bendine göre elkonulan ürünler için öngörülmüştür (SMK m.149/1-e).", "İlan talebi kanunda yer alır (SMK m.149/1-g)."], "ref": "SMK m.149"}, {"id": "ORT-002", "exam": "ortak", "topic": "Hukuki Yaptırımlar", "q": "Tecavüz davasında mahkeme, hak sahibinin kesinleşmiş kararın ilan edilmesi talebini kabul etmiştir. SMK'ya göre ilana ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["İlan masrafları davacı hak sahibine aittir.", "İlan hakkı, kararın kesinleşmesinden sonra üç ay içinde talep edilmezse düşer.", "İlanın şekli ve kapsamı Kurum tarafından belirlenir.", "İlan ancak kararın tamamının yayımlanması suretiyle yapılabilir.", "İlan talebinin kabulü için haklı bir sebep veya menfaat aranmaz."], "answer": 1, "why": ["İlan masrafları karşı tarafa aittir (SMK m.149/1-g).", "Kanuna göre ilan hakkı, kararın kesinleşmesinden sonra üç ay içinde talep edilmezse düşer (SMK m.149/3).", "İlanın şekli ve kapsamı mahkeme kararında tespit edilir; Kurum'un bir yetkisi yoktur (SMK m.149/3).", "Karar tamamen veya özet olarak ilan edilebilir ya da ilgililere tebliğ edilebilir (SMK m.149/1-g).", "İlan talebi ancak haklı bir sebebin veya menfaatin bulunması hâlinde kabul edilir (SMK m.149/1-g)."], "ref": "SMK m.149/3"}, {"id": "ORT-003", "exam": "ortak", "topic": "Hukuki Yaptırımlar", "q": "Hak sahibi A, tecavüz davasında elkonulan makineler üzerinde kendisine mülkiyet hakkı tanınmasını talep etmiş ve talep kabul edilmiştir. Makinelerin değeri 500.000 TL, mahkemece kabul edilen tazminat miktarı ise 300.000 TL'dir. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["A, makinelerin mülkiyetine ek olarak 300.000 TL tazminatı da tahsil eder.", "Makinelerin değeri tazminat hesabında dikkate alınmaz.", "A, aşan 200.000 TL'yi karşı tarafa öder.", "Tecavüz eden, A'ya ayrıca 200.000 TL öder.", "Mülkiyet talebi kabul edildiğinden tazminat talebi kendiliğinden reddedilir."], "answer": 2, "why": ["Makinelerin değeri tazminat miktarından düşülür; mülkiyetle birlikte tam tazminat alınamaz (SMK m.149/2).", "Kanun, makinelerin değerinin tazminattan düşüleceğini açıkça öngörür (SMK m.149/2).", "Ürün, cihaz ve makinelerin değeri tazminattan düşülür; değer tazminatı aşarsa aşan kısım hak sahibince karşı tarafa ödenir (SMK m.149/2).", "Ödeme yönü terstir; aşan kısmı hak sahibi karşı tarafa öder (SMK m.149/2).", "Talepler birlikte kabul edilebilir; yalnızca değer tazminattan mahsup edilir (SMK m.149/2)."], "ref": "SMK m.149/2"}, {"id": "ORT-004", "exam": "ortak", "topic": "Hukuki Yaptırımlar", "q": "Tescilli bir coğrafi işarete tecavüz edilmesi hâlinde aşağıdakilerden hangileri talep edilemez veya uygulanmaz?\nI. Manevi zararın tazmini\nII. Yoksun kalınan kazancın SMK m.151'deki değerlendirme usulleriyle hesaplanması\nIII. Tecavüz fiillerinin durdurulması", "options": ["Yalnız I", "Yalnız II", "Yalnız III", "I ve II", "I, II ve III"], "answer": 3, "why": ["II de uygulanmaz; m.151 hükmü coğrafi işarete tecavüz hâlinde uygulanmaz (SMK m.151/6).", "I de talep edilemez; coğrafi işaretlerde manevi zararın tazmini istenemez (SMK m.149/4).", "Tecavüzün durdurulması coğrafi işaret sahibi bakımından da istenebilir (SMK m.149/1-c).", "Manevi tazminat istenemez (SMK m.149/4) ve m.151 yoksun kalınan kazanç hükmü uygulanmaz (SMK m.151/6); durdurma ise talep edilebilir.", "III yanlıştır; durdurma talebi m.149'da yer alır ve coğrafi işaretler için kısıtlanmamıştır (SMK m.149/1-c)."], "ref": "SMK m.149/4, m.151/6"}, {"id": "ORT-005", "exam": "ortak", "topic": "Tazminat", "q": "Tecavüz eden kişi, taklit ürünleri kalitesiz şekilde üreterek uygun olmayan bir tarzda piyasaya sürmüş ve bu nedenle hak sahibinin markasının itibarı zarar görmüştür. SMK'ya göre hak sahibi bu itibar kaybı için ne talep edebilir?", "options": ["Yalnızca yoksun kalınan kazanç kapsamında değerlendirilen bir tazminat", "Hiçbir tazminat; itibar kaybı yalnızca cezai yaptırıma konu olur", "Kurum'dan idari yoldan itibar tazminatı", "Sınai mülkiyet hakkının itibarının zarara uğraması nedeniyle ayrıca tazminat", "Yalnızca tanınmış markalar için itibar tazminatı"], "answer": 3, "why": ["İtibar tazminatı, maddi tazminattan ayrı olarak 'ayrıca' istenebilir (SMK m.150/2).", "Kanun itibar zararı için açıkça tazminat öngörür (SMK m.150/2).", "Tazminat talepleri mahkemeden istenir; Kurum tazminata hükmetmez (SMK m.149/1, m.156/1).", "Hakka konu ürünlerin kötü kullanılması/üretilmesi veya uygun olmayan tarzda piyasaya sürülmesi sonucu itibar zarar görürse ayrıca tazminat istenebilir (SMK m.150/2).", "m.150/2 tüm sınai mülkiyet haklarını kapsar; tanınmışlık şartı aranmaz (SMK m.150/2)."], "ref": "SMK m.150/2"}, {"id": "ORT-006", "exam": "ortak", "topic": "Tazminat", "q": "SMK'ya göre yoksun kalınan kazancın hesaplanmasına ilişkin aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Hak sahibinin uğradığı zarar, fiili kaybı ve yoksun kalınan kazancı kapsar.", "Tecavüz edenin elde ettiği net kazanç esas alınabilir.", "Tecavüz edenin hakkı lisansla hukuka uygun kullansaydı ödeyeceği lisans bedeli esas alınabilir.", "Hesaplamada lisansların sayısı, süresi ve çeşidi ile ihlalin nitelik ve boyutu gibi etkenler göz önünde tutulur.", "Değerlendirme usulü mahkeme tarafından re'sen belirlenir; hak sahibinin seçim hakkı yoktur."], "answer": 4, "why": ["Doğrudur (SMK m.151/1).", "Doğrudur; net kazanç usulü kanunda sayılmıştır (SMK m.151/2-b).", "Doğrudur; lisans bedeli usulü kanunda yer alır (SMK m.151/2-c).", "Doğrudur (SMK m.151/3).", "Yanlıştır; yoksun kalınan kazanç, zarar gören hak sahibinin seçimine bağlı olarak kanundaki usullerden biriyle hesaplanır (SMK m.151/2)."], "ref": "SMK m.151"}, {"id": "ORT-007", "exam": "ortak", "topic": "Tazminat", "q": "Mahkeme, ürüne ilişkin talebin oluşmasında sınai mülkiyet hakkının belirleyici etken olduğu kanaatine varırsa, yoksun kalınan kazancın hesaplanmasında hakkaniyete uygun bir payın daha eklenmesine karar verir. Bu ek pay, aşağıdaki değerlendirme usullerinden hangilerinin seçilmesi hâlinde söz konusu olabilir?\nI. Tecavüz edenin rekabeti olmasaydı hak sahibinin elde edebileceği muhtemel gelir\nII. Tecavüz edenin elde ettiği net kazanç\nIII. Tecavüz edenin ödemesi gereken lisans bedeli", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 2, "why": ["Eksiktir; (b) bendindeki net kazanç usulünde de ek pay eklenebilir (SMK m.151/4).", "Eksiktir; (a) bendindeki muhtemel gelir usulünde de ek pay eklenebilir (SMK m.151/4).", "Hakkaniyete uygun pay, yalnızca (a) veya (b) bentlerindeki usullerden birinin seçilmesi hâlinde eklenir (SMK m.151/4).", "Lisans bedeli usulü (c bendi) için ek pay öngörülmemiştir (SMK m.151/4).", "III hatalıdır; m.151/4 yalnızca (a) ve (b) bentlerine atıf yapar (SMK m.151/4)."], "ref": "SMK m.151/4"}, {"id": "ORT-008", "exam": "ortak", "topic": "Tazminat", "q": "Patent hakkına tecavüz davasında mahkeme, patent sahibinin SMK'da öngörülen patenti kullanma yükümlülüğünü yerine getirmediği kanaatine varmıştır. Bu durumda yoksun kalınan kazanç nasıl hesaplanır?", "options": ["Tecavüz edenin hakkı lisans sözleşmesiyle hukuka uygun kullanmış olması hâlinde ödemesi gereken lisans bedeline göre", "Hak sahibinin seçeceği herhangi bir usule göre", "Tecavüz edenin elde ettiği net kazanca göre", "Tecavüz edenin rekabeti olmasaydı elde edilebilecek muhtemel gelire göre", "Yoksun kalınan kazanç talep edilemez; yalnızca fiili kayıp istenebilir"], "answer": 0, "why": ["Kullanma yükümlülüğü yerine getirilmemişse yoksun kalınan kazanç m.151/2-c'ye, yani lisans bedeline göre hesaplanır (SMK m.151/5).", "Bu durumda hak sahibinin seçim serbestisi yoktur; kanun (c) bendini zorunlu kılar (SMK m.151/5).", "Net kazanç usulü (b bendi) bu hâlde uygulanmaz (SMK m.151/5).", "Muhtemel gelir usulü (a bendi) bu hâlde uygulanmaz (SMK m.151/5).", "Kanun yoksun kalınan kazancı ortadan kaldırmaz, yalnızca hesaplama usulünü (c) bendiyle sınırlar (SMK m.151/5)."], "ref": "SMK m.151/5"}, {"id": "ORT-009", "exam": "ortak", "topic": "Hakkın Tüketilmesi", "q": "SMK'da düzenlenen hakkın tüketilmesi ilkesine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Tüketilme yalnızca hak sahibinin bizzat piyasaya sunduğu ürünler için geçerlidir; onun izniyle üçüncü kişilerce sunulanlar kapsam dışıdır.", "Marka sahibi, tüketilme kapsamındaki ürünlerin üçüncü kişilerce değiştirilerek veya kötüleştirilerek ticari amaçla kullanılmasını önleme hakkına sahiptir.", "Piyasaya sunulmuş ürünlerin her yeniden satışı hak sahibinin ayrı iznine bağlıdır.", "Tüketilme ilkesi yalnızca patentler için düzenlenmiştir.", "Tüketilme ilkesi, ürünlerin hak sahibinin izni olmaksızın piyasaya sunulması hâlinde de uygulanır."], "answer": 1, "why": ["Hak sahibinin izniyle üçüncü kişilerce piyasaya sunulan ürünler de tüketilme kapsamındadır (SMK m.152/1).", "Kanun marka sahibine bu istisnai önleme hakkını açıkça tanımıştır (SMK m.152/2).", "Piyasaya sunulduktan sonra bu ürünlerle ilgili fiiller hakkın kapsamı dışında kalır (SMK m.152/1).", "m.152 Ortak Hükümler'de yer alır ve tüm sınai mülkiyet haklarına uygulanır (SMK m.152).", "Tüketilme için ürünün hak sahibi veya onun izniyle piyasaya sunulmuş olması gerekir (SMK m.152/1)."], "ref": "SMK m.152"}, {"id": "ORT-010", "exam": "ortak", "topic": "Dava Hakkı", "q": "SMK m.153 uyarınca sınai mülkiyet hakkı sahibi, aşağıdaki kişilerden hangilerine karşı bu Kanunda yer alan hukuk davalarını açamaz veya ceza davası için şikâyette bulunamaz?\nI. Tecavüz eden tarafından piyasaya sürülmüş ürünleri kişisel ihtiyaçları ölçüsünde elinde bulunduran kişi\nII. Hak sahibine tazminat ödeyen kişi tarafından, hak sahibinin elkoymaması nedeniyle piyasaya sürülmüş ürünleri ticari amaçla kullanan kişi\nIII. Taklit ürünleri ticari amaçla depolayan toptancı", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 1, "why": ["Eksiktir; II'deki kişiye karşı da dava açılamaz (SMK m.153/2).", "Kişisel ihtiyaç ölçüsünde bulunduran (SMK m.153/1) ve tazminat ödenmiş ürünleri ticari amaçla kullanan (SMK m.153/2) kişilere karşı dava açılamaz.", "III'teki ticari amaçla depolama korunmaz; hatta m.30/1 kapsamında suçtur (SMK m.30/1).", "III'teki toptancı m.153 korumasından yararlanamaz (SMK m.153).", "Ticari amaçla depolayan kişi m.153'te sayılmamıştır (SMK m.153)."], "ref": "SMK m.153"}, {"id": "ORT-011", "exam": "ortak", "topic": "Dava Hakkı", "q": "SMK m.154'te düzenlenen tecavüzün mevcut olmadığının tespiti davasına ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Talebin tebliğinden itibaren bir ay içinde cevap verilmezse menfaat sahibi dava açabilir.", "Kendisine karşı tecavüz davası açılmış kişi bu davayı açamaz.", "Hak sahibinden görüş bildirmesinin talep edilmiş olması, davanın dava şartıdır.", "Dava, sicile kayıtlı tüm hak sahiplerine tebliğ edilir.", "Dava, hükümsüzlük davasıyla birlikte de açılabilir."], "answer": 2, "why": ["Doğrudur (SMK m.154/1).", "Doğrudur (SMK m.154/1 son cümle).", "Yanlıştır; bildirimin yapılmış olması açılacak davada dava şartı olarak aranmaz (SMK m.154/1).", "Doğrudur (SMK m.154/2).", "Doğrudur (SMK m.154/3)."], "ref": "SMK m.154"}, {"id": "ORT-012", "exam": "ortak", "topic": "Görevli ve Yetkili Mahkeme", "q": "SMK'da öngörülen davalarda görevli ve yetkili mahkemeye ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Kurum kararlarına karşı açılacak davalar Ankara İdare Mahkemesinde görülür.", "Fikri ve sınai haklar hukuk mahkemesi kurulmamış yerlerde bu davalara asliye ticaret mahkemesi bakar.", "Fikri ve sınai haklar mahkemeleri üç hâkimli olarak kurulur.", "Kurumun SMK hükümlerine göre aldığı kararlara karşı açılacak davalarda görevli ve yetkili mahkeme Ankara Fikri ve Sınai Haklar Hukuk Mahkemesidir.", "Kurumun kararlarından zarar gören üçüncü kişilerin Kurum aleyhine açacakları davalarda yetkili mahkeme davacının yerleşim yeri mahkemesidir."], "answer": 3, "why": ["Kurum kararlarına karşı davalar idare mahkemesinde değil, Ankara Fikri ve Sınai Haklar Hukuk Mahkemesinde görülür (SMK m.156/2).", "Bu yerlerde HSK tarafından belirlenen asliye hukuk mahkemesi bakar (SMK m.156/1).", "Bu mahkemeler tek hâkimli ve asliye mahkemesi derecesinde kurulur (SMK m.156/1).", "Doğrudur (SMK m.156/2).", "Bu davalarda da görevli ve yetkili mahkeme Ankara Fikri ve Sınai Haklar Hukuk Mahkemesidir (SMK m.156/2)."], "ref": "SMK m.156/1-2"}, {"id": "ORT-013", "exam": "ortak", "topic": "Görevli ve Yetkili Mahkeme", "q": "Almanya'da yerleşik X şirketi, Türkiye'de tescilli markasına İzmir'de yerleşik Y tarafından tecavüz edildiğini ileri sürmektedir. Tecavüz fiili yalnızca İstanbul'da gerçekleşmiş ve etkileri yalnızca İstanbul'da görülmüştür. X'in sicilde kayıtlı marka vekilinin işyeri Bursa'dadır ve vekillik kaydı silinmemiştir. SMK m.156'ya göre aşağıdaki mahkemelerden hangileri yetkilidir?\nI. Bursa mahkemesi\nII. İstanbul mahkemesi\nIII. Kurum merkezinin bulunduğu Ankara mahkemesi", "options": ["Yalnız I", "Yalnız III", "I ve III", "I ve II", "I, II ve III"], "answer": 3, "why": ["Eksiktir; hukuka aykırı fiilin gerçekleştiği İstanbul mahkemesi de yetkilidir (SMK m.156/3).", "Kurum merkezinin bulunduğu yer, ancak vekillik kaydı silinmişse yetkilidir (SMK m.156/4).", "Vekillik kaydı silinmediğinden Ankara yetkili değildir (SMK m.156/4).", "Davacının Türkiye'de yerleşim yeri yoksa sicilde kayıtlı vekilin işyeri (Bursa) davacı yerleşim yeri yerine geçer (SMK m.156/4); fiilin gerçekleştiği yer (İstanbul) de yetkilidir (SMK m.156/3).", "III hatalıdır; Kurum merkezi yalnızca vekillik kaydı silinmişse devreye girer (SMK m.156/4)."], "ref": "SMK m.156/3-4"}, {"id": "ORT-014", "exam": "ortak", "topic": "Zamanaşımı", "q": "SMK'ya göre sınai mülkiyet hakkı veya geleneksel ürün adından doğan özel hukuka ilişkin taleplerde zamanaşımı bakımından hangi hükümler uygulanır?", "options": ["SMK'da öngörülen beş yıllık özel zamanaşımı süresi", "6102 sayılı Türk Ticaret Kanununun haksız rekabete ilişkin zamanaşımı hükümleri", "6100 sayılı Hukuk Muhakemeleri Kanunu hükümleri", "Bu talepler zamanaşımına tabi değildir", "6098 sayılı Türk Borçlar Kanununun zamanaşımına ilişkin hükümleri"], "answer": 4, "why": ["SMK'da tecavüz talepleri için özel bir zamanaşımı süresi öngörülmemiş, TBK'ya atıf yapılmıştır (SMK m.157).", "m.157 açıkça TBK'ya atıf yapar, TTK'ya değil (SMK m.157).", "HMK, m.159/3 uyarınca ihtiyati tedbirlerde tamamlayıcıdır; zamanaşımında uygulanacak kanun TBK'dır (SMK m.157).", "Kanun, TBK zamanaşımı hükümlerinin uygulanacağını öngörür (SMK m.157).", "Kanun bu taleplerde TBK'nın zamanaşımı hükümlerine atıf yapar (SMK m.157)."], "ref": "SMK m.157"}, {"id": "ORT-015", "exam": "ortak", "topic": "Lisans ve Dava Hakkı", "q": "Sözleşmede aksine bir hüküm bulunmadığı varsayımıyla, lisans alanın dava açma hakkına ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["İnhisari lisans alan, üçüncü kişinin tecavüzü hâlinde hak sahibinin açabileceği davaları kendi adına açabilir.", "İnhisari olmayan lisans alan hiçbir koşulda dava açamaz.", "İnhisari olmayan lisans alan, hak sahibine bildirimde bulunmaksızın doğrudan kendi adına dava açabilir.", "İnhisari lisans alan, dava açabilmek için hak sahibine bildirim yapıp üç ay beklemek zorundadır.", "Lisans alan, üç aylık süre dolmadan ihtiyati tedbir talep edemez."], "answer": 0, "why": ["Doğrudur (SMK m.158/1).", "Hak sahibi talebi kabul etmez veya bildirimden itibaren üç ay içinde dava açmazsa inhisari olmayan lisans alan da dava açabilir (SMK m.158/2).", "Önce hak sahibinden davayı açmasını bildirimle istemesi gerekir (SMK m.158/2).", "Bildirim ve üç ay bekleme şartı inhisari olmayan lisans alan içindir (SMK m.158/1-2).", "Ciddi zarar tehlikesi varsa süre geçmeden ihtiyati tedbir talep edilebilir (SMK m.158/3)."], "ref": "SMK m.158"}, {"id": "ORT-016", "exam": "ortak", "topic": "İhtiyati Tedbir", "q": "SMK m.159 uyarınca ihtiyati tedbirlere ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Talep eden, kullanımın tecavüz teşkil edecek şekilde gerçekleşmekte olduğunu veya bunun için ciddi ve etkin çalışmalar yapıldığını ispat etmelidir.", "Tecavüze konu ürünlere elkonulması tedbiri, gümrük ve serbest bölge gibi alanlarda bulunan ürünler için uygulanamaz.", "İhtiyati tedbirler, herhangi bir zararın tazmini bakımından teminat verilmesini kapsayabilir.", "SMK'da hüküm bulunmayan hususlarda 6100 sayılı HMK hükümleri uygulanır.", "İhtiyati tedbir, verilecek hükmün etkinliğini temin etmek üzere talep edilir."], "answer": 1, "why": ["Doğrudur (SMK m.159/1).", "Yanlıştır; elkoyma Türkiye sınırları içinde veya gümrük ve serbest liman veya bölge gibi alanlar dâhil bulundukları her yerde uygulanabilir (SMK m.159/2-b).", "Doğrudur (SMK m.159/2-c).", "Doğrudur (SMK m.159/3).", "Doğrudur (SMK m.159/1)."], "ref": "SMK m.159"}, {"id": "ORT-017", "exam": "ortak", "topic": "Cezai Hükümler", "q": "Başkasına ait marka hakkına iltibas suretiyle tecavüz ederek mal üreten kişi için SMK m.30/1'de öngörülen ceza hangisidir?", "options": ["Bir yıldan üç yıla kadar hapis ve beş bin güne kadar adli para cezası", "İki yıldan dört yıla kadar hapis ve beş bin güne kadar adli para cezası", "Bir yıldan üç yıla kadar hapis ve yirmi bin güne kadar adli para cezası", "Altı aydan iki yıla kadar hapis", "Yalnızca idari para cezası"], "answer": 2, "why": ["Bu ceza, marka koruması olduğunu belirten işareti yetkisiz kaldırma suçu içindir (SMK m.30/2).", "Bu ceza, yetkisiz olarak marka üzerinde devir, lisans veya rehin suretiyle tasarruf suçu içindir (SMK m.30/3).", "Doğru cezadır (SMK m.30/1).", "SMK m.30'da böyle bir ceza öngörülmemiştir (SMK m.30/1).", "Fiil suç olarak düzenlenmiş olup hapis ve adli para cezası öngörülmüştür (SMK m.30/1)."], "ref": "SMK m.30/1"}, {"id": "ORT-018", "exam": "ortak", "topic": "Cezai Hükümler", "q": "SMK m.30'da düzenlenen marka hakkına tecavüz suçlarına ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Bu suçların soruşturulması ve kovuşturulması şikâyete bağlıdır.\nII. Bu suçlardan dolayı cezaya hükmedebilmek için markanın Türkiye'de tescilli olması şarttır.\nIII. Taklit malı satan kişi, malı nereden temin ettiğini bildirerek üretenlerin ortaya çıkarılmasını ve mallara elkonulmasını sağlarsa hakkında cezaya hükmolunmaz.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 4, "why": ["II ve III de doğrudur (SMK m.30/5, m.30/7).", "I ve III de doğrudur (SMK m.30/6, m.30/7).", "III de doğrudur; kanun bu durumda cezaya hükmolunmayacağını öngörür (SMK m.30/7).", "I de doğrudur; suçlar şikâyete bağlıdır (SMK m.30/6).", "Şikâyete bağlılık (SMK m.30/6), Türkiye'de tescil şartı (SMK m.30/5) ve etkin pişmanlık benzeri cezasızlık hâli (SMK m.30/7) kanunda yer alır."], "ref": "SMK m.30"}, {"id": "ORT-019", "exam": "ortak", "topic": "Cezai Hükümler", "q": "SMK'daki cezai hükümlere ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Marka koruması olduğunu belirten işareti mal veya ambalaj üzerinden yetkisiz kaldırmak suçtur.", "Yetkisiz olarak başkasına ait marka üzerinde devir, lisans veya rehin suretiyle tasarrufta bulunmak suçtur.", "Taklit malı ticari amaçla satın almak, bulundurmak, nakletmek veya depolamak da m.30/1 kapsamında suçtur.", "Suçun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde tüzel kişiye hapis cezası verilir.", "SMK'da hapis cezası öngören hükümler marka hakkına tecavüze ilişkin m.30'da düzenlenmiştir; patent ve tasarım için ayrıca cezai hüküm öngörülmemiştir."], "answer": 3, "why": ["Doğrudur; bir yıldan üç yıla kadar hapis ve beş bin güne kadar adli para cezası öngörülmüştür (SMK m.30/2).", "Doğrudur; iki yıldan dört yıla kadar hapis öngörülmüştür (SMK m.30/3).", "Doğrudur (SMK m.30/1).", "Yanlıştır; bu hâlde tüzel kişilere özgü güvenlik tedbirlerine hükmolunur (SMK m.30/4).", "Doğrudur; SMK'da hapis cezası yalnızca m.30'da yer alır, patent ve tasarım tecavüzü hukuki yaptırımlara tabidir (SMK m.30, m.149)."], "ref": "SMK m.30"}, {"id": "ORT-020", "exam": "ortak", "topic": "Hükümsüzlük", "q": "Markanın hükümsüzlüğü ve iptali kararlarının etkisine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Hükümsüzlük kararı, kesinleştiği tarihten itibaren ileriye doğru etkilidir.", "İptal kararı her durumda marka başvuru tarihinden itibaren etkilidir.", "Hükümsüzlük kararı yalnızca davanın taraflarını bağlar.", "Marka, hükümsüzlük kararı kesinleşmeden sicilden terkin edilir.", "Hükümsüzlük kararı marka başvuru tarihinden itibaren etkili olup markaya SMK ile sağlanan koruma hiç doğmamış sayılır."], "answer": 4, "why": ["Hükümsüzlük kararı geçmişe, başvuru tarihine kadar etkilidir (SMK m.27/1).", "İptal kararı kural olarak iptal talebinin Kuruma sunulduğu tarihten itibaren etkilidir; talep üzerine iptal hâlinin doğduğu daha önceki tarihten itibaren etkili kılınabilir (SMK m.27/2).", "Kesinleşmiş hükümsüzlük ve iptal kararları herkese karşı hüküm doğurur (SMK m.27/5).", "Terkin, kararın kesinleşmesinden sonra yapılır (SMK m.27/7; ayrıca m.162).", "Doğrudur (SMK m.27/1)."], "ref": "SMK m.27"}, {"id": "ORT-021", "exam": "ortak", "topic": "Hükümsüzlük", "q": "Hak sahibinin ağır ihmali veya kötüniyeti nedeniyle zarar görenlerin tazminat talepleri saklı kalmak üzere, marka, patent veya tasarımın hükümsüzlüğünün geçmişe dönük etkisi aşağıdakilerden hangilerini etkilemez?\nI. Karardan önce hakka tecavüz nedeniyle verilmiş kesinleşmiş ve uygulanmış kararlar\nII. Karardan önce kurulmuş ve uygulanmış sözleşmeler\nIII. Karardan önce kurulmuş ancak henüz uygulanmamış lisans sözleşmeleri", "options": ["Yalnız I", "I ve II", "II ve III", "I ve III", "I, II ve III"], "answer": 1, "why": ["Eksiktir; kurulmuş ve uygulanmış sözleşmeler de etkilenmez (SMK m.27/3-b, m.79/2-b, m.139/2-b).", "Kesinleşmiş ve uygulanmış kararlar ile kurulmuş ve uygulanmış sözleşmeler geçmişe etkiden korunur (SMK m.27/3, m.79/2, m.139/2).", "Koruma için sözleşmenin uygulanmış olması gerekir; III bu şartı taşımaz (SMK m.27/3-b).", "Uygulanmamış sözleşmeler koruma kapsamında değildir (SMK m.139/2-b).", "III hatalıdır; kanun 'kurulmuş ve uygulanmış' sözleşmeleri korur (SMK m.27/3-b, m.79/2-b)."], "ref": "SMK m.27/3, m.79/2, m.139/2"}, {"id": "ORT-022", "exam": "ortak", "topic": "Hükümsüzlük", "q": "Marka hükümsüzlük davasına ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Markanın hükümsüzlüğü davalarında Kurum da davalı olarak gösterilir.", "Cumhuriyet savcıları markanın hükümsüzlüğünü mahkemeden isteyebilir.", "Dava, dava tarihinde sicilde marka sahibi olarak kayıtlı kişilere veya hukuki haleflerine karşı açılır.", "Hükümsüzlük hâlleri bir kısım mal veya hizmete ilişkinse yalnız o mal veya hizmetler yönünden kısmi hükümsüzlüğe karar verilir.", "Sonraki tarihli markanın kullanımına bilerek beş yıl boyunca sessiz kalan marka sahibi, sonraki tescil kötüniyetli değilse markasını hükümsüzlük gerekçesi yapamaz."], "answer": 0, "why": ["Yanlıştır; marka hükümsüzlük davalarında Kurum taraf gösterilmez (SMK m.25/3).", "Doğrudur; menfaati olanlar, Cumhuriyet savcıları ve ilgili kamu kurumları isteyebilir (SMK m.25/2).", "Doğrudur (SMK m.25/3).", "Doğrudur (SMK m.25/5).", "Doğrudur; sessiz kalma ile hak kaybı düzenlenmiştir (SMK m.25/6)."], "ref": "SMK m.25"}, {"id": "ORT-023", "exam": "ortak", "topic": "Hükümsüzlük", "q": "SMK'ya göre patent ve tasarım hükümsüzlük davaları hangi süre içinde açılabilir?", "options": ["Yalnızca koruma süresi içinde", "Koruma süresince veya hakkın sona ermesini izleyen beş yıl içinde", "Hakkın sona ermesini izleyen on yıl içinde", "Tescil veya patentin verilmesi tarihinden itibaren beş yıl içinde", "Hakkın sona ermesini izleyen iki yıl içinde"], "answer": 1, "why": ["Hakkın sona ermesinden sonra da beş yıl içinde dava açılabilir (SMK m.138/5, m.78/3).", "Patent için (SMK m.138/5) ve tasarım için (SMK m.78/3) aynı süre öngörülmüştür.", "Kanundaki süre on yıl değil beş yıldır (SMK m.138/5).", "Süre tescil tarihinden değil; koruma süresince ve sona ermeyi izleyen beş yıl olarak düzenlenmiştir (SMK m.78/3, m.138/5).", "Kanundaki süre iki yıl değil beş yıldır (SMK m.78/3)."], "ref": "SMK m.138/5, m.78/3"}, {"id": "ORT-024", "exam": "ortak", "topic": "Kurum Kararlarına İtiraz", "q": "Marka başvurusuna ilişkin bir Kurum kararından zarar gören tarafın karara itirazına ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["İtiraz, kararın bildirim tarihinden itibaren iki ay içinde yazılı ve gerekçeli olarak Kuruma yapılır.", "İtiraz ücreti itiraz süresi içinde ödenmeli ve ödendiğine ilişkin bilgi aynı süre içinde Kuruma sunulmalıdır.", "İtiraz gerekçeleri, itiraz süresi dolduktan sonra Kurul incelemesi sırasında değiştirilebilir veya yeni gerekçeler eklenebilir.", "Şekli eksiklik içermeyen itirazlar Kurul (YİDK) tarafından incelenir.", "Kurul, itiraz hakkında yapacağı inceleme sonucunda Kurumun nihai kararını verir."], "answer": 2, "why": ["Doğrudur (SMK m.20/2).", "Doğrudur (SMK m.20/2).", "Yanlıştır; itiraz süresinden sonra gerekçeler değiştirilemez ve yeni gerekçe eklenemez (SMK m.20/2).", "Doğrudur (SMK m.21/1).", "Doğrudur (SMK m.21/4)."], "ref": "SMK m.20-21"}, {"id": "ORT-025", "exam": "ortak", "topic": "Süreler ve Yeniden Tesis", "q": "SMK m.146 uyarınca, itirazlar da dâhil Kurum nezdinde yapılacak işlemlerde süre Kanun veya ilgili yönetmelikte belirlenmemişse uyulması gereken süre ve bu süreye uyulmamasının sonucu hangisidir?", "options": ["Bildirim tarihinden itibaren bir ay; talep reddedilir.", "Bildirim tarihinden itibaren üç ay; başvuru geri çekilmiş sayılır.", "Bildirim tarihinden itibaren iki ay; Kurum re'sen ek süre verir.", "Bildirim tarihinden itibaren iki ay; talep yapılmamış sayılır.", "Bildirim tarihinden itibaren altı ay; talep yapılmamış sayılır."], "answer": 3, "why": ["Genel süre bir ay değil iki aydır; sonuç 'red' değil 'yapılmamış sayılma'dır (SMK m.146/1).", "Genel süre iki aydır ve sonuç talebin yapılmamış sayılmasıdır (SMK m.146/1).", "Kanun ek süre öngörmez; talep yapılmamış sayılır (SMK m.146/1).", "Doğrudur (SMK m.146/1).", "Genel süre altı ay değil iki aydır (SMK m.146/1)."], "ref": "SMK m.146"}, {"id": "ORT-026", "exam": "ortak", "topic": "Süreler ve Yeniden Tesis", "q": "Patent başvurusu ve patentle ilgili işlemlerde işlemlerin devam ettirilmesi ve hakların yeniden tesisine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["İşlemlerin devam ettirilmesi talebi, süreye uyulmamanın sonucunun bildiriminden itibaren üç ay içinde yapılır.", "Hakların yeniden tesisi için şartların gerektirdiği özenin gösterilmiş olması aranmaz.", "Yıllık ücrete ilişkin telafi ücretinin ödenmesi süresi bakımından işlemlerin devam ettirilmesi talep edilebilir.", "Hakların kaybı ile yeniden tesis kararının yayımı arasında buluşu iyiniyetle kullanan üçüncü kişiler kullanmaya devam edemez.", "Hakların yeniden tesisi talebi, uyulamamış sürenin bitiminden itibaren bir yılı geçmemek üzere, süreye uyulamama nedeninin ortadan kalkmasından itibaren iki ay içinde ücreti ödenerek yapılır."], "answer": 4, "why": ["Süre üç ay değil, bildirim tarihinden itibaren iki aydır (SMK m.107/1).", "Yeniden tesis, gerekli özen gösterilmesine rağmen süreye uyulamamış olmasını gerektirir (SMK m.107/2).", "Telafi ücreti süresi ve rüçhan süresi (m.93/1) bakımından devam ettirme talep edilemez (SMK m.107/4).", "Bu kişiler işletmelerinin makul ihtiyaçları ölçüsünde buluşu ücretsiz kullanmaya devam edebilir (SMK m.107/3).", "Doğrudur (SMK m.107/2)."], "ref": "SMK m.107"}, {"id": "ORT-027", "exam": "ortak", "topic": "Vekil ve Temsil", "q": "Yerleşim yeri yurt dışında bulunan bir kişinin Kurum nezdindeki işlemlerine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Ancak marka veya patent vekili tarafından temsil edilebilir; vekil olmaksızın asil tarafından yapılan işlemler yapılmamış sayılır.", "Vekil atanması isteğe bağlıdır; kişi işlemleri doğrudan kendisi yapabilir.", "Asil tarafından yapılan işlemler geçerlidir; Kurum yalnızca eksiklik bildiriminde bulunur.", "Vekile yapılan tebligat asile yapılmış sayılmaz; tebligatın ayrıca asile yapılması gerekir.", "Vekil atanmış olsa bile işlemleri asil ve vekil birlikte yürütür."], "answer": 0, "why": ["Doğrudur (SMK m.160/3).", "Yurt dışında yerleşik kişiler için vekille temsil zorunludur (SMK m.160/3).", "Vekille temsil edilmeksizin asil tarafından yapılan işlemler yapılmamış sayılır (SMK m.160/3).", "Vekil tayin edilmişse vekile yapılan tebligat asile yapılmış sayılır (SMK m.160/4).", "Vekil tayin edilmesi hâlinde tüm işlemler vekil tarafından yapılır (SMK m.160/4)."], "ref": "SMK m.160"}, {"id": "ORT-028", "exam": "ortak", "topic": "Ücretler", "q": "SMK m.161'de düzenlenen ücretlere ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Hakkın verilmesi veya tescili ile ilgili işlemlerde ücret ödeme bilgisi süresinde sunulmazsa başvuru geri çekilmiş sayılır.", "Ödenen ücretler, talebin reddedilmesi hâlinde her durumda başvuru sahibine iade edilir.", "Sicile kayıtlı hakla ilgili diğer işlemlerde ücret ödeme bilgisi süresinde sunulmazsa ilgili talep yapılmamış sayılır.", "Eksik ödenen ücret Kurumca talep sahibine bildirilir ve bildirimden itibaren bir ay içinde ödeme bilgisinin sunulması gerekir.", "Eksik ücretin bildirilmesine ilişkin usul, 15, 18, 20, 23 ve 69 uncu maddeler kapsamındaki ücretlerde uygulanmaz."], "answer": 1, "why": ["Doğrudur (SMK m.161/1).", "Yanlıştır; aksi öngörülmediği sürece ödenen ücretler iade edilmez ve Kuruma gelir kaydedilir (SMK m.161/4).", "Doğrudur (SMK m.161/2).", "Doğrudur (SMK m.161/3).", "Doğrudur; bu maddeler eksik ücret bildirimi kuralının dışında bırakılmıştır (SMK m.161/3)."], "ref": "SMK m.161"}, {"id": "ORT-029", "exam": "ortak", "topic": "Tecavüz Fiilleri", "q": "Aşağıdakilerden hangisi SMK uyarınca marka hakkına tecavüz sayılmaz?", "options": ["Marka sahibinin izni olmaksızın markanın ayırt edilemeyecek kadar benzerini kullanarak markayı taklit etmek", "Markanın taklit edildiğini bildiği hâlde taklit markalı ürünleri ithal etmek", "Marka sahibinin izniyle Türkiye'de piyasaya sunulmuş orijinal ürünleri, herhangi bir değişiklik yapmaksızın yeniden satmak", "Marka sahibi tarafından lisans yoluyla verilmiş hakları izinsiz genişletmek", "Lisans yoluyla verilmiş hakları marka sahibinin izni olmadan üçüncü kişilere devretmek"], "answer": 2, "why": ["Tecavüz sayılır (SMK m.29/1-b).", "Tecavüz sayılır (SMK m.29/1-c).", "Hak sahibi veya izniyle piyasaya sunulan ürünlerle ilgili fiiller hakkın kapsamı dışında kalır (hakkın tüketilmesi, SMK m.152/1).", "Tecavüz sayılır (SMK m.29/1-ç).", "Tecavüz sayılır (SMK m.29/1-ç)."], "ref": "SMK m.29, m.152"}, {"id": "ORT-030", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi'ne göre bir Birlik ülkesi vatandaşının diğer Birlik ülkelerinde, o ülkelerin kendi vatandaşlarına tanıdığı korumadan aynı şekilde yararlanmasını öngören ilke hangisidir?", "options": ["En çok kayrılan ulus ilkesi", "Bağımsızlık ilkesi", "Telle quelle ilkesi", "Ulusal muamele ilkesi", "Karşılıklılık ilkesi"], "answer": 3, "why": ["Bu ilke Paris'te değil TRIPS m.4'te düzenlenmiştir.", "Bağımsızlık ilkesi, farklı ülkelerde alınan hakların birbirinden bağımsız olmasıdır (Paris m.4bis, m.6).", "Menşe ülkede tescilli markanın 'olduğu gibi' kabulüne ilişkindir (Paris m.6quinquies).", "Paris m.2 uyarınca Birlik ülkeleri vatandaşları diğer Birlik ülkelerinde o ülkenin vatandaşlarına tanınan korumadan yararlanır.", "Paris'in temel ilkesi karşılıklılık değil ulusal muameledir; SMK m.3/1-ç karşılıklılığı ayrı bir dayanak olarak öngörür."], "ref": "Paris Sözleşmesi m.2"}, {"id": "ORT-031", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi'nde öngörülen rüçhan hakkı sürelerine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Patent, faydalı model, tasarım ve marka için on iki ay", "Patent için on iki ay; faydalı model, tasarım ve marka için altı ay", "Patent ve faydalı model için altı ay; tasarım ve marka için on iki ay", "Tüm sınai mülkiyet hakları için altı ay", "Patent ve faydalı model için on iki ay; endüstriyel tasarım ve marka için altı ay"], "answer": 4, "why": ["Tasarım ve marka için süre altı aydır (Paris m.4/C).", "Faydalı model için süre on iki aydır (Paris m.4/C).", "Süreler ters verilmiştir (Paris m.4/C).", "Patent ve faydalı model için süre on iki aydır (Paris m.4/C).", "Paris m.4/C uyarınca bu şekildedir; SMK de patent için 12 ay (SMK m.93/1), marka için 6 ay (SMK m.12/1) öngörür."], "ref": "Paris Sözleşmesi m.4/C"}, {"id": "ORT-032", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Bir Birlik ülkesinde alınan patentin, aynı buluş için başka bir Birlik ülkesinde ya da başka bir ülkede alınan patentin hükümsüz kılınması veya sona ermesi nedeniyle kendiliğinden hükümsüz olmaması Paris Sözleşmesi'nin hangi ilkesinin sonucudur?", "options": ["Patentlerin bağımsızlığı ilkesi", "Ulusal muamele ilkesi", "Rüçhan hakkı ilkesi", "Telle quelle ilkesi", "Hakkın tüketilmesi ilkesi"], "answer": 0, "why": ["Paris m.4bis uyarınca farklı ülkelerde aynı buluş için alınan patentler birbirinden bağımsızdır.", "Ulusal muamele yabancılara vatandaşlarla eşit muameleyi ifade eder (Paris m.2).", "Rüçhan, ilk başvuru tarihinin sonraki başvurularda esas alınmasını sağlar (Paris m.4).", "Bu ilke markalarla ilgilidir (Paris m.6quinquies).", "Tüketilme, piyasaya sunulan ürünler üzerindeki hakkın sona ermesidir; Paris'in temel ilkesi değildir (karş. SMK m.152)."], "ref": "Paris Sözleşmesi m.4bis"}, {"id": "ORT-033", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi m.6bis'te düzenlenen tanınmış marka korumasına ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Tanınmış markanın reprodüksiyonu, taklidi veya tercümesi niteliğindeki ve karışıklık yaratabilecek markanın tescili reddedilir veya iptal edilir.", "Koruma, tanınmış markanın koruma istenen ülkede tescilli olmasını şart koşar.", "Bu tür bir markanın iptalinin talep edilmesi için tescil tarihinden itibaren en az beş yıllık süre tanınmalıdır.", "Kötü niyetle tescil ettirilen veya kullanılan markaların iptali ya da kullanımının yasaklanması için süre sınırı konulamaz.", "m.6bis koruması aynı veya benzer mallar bakımından öngörülmüştür."], "answer": 1, "why": ["Doğrudur (Paris m.6bis/1).", "Yanlıştır; m.6bis tescilsiz tanınmış markaları da korur; SMK m.6/4 de bu maddeye atıf yapar.", "Doğrudur (Paris m.6bis/2).", "Doğrudur (Paris m.6bis/3).", "Doğrudur; benzer olmayan mallara genişleme TRIPS m.16/3 ile getirilmiştir."], "ref": "Paris Sözleşmesi m.6bis"}, {"id": "ORT-034", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi m.6ter uyarınca izinsiz olarak marka veya marka unsuru olarak tescili reddedilmesi ve kullanımı yasaklanması gereken işaretler arasında aşağıdakilerden hangisi yer almaz?", "options": ["Birlik ülkelerinin devlet armaları", "Birlik ülkelerinin bayrakları ve diğer devlet amblemleri", "Bir Birlik ülkesinde faaliyet gösteren özel bir şirketin ticaret unvanı ve logosu", "Birlik ülkelerince kabul edilmiş kontrol ve garanti belirten resmi işaret ve damgalar", "Uluslararası hükümetlerarası örgütlerin arma, bayrak, amblem, kısaltma ve adları"], "answer": 2, "why": ["m.6ter kapsamındadır; SMK m.5/1-g de bu maddeye göre reddedilecek işaretlere atıf yapar.", "m.6ter kapsamındadır (Paris m.6ter/1-a).", "Özel şirket işaretleri m.6ter kapsamında değildir; m.6ter devlet ve hükümetlerarası örgütlere ait işaretleri korur.", "m.6ter kapsamındadır (Paris m.6ter/1-a).", "m.6ter kapsamındadır (Paris m.6ter/1-b)."], "ref": "Paris Sözleşmesi m.6ter"}, {"id": "ORT-035", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Menşe ülkesinde usulüne uygun olarak tescil edilmiş bir markanın, kanunda sayılan istisnalar dışında diğer Birlik ülkelerinde de 'olduğu gibi' tescile kabul edilmesi ve korunması Paris Sözleşmesi'nin hangi maddesinde düzenlenmiştir?", "options": ["m.6bis", "m.6ter", "m.4", "m.6quinquies (telle quelle)", "m.2"], "answer": 3, "why": ["m.6bis tanınmış markalara ilişkindir.", "m.6ter devlet arması, bayrak ve resmi işaretlere ilişkindir.", "m.4 rüçhan hakkını düzenler.", "'Telle quelle' kuralı Paris m.6quinquies'te düzenlenmiştir; ret ancak sayılan sınırlı hâllerde mümkündür.", "m.2 ulusal muamele ilkesini düzenler."], "ref": "Paris Sözleşmesi m.6quinquies"}, {"id": "ORT-036", "exam": "ortak", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi m.5bis uyarınca sınai mülkiyet haklarının devamı için öngörülen ücretlerin ödenmesinde (ulusal mevzuat öngörürse ek ücretle) tanınması gereken ek süre (grace period) en az ne kadardır?", "options": ["Bir ay", "İki ay", "Üç ay", "On iki ay", "Altı ay"], "answer": 4, "why": ["Sözleşmedeki asgari süre bir ay değil altı aydır (Paris m.5bis/1).", "Sözleşmedeki asgari süre altı aydır (Paris m.5bis/1).", "Sözleşmedeki asgari süre altı aydır (Paris m.5bis/1).", "Sözleşme on iki ay değil, en az altı ay öngörür (Paris m.5bis/1).", "Paris m.5bis/1 en az altı aylık ek süre öngörür; SMK m.101/3'teki altı aylık ek ücretli ödeme süresi de bununla uyumludur."], "ref": "Paris Sözleşmesi m.5bis"}, {"id": "ORT-037", "exam": "ortak", "topic": "TRIPS", "q": "TRIPS Anlaşması'nı Paris Sözleşmesi'nden ayıran ve bir üyenin herhangi bir ülke vatandaşına tanıdığı avantaj, ayrıcalık, imtiyaz veya muafiyetin diğer tüm üyelerin vatandaşlarına da derhal ve koşulsuz tanınmasını öngören ilke hangisidir?", "options": ["En çok kayrılan ulus muamelesi", "Ulusal muamele", "Rüçhan hakkı", "Bağımsızlık ilkesi", "Hakkın tüketilmesi"], "answer": 0, "why": ["TRIPS m.4'te düzenlenmiştir; Paris Sözleşmesi'nde bu ilke yer almaz.", "Ulusal muamele TRIPS m.3'te yer alır ancak Paris m.2'de de bulunduğundan TRIPS'i Paris'ten ayıran ilke değildir.", "Rüçhan Paris m.4'te düzenlenmiş olup TRIPS m.2/1 ile Paris hükümleri TRIPS'e dâhil edilmiştir.", "Bağımsızlık Paris m.4bis ve m.6'da düzenlenmiştir.", "TRIPS m.6, tüketilme konusunun uyuşmazlık çözümünde ele alınmayacağını öngörür; tanımdaki ilke bu değildir."], "ref": "TRIPS m.4"}, {"id": "ORT-038", "exam": "ortak", "topic": "TRIPS", "q": "TRIPS Anlaşması'nda öngörülen asgari koruma sürelerine ilişkin aşağıdakilerden hangisi yanlıştır?", "options": ["Patent koruması, başvuru tarihinden itibaren en az yirmi yıldır.", "Markanın ilk tescili ve her yenilemesi en az yedi yıl olup tescil sınırsız yenilenebilir.", "Endüstriyel tasarımlar için asgari koruma süresi beş yıldır.", "Entegre devre topografyaları için koruma süresi en az on yıldır.", "İcracılar ve ses kaydı yapımcıları için koruma süresi en az elli yıldır."], "answer": 2, "why": ["Doğrudur (TRIPS m.33).", "Doğrudur (TRIPS m.18).", "Yanlıştır; TRIPS m.26/3 tasarımlar için en az on yıllık koruma öngörür.", "Doğrudur (TRIPS m.38).", "Doğrudur (TRIPS m.14/5)."], "ref": "TRIPS m.18, 26, 33, 38"}, {"id": "ORT-039", "exam": "ortak", "topic": "TRIPS", "q": "TRIPS Anlaşması'nın genel ilkelerine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["TRIPS, üyelere Paris Sözleşmesi'nin maddi hükümlerine uyma yükümlülüğü getirmez.", "Üyeler, TRIPS'te öngörülenden daha geniş koruma sağlayamaz.", "TRIPS'ten doğan uyuşmazlıklar yalnızca WIPO nezdinde çözülür.", "TRIPS yalnızca patent ve markaları kapsar.", "Üyeler, Anlaşma hükümlerine aykırı olmamak kaydıyla, Anlaşmanın gerektirdiğinden daha kapsamlı koruma sağlayabilir; ancak buna zorunlu değildir."], "answer": 4, "why": ["Üyeler Paris m.1-12 ve m.19'a uymakla yükümlüdür (TRIPS m.2/1).", "TRIPS bir tavan değil taban belirler (TRIPS m.1/1).", "Uyuşmazlıklar Dünya Ticaret Örgütü uyuşmazlık çözüm mekanizmasında çözülür (TRIPS m.64).", "TRIPS; telif, coğrafi işaret, tasarım, entegre devre ve açıklanmamış bilgileri de kapsar (TRIPS Kısım II).", "Doğrudur; TRIPS asgari standartlar getirir (TRIPS m.1/1)."], "ref": "TRIPS m.1, m.2"}, {"id": "ORT-040", "exam": "ortak", "topic": "TRIPS", "q": "TRIPS Anlaşması'nda coğrafi işaretler için genel korumaya ek olarak daha güçlü (ek) koruma öngörülen ürünler hangileridir?", "options": ["Şaraplar ve alkollü içkiler", "Tüm tarım ürünleri ve gıda maddeleri", "El sanatları ürünleri", "Peynirler ve süt ürünleri", "Maden suları"], "answer": 0, "why": ["TRIPS m.23 şarap ve alkollü içkilere ilişkin coğrafi işaretler için ek koruma öngörür.", "Bu ürünler TRIPS m.22'deki genel korumadan yararlanır; ek koruma yalnızca şarap ve alkollü içkiler içindir (TRIPS m.23).", "Ek koruma kapsamında değildir (TRIPS m.23).", "Ek koruma kapsamında değildir (TRIPS m.23).", "Ek koruma kapsamında değildir (TRIPS m.23)."], "ref": "TRIPS m.23"}, {"id": "PAT2-001", "exam": "patent", "topic": "Faydalı Model", "q": "6769 sayılı SMK’ya göre bir buluşun faydalı model ile korunabilmesi için aranan şartlar aşağıdakilerden hangisinde doğru olarak verilmiştir?", "options": ["Yenilik, buluş basamağı ve sanayiye uygulanabilirlik", "Yalnızca yenilik", "Yenilik ve sanayiye uygulanabilirlik", "Buluş basamağı ve sanayiye uygulanabilirlik", "Yenilik ve buluş basamağı"], "answer": 2, "why": ["Bu üç şart patent için aranır (SMK m.82/1); faydalı modelde buluş basamağı şartı yoktur.", "Yenilik tek başına yeterli değildir; sanayiye uygulanabilirlik de aranır (SMK m.142/1).", "Doğru. m.83/1’e göre yeni olan ve m.83/6 kapsamında sanayiye uygulanabilen buluşlar faydalı model ile korunur (SMK m.142/1).", "Faydalı modelde buluş basamağı aranmaz; yenilik ise vazgeçilmez şarttır (SMK m.142/1).", "Buluş basamağı faydalı model şartı değildir; sanayiye uygulanabilirlik şarttır (SMK m.142/1)."], "ref": "SMK m.142/1"}, {"id": "PAT2-002", "exam": "patent", "topic": "Faydalı Model", "q": "SMK’ya göre aşağıdaki buluşlardan hangisi faydalı model ile korunabilir?", "options": ["Yeni ve sanayiye uygulanabilir bir mekanik kilit düzeneğine (cihaza) ilişkin buluş", "Yeni bir kimyasal maddenin üretim usulüne ilişkin buluş", "Biyoteknolojik bir buluş", "Bir usul sonucu doğrudan elde edilen ürüne ilişkin buluş", "Yeni bir ilaç etken maddesine ilişkin buluş"], "answer": 0, "why": ["Doğru. Yeni ve sanayiye uygulanabilir bir cihaz buluşu m.142/3’teki istisnalara girmediğinden faydalı model ile korunabilir (SMK m.142/1).", "Kimyasal usuller ve usullere ilişkin buluşlar faydalı model kapsamı dışındadır (SMK m.142/3-a ve ç).", "Biyoteknolojik buluşlar faydalı model ile korunmaz (SMK m.142/3-c).", "Usuller veya bu usuller sonucu elde edilen ürünlere ilişkin buluşlar faydalı model ile korunmaz (SMK m.142/3-ç).", "Eczacılıkla ilgili maddelere ilişkin buluşlar faydalı model ile korunmaz (SMK m.142/3-b)."], "ref": "SMK m.142"}, {"id": "PAT2-003", "exam": "patent", "topic": "Faydalı Model", "q": "Aşağıdakilerden hangileri faydalı model ile korunamaz?\nI. Bilgisayar programlarının kendisi\nII. İnsan veya hayvan vücuduna uygulanacak cerrahi yöntemler\nIII. Bitki çeşitleri", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 4, "why": ["Eksik. II ve III de korunamaz; m.142/3, m.82’nin ikinci ve üçüncü fıkralarını faydalı modele de uygular.", "Eksik. Bilgisayar programları (m.82/2-c) ve bitki çeşitleri (m.82/3-b) de faydalı model ile korunamaz (SMK m.142/3).", "Eksik. Bitki çeşitleri de m.82/3-b uyarınca korunamaz; m.142/3 bu fıkrayı faydalı modele de uygular.", "Eksik. Bilgisayar programları m.82/2-c uyarınca buluş sayılmaz ve faydalı model konusu da olamaz (SMK m.142/3).", "Doğru. m.142/3, m.82/2 (buluş sayılmayanlar) ve m.82/3’ü (patent verilmeyenler) faydalı modele de uygular; üçü de korunamaz."], "ref": "SMK m.142/3, m.82/2-3"}, {"id": "PAT2-004", "exam": "patent", "topic": "Faydalı Model", "q": "SMK’ya göre faydalı modelin yenilik değerlendirmesine ilişkin özel kural aşağıdakilerden hangisidir?", "options": ["Yenilik yalnızca Türkiye’de yapılan açıklamalar dikkate alınarak değerlendirilir.", "Buluş konusuna katkı sağlamayan teknik özellikler yenilik değerlendirmesinde dikkate alınmaz.", "Yenilik, başvuru tarihinden önceki beş yıl içinde yapılan açıklamalarla sınırlıdır.", "Yenilik değerlendirmesinde yalnızca yazılı yayınlar dikkate alınır.", "Yenilik değerlendirmesinde özet de koruma kapsamının belirlenmesine esas alınır."], "answer": 1, "why": ["Yanlış. Tekniğin bilinen durumu dünyanın herhangi bir yerinde yapılan açıklamaları kapsar (SMK m.83/2, m.142/1).", "Doğru. Faydalı modelin yenilik değerlendirmesinde buluş konusuna katkı sağlamayan teknik özellikler dikkate alınmaz (SMK m.142/2).", "Yanlış. SMK’da böyle bir zaman sınırı yoktur; başvuru tarihinden önceki tüm açıklamalar esas alınır (SMK m.83/2).", "Yanlış. Yazılı veya sözlü tanıtım, kullanım ya da başka biçimde yapılan açıklamalar da dikkate alınır (SMK m.83/2).", "Yanlış. Özet yalnızca teknik bilgi verme amacı taşır, koruma kapsamının belirlenmesinde kullanılmaz (SMK m.92/5)."], "ref": "SMK m.142/2"}, {"id": "PAT2-005", "exam": "patent", "topic": "Faydalı Model", "q": "Faydalı model başvurusunda bulunan (A), şeklî şartlar bakımından eksiklik bulunmadığı kendisine bildirilmiştir. SMK’ya göre (A) araştırma talebini hangi süre içinde yapmalıdır?", "options": ["Başvuru tarihinden itibaren on iki ay içinde", "Bildirim tarihinden itibaren bir ay içinde", "Bildirim tarihinden itibaren üç ay içinde", "Bildirim tarihinden itibaren iki ay içinde", "Başvuru tarihinden itibaren altı ay içinde"], "answer": 3, "why": ["Yanlış. On iki aylık süre patent başvurusundaki araştırma talebi süresidir (SMK m.96/1).", "Yanlış. Bir aylık süre dönüştürme taleplerinde belge ve araştırma ücreti için öngörülmüştür (SMK m.104/1-2).", "Yanlış. Üç ay, araştırma raporuna itiraz/görüş süresidir (SMK m.143/8).", "Doğru. Eksiklik olmadığının veya giderildiğinin bildirildiği tarihten itibaren iki ay içinde ücret ödenerek araştırma talep edilir; aksi hâlde başvuru geri çekilmiş sayılır (SMK m.143/5).", "Yanlış. Faydalı model için böyle bir süre öngörülmemiştir (SMK m.143/5)."], "ref": "SMK m.143/5"}, {"id": "PAT2-006", "exam": "patent", "topic": "Faydalı Model", "q": "Faydalı model başvurusuna ilişkin araştırma raporu Bültende yayımlanmıştır. SMK’ya göre aşağıdaki ifadelerden hangileri doğrudur?\nI. Başvuru sahibi, araştırma raporunun içeriğine itiraz edebilir.\nII. Üçüncü kişiler görüş bildirebilir.\nIII. İtiraz ve görüş süresi, araştırma raporunun yayımından itibaren altı aydır.", "options": ["I ve II", "Yalnız I", "Yalnız II", "II ve III", "I, II ve III"], "answer": 0, "why": ["Doğru. Yayımdan itibaren üç ay içinde başvuru sahibi rapora itiraz edebilir, üçüncü kişiler görüş bildirebilir; süre altı ay değil üç aydır (SMK m.143/8).", "Eksik. Üçüncü kişiler de görüş bildirebilir (SMK m.143/8).", "Eksik. Başvuru sahibi de araştırma raporunun içeriğine itiraz edebilir (SMK m.143/8).", "III yanlıştır; süre araştırma raporunun yayımından itibaren üç aydır (SMK m.143/8).", "III yanlıştır; altı ay patentin verilmesine itiraz süresidir (SMK m.99/1), faydalı modelde süre üç aydır (SMK m.143/8)."], "ref": "SMK m.143/8"}, {"id": "PAT2-007", "exam": "patent", "topic": "Faydalı Model", "q": "Rakip firma (B), (C) adına verilen faydalı modelin yeni olmadığını düşünmektedir. Faydalı model verilmesi kararı Bültende yayımlanmıştır. SMK’ya göre (B)’nin başvurabileceği yol aşağıdakilerden hangisidir?", "options": ["Yayımdan itibaren altı ay içinde Kuruma 99. madde kapsamında itiraz etmek", "Yayımdan itibaren iki ay içinde Kurum kararına 100. madde kapsamında itiraz etmek", "Yetkili mahkemeden faydalı modelin hükümsüzlüğünü talep etmek", "Kurumdan faydalı modelin incelemeli patente dönüştürülmesini istemek", "Yayımdan itibaren üç ay içinde Kuruma görüş bildirerek faydalı modelin iptalini istemek"], "answer": 2, "why": ["Yanlış. Faydalı model verilmesinden sonra 99. maddedeki itiraz usulü işletilemez (SMK m.143/11).", "Yanlış. Verilme sonrası Kurum nezdinde itiraz yolu kapalıdır; yalnızca mahkemeden hükümsüzlük istenebilir (SMK m.143/11).", "Doğru. Faydalı model verildikten sonra sadece mahkemeden hükümsüzlük talep edilebilir (SMK m.143/11, m.144).", "Yanlış. Üçüncü kişiye böyle bir dönüştürme hakkı tanınmamıştır; dönüştürme yalnızca başvuru sahibince ve başvuru aşamasında istenebilir (SMK m.104).", "Yanlış. Üç aylık görüş süresi araştırma raporunun yayımına bağlıdır ve verilme sonrası iptal yolu değildir (SMK m.143/8, 143/11)."], "ref": "SMK m.143/11"}, {"id": "PAT2-008", "exam": "patent", "topic": "Faydalı Model", "q": "SMK’ya göre faydalı modele ilişkin aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Faydalı modelin koruma süresi, başvuru tarihinden başlamak üzere on yıldır ve uzatılamaz.", "Faydalı modelin koruma süresi on yıldır; yıllık ücret ödenerek beş yıl uzatılabilir.", "Faydalı modelin koruma süresi, verilme kararının yayımından itibaren on yıldır.", "Faydalı model başvurusu için ek başvuru yapılabilir.", "Faydalı modelin verilmiş olması, geçerliliği konusunda Kurumca garanti verildiği anlamına gelir."], "answer": 0, "why": ["Doğru. Başvuru tarihinden başlamak üzere faydalı modelin koruma süresi on yıldır ve bu süre uzatılamaz (SMK m.101/1).", "Yanlış. Koruma süreleri uzatılamaz (SMK m.101/1).", "Yanlış. Süre başvuru tarihinden başlar (SMK m.101/1).", "Yanlış. Faydalı model başvurusu için ek başvuru yapılamaz (SMK m.123/14).", "Yanlış. Faydalı modelin verilmesi geçerliliği ve yararlılığı konusunda Kurum garantisi olarak yorumlanamaz (SMK m.143/13)."], "ref": "SMK m.101/1, m.123/14, m.143/13"}, {"id": "PAT2-009", "exam": "patent", "topic": "Faydalı Model", "q": "Patent başvurusu işlemleri devam eden (D), başvurusunun faydalı model başvurusuna dönüştürülmesini talep etmiş; Kurum gerekli bildirimi yapmıştır. (D) bildirim tarihinden itibaren bir ay içinde gerekli belgeleri vermemiş ve araştırma ücretini ödememiştir. SMK’ya göre sonuç nedir?", "options": ["Başvuru geri çekilmiş sayılır.", "Başvuru reddedilir ve karar Bültende yayımlanır.", "Dönüştürme talebi yapılmamış sayılır ve başvuru patent başvurusu olarak işlem görmeye devam eder.", "Başvuru re’sen faydalı model başvurusu olarak işleme devam eder.", "(D)’ye eksiklikleri tamamlaması için iki aylık ek süre verilir."], "answer": 2, "why": ["Yanlış. Kanun bu durumda geri çekilmiş sayılma değil, dönüştürme talebinin yapılmamış sayılmasını öngörür (SMK m.104/1).", "Yanlış. Ret sonucu öngörülmemiştir (SMK m.104/1).", "Doğru. Bir ay içinde şartlar yerine getirilmezse dönüştürme talebi yapılmamış sayılır ve başvuru patent başvurusu olarak devam eder (SMK m.104/1).", "Yanlış. Şartlar yerine getirilmediği için dönüştürme gerçekleşmez (SMK m.104/1).", "Yanlış. Kanunda ek süre öngörülmemiştir; süre bildirimden itibaren bir aydır (SMK m.104/1)."], "ref": "SMK m.104/1"}, {"id": "PAT2-010", "exam": "patent", "topic": "Faydalı Model", "q": "SMK’ya göre faydalı model başvuru sahibi, başvurusunun patent başvurusuna dönüştürülmesini en geç ne zamana kadar talep edebilir?", "options": ["Başvurunun Bültende yayımlanmasına kadar", "Araştırma raporunun bildirim tarihini takip eden üç aylık sürenin bitimine kadar", "Faydalı model verilmesi kararının yayımına kadar", "Araştırma talebinde bulunulmasına kadar", "Başvuru tarihinden itibaren on iki ay içinde"], "answer": 1, "why": ["Yanlış. Kanun yayımı sınır olarak öngörmez; hatta yayımlanmış başvurularda dönüştürme kararı Bültende yayımlanır (SMK m.104/3).", "Doğru. Faydalı model başvuru sahibi en geç araştırma raporunun bildirim tarihini takip eden üç aylık sürenin bitimine kadar dönüştürme talep edebilir (SMK m.104/2).", "Yanlış. Süre, araştırma raporunun bildirimine bağlanmıştır (SMK m.104/2).", "Yanlış. Talep araştırma raporu düzenlendikten sonra da belirli süre içinde yapılabilir (SMK m.104/2).", "Yanlış. Böyle bir süre öngörülmemiştir (SMK m.104/2)."], "ref": "SMK m.104/2"}, {"id": "PAT2-011", "exam": "patent", "topic": "Faydalı Model", "q": "Patent ve faydalı model başvuruları arasındaki dönüştürmeye ilişkin aşağıdaki ifadelerden hangileri SMK’ya göre doğrudur?\nI. Dönüşen başvuru için talep edilmiş rüçhan hakkı, dönüşmüş başvuru için de tanınır.\nII. Daha önce dönüştürülmüş bir başvuru için yapılan yeniden dönüştürme talebi işleme alınmaz.\nIII. Dönüştürme talebi yalnızca başvuru Bültende yayımlanmadan önce yapılabilir.", "options": ["Yalnız I", "Yalnız II", "I ve II", "I ve III", "I, II ve III"], "answer": 2, "why": ["Eksik. II de doğrudur; yeniden dönüştürme talepleri işleme alınmaz (SMK m.104/5).", "Eksik. I de doğrudur; rüçhan hakkı dönüşmüş başvuruya da tanınır (SMK m.104/4).", "Doğru. I (SMK m.104/4) ve II (SMK m.104/5) doğrudur; III yanlıştır çünkü yayımlanmış başvurular da dönüştürülebilir ve kabul kararı Bültende yayımlanır (SMK m.104/3).", "III yanlıştır; m.104/3 yayımlanmış başvuruların dönüştürülmesini açıkça öngörür.", "III yanlış olduğundan bu seçenek doğru değildir (SMK m.104/3)."], "ref": "SMK m.104/3-5"}, {"id": "PAT2-012", "exam": "patent", "topic": "Faydalı Model", "q": "Aşağıdakilerden hangisi SMK’da sayılan faydalı modelin hükümsüzlük nedenlerinden biri değildir?", "options": ["Faydalı model konusunun yeni olmaması", "Buluşun m.92/1 uyarınca yeterince açıklanmamış olması", "Faydalı model konusunun, buluş basamağı içermemesi", "Faydalı model konusunun başvurunun ilk hâlinin kapsamını aşması", "Faydalı model sahibinin m.109’a göre faydalı model isteme hakkına sahip olmadığının ispatlanması"], "answer": 2, "why": ["Hükümsüzlük nedenidir; konu m.142’deki şartları (yenilik) taşımıyorsa hükümsüzlüğe karar verilir (SMK m.144/1-a).", "Hükümsüzlük nedenidir (SMK m.144/1-b).", "Doğru cevap. Faydalı modelde buluş basamağı şartı aranmadığından (SMK m.142/1) bu durum m.144/1’de hükümsüzlük nedeni olarak yer almaz.", "Hükümsüzlük nedenidir (SMK m.144/1-c).", "Hükümsüzlük nedenidir; ancak yalnızca buluşu yapan veya halefleri ileri sürebilir (SMK m.144/1-ç, 144/2)."], "ref": "SMK m.144/1"}, {"id": "PAT2-013", "exam": "patent", "topic": "Faydalı Model", "q": "SMK’ya göre faydalı modelin hükümsüzlüğüne ilişkin aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Hükümsüzlük davası, koruma süresince veya hakkın sona ermesini izleyen beş yıl içinde açılabilir.", "Dava, sicilde faydalı model sahibi olarak kayıtlı kişiye karşı açılır.", "Cumhuriyet savcıları da faydalı modelin hükümsüzlüğünü isteyebilir.", "Hükümsüzlük nedenleri faydalı modelin bir bölümüne ilişkinse kısmi hükümsüzlüğe karar verilir.", "Kısmi hükümsüzlük hâlinde bir istemin kısmen hükümsüzlüğüne de karar verilebilir."], "answer": 4, "why": ["Doğrudur (SMK m.144/3).", "Doğrudur; sicilde hak sahibi görünen kişilere ayrıca tebligat yapılır (SMK m.144/3).", "Doğrudur; menfaati olanlar, Cumhuriyet savcıları veya ilgili kamu kurum ve kuruluşları hükümsüzlüğü isteyebilir (SMK m.144/2).", "Doğrudur; yalnızca o bölümü etkileyen istemler iptal edilir (SMK m.144/5).", "Yanlış ifade, doğru cevap. Bir istemin kısmen hükümsüzlüğüne karar verilemez (SMK m.144/5)."], "ref": "SMK m.144"}, {"id": "PAT2-014", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "SMK m.83/3’e göre, başvuru tarihinden önceki tarihli olup başvuru tarihinde veya sonrasında yayımlanan aşağıdaki başvurulardan hangilerinin ilk içerikleri tekniğin bilinen durumu olarak dikkate alınır?\nI. PCT uyarınca yapılıp PCT’nin 22. ve 39. maddelerine göre yönetmelikteki şartlara uygun olarak ulusal aşamaya giriş yapan başvurular\nII. EPC m.79/2’ye göre Türkiye’nin belirlendiği ve ilgili belirleme ücretinin ödendiği Avrupa patent başvuruları\nIII. Türkiye’nin belirlenmediği Avrupa patent başvuruları", "options": ["Yalnız I", "I ve II", "Yalnız II", "II ve III", "I, II ve III"], "answer": 1, "why": ["Eksik. Türkiye’nin belirlendiği ve belirleme ücreti ödenen Avrupa patent başvuruları da kapsamdadır (SMK m.83/3-b).", "Doğru. m.83/3-a ulusal aşamaya giren PCT başvurularını, m.83/3-b Türkiye’nin belirlendiği ve ücreti ödenen Avrupa başvurularını kapsar; Türkiye’nin belirlenmediği başvurular sayılmamıştır.", "Eksik. Ulusal aşamaya giren PCT başvuruları da kapsamdadır (SMK m.83/3-a).", "III yanlıştır; m.83/3-b Türkiye’nin belirlenmesini ve belirleme ücretinin ödenmesini şart koşar.", "III yanlıştır; Türkiye’nin belirlenmediği Avrupa başvuruları m.83/3 kapsamında değildir."], "ref": "SMK m.83/3"}, {"id": "PAT2-015", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "Türkiye’de ulusal aşamaya girmiş, (E)’nin başvuru tarihinden önce yapılmış ancak (E)’nin başvuru tarihinden sonra yayımlanmış bir PCT başvurusu bulunmaktadır. SMK’ya göre bu başvurunun içeriği (E)’nin patent başvurusunun değerlendirilmesinde nasıl dikkate alınır?", "options": ["Yenilik değerlendirmesinde dikkate alınır, buluş basamağı değerlendirmesinde dikkate alınmaz.", "Hiçbir şekilde dikkate alınmaz.", "Yalnızca buluş basamağı değerlendirmesinde dikkate alınır.", "Yalnızca sanayiye uygulanabilirlik değerlendirmesinde dikkate alınır.", "Hem yenilik hem buluş basamağı değerlendirmesinde dikkate alınır."], "answer": 0, "why": ["Doğru. m.83/3 uyarınca tekniğin bilinen durumu sayılan başvurular yalnızca yenilikte dikkate alınır; buluş basamağında dikkate alınmaz (SMK m.83/3, 83/5).", "Yanlış. Ulusal aşamaya giren PCT başvurusunun ilk içeriği tekniğin bilinen durumu sayılır (SMK m.83/3-a).", "Yanlış. Durum tersidir; bu içerik buluş basamağında dikkate alınmaz (SMK m.83/5).", "Yanlış. Sanayiye uygulanabilirlik tekniğin bilinen durumuna göre değerlendirilmez (SMK m.83/6).", "Yanlış. m.83/3 kapsamındaki başvurular buluş basamağı değerlendirmesinde dikkate alınmaz (SMK m.83/5)."], "ref": "SMK m.83/3, m.83/5"}, {"id": "PAT2-016", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "SMK m.83/3-a’da atıf yapılan Patent İşbirliği Antlaşması’nın (PCT) 22. ve 39. maddeleri esas olarak hangi konuyu düzenler?", "options": ["Uluslararası araştırma raporunun düzenlenmesini", "Belirlenmiş/seçilmiş ofislerde ulusal aşamaya giriş için gerekli işlemleri ve süreleri", "Uluslararası başvurunun 18. ayda yayımlanmasını", "İstemlerde Uluslararası Büro nezdinde yapılan değişiklikleri", "Biyolojik materyalin tevdi edilmesini"], "answer": 1, "why": ["Yanlış. Uluslararası araştırma PCT m.15-18’de düzenlenir.", "Doğru. PCT m.22 (Bölüm I, belirlenmiş ofis) ve m.39 (Bölüm II, seçilmiş ofis), çeviri ve ücret gibi ulusal aşama işlemlerini ve 30 aylık süreyi düzenler; SMK m.83/3-a bu maddelere atıf yapar.", "Yanlış. Uluslararası yayım PCT m.21’de düzenlenir.", "Yanlış. İstemlerde Uluslararası Büro nezdinde değişiklik PCT m.19’da düzenlenir.", "Yanlış. Biyolojik materyal tevdii Budapeşte Antlaşması ve SMK m.92/2-3’te düzenlenir."], "ref": "SMK m.83/3-a; PCT m.22, 39"}, {"id": "PAT2-017", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "SMK m.83/3-b’ye göre, uluslararası başvuruya dayanan (Euro-PCT) bir Avrupa patent başvurusunun Türkiye bakımından tekniğin bilinen durumu sayılması için Avrupa Patent Sözleşmesi’nin hangi hükmündeki gerekliliklerin sağlanması aranır?", "options": ["EPC m.54/3", "EPC m.99/1", "EPC m.153/5", "EPC m.65", "EPC m.79/2"], "answer": 2, "why": ["Yanlış. SMK m.83/3-b Euro-PCT başvuruları için EPC m.153/5’e atıf yapar.", "Yanlış. EPC m.99 itirazı düzenler; SMK m.83/3-b’de atıf yapılan hüküm değildir.", "Doğru. SMK m.83/3-b, EPC m.153/5’teki gereklilikleri sağlayan, uluslararası başvuruya dayanan Avrupa patent başvurularını kapsar.", "Yanlış. EPC m.65 çeviri şartıyla ilgilidir; SMK m.83/3-b’de atıf yapılmaz.", "Yanlış. EPC m.79/2’ye SMK m.83/3-b’de doğrudan yapılan Avrupa başvuruları (Türkiye’nin belirlenmesi ve belirleme ücreti) için atıf yapılır; Euro-PCT için ölçüt m.153/5’tir."], "ref": "SMK m.83/3-b"}, {"id": "PAT2-018", "exam": "patent", "topic": "Avrupa Patenti", "q": "Türkiye’yi kapsayan bir Avrupa patentinin Türkiye’de geçerlilik kazanması (validasyon) ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Avrupa patenti verildiği anda, hiçbir işlem yapılmasına gerek olmaksızın Türkiye’de birim (üniter) etkili patent olarak geçerlidir.", "Patent fasikülünün Türkçe çevirisi, patentin verildiğinin Avrupa Patent Bülteninde yayımlandığı tarihten itibaren üç ay içinde Kuruma sunulmalıdır.", "Türkçe çeviri, Avrupa patent başvurusunun yapıldığı tarihten itibaren on sekiz ay içinde sunulmalıdır.", "Avrupa patentlerinin Türkiye’de geçerliliği, ayrıca Kurum tarafından esasa ilişkin inceleme yapılmasına bağlıdır.", "EPC, taraf devletlerin çeviri istemesini yasaklamaktadır."], "answer": 1, "why": ["Yanlış. Birim etkili patent yalnızca katılımcı AB üyesi devletleri kapsar; Türkiye için ulusal validasyon gerekir.", "Doğru. EPC m.65 taraf devletlere çeviri isteme imkânı verir; Türkiye’de çeviri, patentin verildiğinin Avrupa Patent Bülteninde yayımlanmasından itibaren üç ay içinde Kuruma sunulur (Patent Yönetmeliği).", "Yanlış. Çeviri süresi verilme bildiriminin yayımına bağlıdır; 18 ay yayım süresidir.", "Yanlış. Esasa ilişkin inceleme EPO tarafından yapılmıştır; validasyon çeviri ve ücret gibi şeklî işlemlerden ibarettir.", "Yanlış. EPC m.65/1 taraf devletlere çeviri isteme yetkisi tanır."], "ref": "EPC m.65; Patent Yönetmeliği"}, {"id": "PAT2-019", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "SMK geçici m.1/2’ye göre, SMK’nın yürürlüğe girdiği tarihten önce ulusal aşamaya girmiş uluslararası veya bölgesel anlaşmalar yoluyla yapılmış patent başvuruları hangi mevzuata göre sonuçlandırılır?", "options": ["Uluslararası başvuru tarihinde yürürlükte olan mevzuata göre", "Rüçhan tarihinde yürürlükte olan mevzuata göre", "Başvurunun ulusal aşamaya girdiği tarihte yürürlükte olan mevzuata göre", "Karar tarihinde yürürlükte olan SMK hükümlerine göre", "Başvuru sahibinin seçimine göre eski veya yeni mevzuata göre"], "answer": 2, "why": ["Yanlış. Kanun ölçüt olarak ulusal aşamaya giriş tarihini esas almıştır (SMK geçici m.1/2).", "Yanlış. Rüçhan tarihi ölçüt değildir (SMK geçici m.1/2).", "Doğru. Bu başvurular ulusal aşamaya girdiği tarihte yürürlükte olan mevzuat hükümlerine göre sonuçlandırılır (SMK geçici m.1/2).", "Yanlış. Ulusal aşamaya giriş tarihindeki mevzuat uygulanır (SMK geçici m.1/2).", "Yanlış. Kanunda seçim hakkı tanınmamıştır (SMK geçici m.1/2)."], "ref": "SMK geçici m.1/2"}, {"id": "PAT2-020", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "SMK’ya göre başvurunun yayımı ile PCT’ye göre uluslararası yayım birlikte değerlendirildiğinde aşağıdaki ifadelerden hangisi doğrudur?", "options": ["SMK’da yayım süresi yalnızca patent başvuruları için öngörülmüş olup faydalı model başvuruları yayımlanmaz.", "SMK’ya göre başvuru, başvuru tarihinden itibaren otuz ay dolunca yayımlanır.", "PCT’de uluslararası yayım, ulusal aşamaya girişten sonra belirlenmiş ofislerce yapılır.", "Hem SMK’da hem PCT’de yayım kural olarak başvuru veya varsa rüçhan tarihinden itibaren on sekiz ayın dolmasıyla yapılır ve erken yayım istenebilir.", "SMK’da erken yayım talebi mümkün değildir."], "answer": 3, "why": ["Yanlış. SMK m.97/1 patent veya faydalı model başvurusunun yayımını düzenler.", "Yanlış. Süre on sekiz aydır (SMK m.97/1).", "Yanlış. Uluslararası yayımı Uluslararası Büro yapar ve bu yayım ulusal aşamadan önce, 18. ayda gerçekleşir (PCT m.21).", "Doğru. SMK m.97/1’e göre başvuru veya rüçhan tarihinden itibaren 18 ay dolunca ya da erken yayım talebiyle yayım yapılır; PCT m.21/2 de rüçhan tarihinden itibaren 18 ayı öngörür ve erken yayıma izin verir.", "Yanlış. Başvuru sahibi 18 ay dolmadan erken yayım talep edebilir (SMK m.97/1)."], "ref": "SMK m.97/1; PCT m.21"}, {"id": "PAT2-021", "exam": "patent", "topic": "Uluslararası Başvurular (SMK)", "q": "Japonya’da 10.02.2025 tarihinde ilk patent başvurusunu yapan (F), aynı buluş için Türkiye’de rüçhan hakkı talebiyle başvuru yapmak istemektedir. SMK’ya göre aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["(F), Türkiye’ye en geç 10.02.2026 tarihine kadar başvurmalıdır.", "Rüçhan hakkı talebi, başvuruyla birlikte veya başvuru tarihinden itibaren iki ay içinde ücreti ödenerek yapılabilir.", "Rüçhan hakkı talebine ilişkin belgeler, başvuru tarihinden itibaren üç ay içinde Kuruma sunulmalıdır.", "Paris Sözleşmesine taraf bir devlette yapılan, ulusal başvuruya eşdeğer bölgesel veya uluslararası başvurular da rüçhan hakkı doğurur.", "Japon başvurusunun sonradan reddedilmesi, rüçhan hakkını ortadan kaldırır."], "answer": 4, "why": ["Doğrudur. Rüçhan süresi ilk başvuru tarihinden itibaren on iki aydır (SMK m.93/1).", "Doğrudur (SMK m.94/1).", "Doğrudur; aksi hâlde rüçhan talebi yapılmamış sayılır (SMK m.94/1).", "Doğrudur; ikili veya çok taraflı anlaşmalara göre ulusal başvuruya eşdeğer her başvuru rüçhan doğurur (SMK m.93/2).", "Yanlış ifade, doğru cevap. Usulüne uygun ulusal başvuru, sonucu ne olursa olsun rüçhan doğurur (SMK m.93/3)."], "ref": "SMK m.93, m.94"}, {"id": "PAT2-022", "exam": "patent", "topic": "PCT", "q": "Patent İşbirliği Antlaşması (PCT) ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["PCT, Dünya Fikri Mülkiyet Örgütü (WIPO) tarafından yönetilir.", "Uluslararası başvuru, kural olarak başvuru tarihinde taraf devletlerin tamamının belirlenmesi sonucunu doğurur.", "Uluslararası başvuru, bir ulusal ofise veya alıcı ofis sıfatıyla Uluslararası Büroya yapılabilir.", "PCT sonucunda Uluslararası Büro tarafından tüm taraf devletlerde geçerli tek bir “uluslararası patent” verilir.", "Patentin verilip verilmeyeceğine ulusal aşamada her belirlenmiş ofis kendi mevzuatına göre karar verir."], "answer": 3, "why": ["Doğrudur; PCT’yi WIPO Uluslararası Bürosu yönetir.", "Doğrudur; başvurunun yapılmasıyla tüm taraf devletler belirlenmiş sayılır (PCT Kural 4.9).", "Doğrudur; alıcı ofis ulusal ofis veya WIPO Uluslararası Bürosu olabilir (PCT Kural 19).", "Yanlış ifade, doğru cevap. PCT bir başvuru sistemidir; “uluslararası patent” verilmez, patent verme yetkisi ulusal/bölgesel ofislerdedir.", "Doğrudur; verilme kararı ulusal aşamada belirlenmiş/seçilmiş ofislere aittir (PCT m.27/5)."], "ref": "PCT m.27; Kural 4.9"}, {"id": "PAT2-023", "exam": "patent", "topic": "PCT", "q": "PCT’ye göre uluslararası başvurunun uluslararası yayımı ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Uluslararası Büro tarafından, kural olarak rüçhan tarihinden itibaren on sekiz ayın dolmasından hemen sonra yapılır.", "Uluslararası Araştırma Kurumu tarafından, araştırma raporuyla birlikte otuzuncu ayda yapılır.", "Alıcı ofis tarafından başvuru tarihinden itibaren on iki ay içinde yapılır.", "Yalnızca Bölüm II talebinde bulunulmuşsa yapılır.", "Başvuru sahibinin talebi olmadan erken yayım yapılması zorunludur."], "answer": 0, "why": ["Doğru. Uluslararası yayım Uluslararası Büro tarafından rüçhan tarihinden itibaren 18 ay dolduktan sonra derhâl yapılır; başvuru sahibi erken yayım isteyebilir (PCT m.21/2).", "Yanlış. Yayımı Uluslararası Büro yapar ve süre 18 aydır (PCT m.21).", "Yanlış. Yayım alıcı ofisin görevi değildir; süre 18 aydır (PCT m.21).", "Yanlış. Uluslararası yayım Bölüm II talebinden bağımsızdır (PCT m.21).", "Yanlış. Erken yayım başvuru sahibinin talebine bağlıdır (PCT m.21/2-b)."], "ref": "PCT m.21"}, {"id": "PAT2-024", "exam": "patent", "topic": "PCT", "q": "PCT’ye göre uluslararası araştırma aşaması ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Uluslararası Araştırma Kurumu, uluslararası araştırma raporu ile birlikte bir yazılı görüş düzenler.\nII. Uluslararası araştırma raporu, araştırma kopyasının alınmasından itibaren üç ay veya rüçhan tarihinden itibaren dokuz aydan hangisi daha geç sona eriyorsa o süre içinde düzenlenir.\nIII. Uluslararası araştırma raporu belirlenmiş ofisleri bağlar; ofisler rapordan farklı karar veremez.", "options": ["Yalnız I", "Yalnız II", "I ve III", "II ve III", "I ve II"], "answer": 4, "why": ["Eksik. II de doğrudur (PCT Kural 42.1).", "Eksik. I de doğrudur; araştırma kurumu yazılı görüş de düzenler (PCT Kural 43bis).", "III yanlıştır; araştırma raporu belirlenmiş ofisleri bağlamaz, ulusal ofisler patent verilebilirliğe kendileri karar verir.", "III yanlıştır; rapor bağlayıcı değildir.", "Doğru. Yazılı görüş Kural 43bis’e, süre Kural 42.1’e dayanır; araştırma raporu ise belirlenmiş ofisleri bağlamaz."], "ref": "PCT Kural 42, 43bis"}, {"id": "PAT2-025", "exam": "patent", "topic": "PCT", "q": "PCT m.19 uyarınca yapılan değişikliklerle ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Tarifname, istemler ve resimlerde değişiklik yapılabilir.", "Değişiklikler Uluslararası Ön İnceleme Kurumu nezdinde yapılır.", "Yalnızca istemlerde, Uluslararası Büro nezdinde ve kural olarak araştırma raporunun gönderilmesinden itibaren iki ay veya rüçhan tarihinden itibaren on altı aydan hangisi daha geç sona eriyorsa o süre içinde yapılabilir.", "Değişiklik süresi rüçhan tarihinden itibaren otuz aydır.", "Bu değişiklikler başvurunun ilk hâlinin kapsamını aşabilir."], "answer": 2, "why": ["Yanlış. Tarifname ve resimlerin de değiştirilebilmesi Bölüm II’deki m.34 değişikliklerine özgüdür; m.19 yalnızca istemleri kapsar.", "Yanlış. m.19 değişiklikleri Uluslararası Büroya sunulur; ön inceleme kurumu nezdindeki değişiklikler m.34’e göredir.", "Doğru. PCT m.19 yalnızca istemlerde, Uluslararası Büro nezdinde değişikliğe izin verir; süre Kural 46.1’e göre 2 ay/16 aydan geç olanıdır. Kısa bir açıklama da eklenebilir.", "Yanlış. 30 ay ulusal aşamaya giriş süresidir (PCT m.22).", "Yanlış. Değişiklikler başvurunun ilk hâlindeki açıklamanın kapsamını aşamaz (PCT m.19/2)."], "ref": "PCT m.19; Kural 46.1"}, {"id": "PAT2-026", "exam": "patent", "topic": "PCT", "q": "PCT Bölüm II kapsamında uluslararası ön inceleme talebiyle ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Talep, rüçhan tarihinden itibaren on iki ay içinde yapılmak zorundadır.", "Talep, kural olarak araştırma raporu ve yazılı görüşün gönderilmesinden itibaren üç ay veya rüçhan tarihinden itibaren yirmi iki aydan hangisi daha geç sona eriyorsa o süre içinde yapılır.", "Bölüm II talebi zorunludur; talepte bulunulmayan başvurular geri çekilmiş sayılır.", "Bölüm II kapsamında yalnızca istemlerde değişiklik yapılabilir.", "Uluslararası ön inceleme raporu seçilmiş ofisleri bağlar."], "answer": 1, "why": ["Yanlış. Bölüm II talebi için öngörülen süre 3 ay/22 aydan geç olanıdır (PCT Kural 54bis.1).", "Doğru. PCT Kural 54bis.1’e göre talep süresi, ISR ve yazılı görüşün gönderilmesinden itibaren 3 ay veya rüçhandan itibaren 22 aydan hangisi daha geç biterse odur.", "Yanlış. Bölüm II isteğe bağlıdır (PCT m.31).", "Yanlış. m.34 uyarınca istemler, tarifname ve resimlerde değişiklik yapılabilir.", "Yanlış. Uluslararası ön inceleme raporu bağlayıcı olmayan bir görüştür; seçilmiş ofisler kendi mevzuatına göre karar verir (PCT m.33/1)."], "ref": "PCT m.31, 34; Kural 54bis.1"}, {"id": "PAT2-027", "exam": "patent", "topic": "PCT", "q": "PCT m.33’e göre uluslararası ön incelemede istem konusu buluş hangi ölçütler bakımından değerlendirilir?\nI. Yenilik\nII. Buluş basamağı (aşikâr olmama)\nIII. Sanayiye uygulanabilirlik", "options": ["Yalnız I", "I ve II", "I ve III", "I, II ve III", "II ve III"], "answer": 3, "why": ["Eksik. Buluş basamağı ve sanayiye uygulanabilirlik de incelenir (PCT m.33/1).", "Eksik. Sanayiye uygulanabilirlik de incelenir (PCT m.33/1, 33/4).", "Eksik. Buluş basamağı da incelenir (PCT m.33/1, 33/3).", "Doğru. Uluslararası ön inceleme, istem konusu buluşun yeni, buluş basamağı içeren ve sanayiye uygulanabilir olup olmadığı hakkında bağlayıcı olmayan bir görüş oluşturmayı amaçlar (PCT m.33/1).", "Eksik. Yenilik de incelenir (PCT m.33/1-2)."], "ref": "PCT m.33"}, {"id": "PAT2-028", "exam": "patent", "topic": "PCT", "q": "(G), ilk başvurusunu 15.01.2024 tarihinde yapmış ve bu başvurunun rüçhanını talep ederek PCT başvurusunda bulunmuştur. PCT m.22’ye göre Türkiye gibi belirlenmiş bir ofiste ulusal aşamaya giriş için genel süre ve Avrupa Patent Ofisi nezdinde bölgesel aşamaya giriş süresi sırasıyla en geç hangi tarihlerde sona erer?", "options": ["15.01.2026 – 15.01.2026", "15.07.2025 – 15.08.2025", "15.07.2026 – 15.07.2026", "15.07.2026 – 15.08.2026", "15.01.2027 – 15.02.2027"], "answer": 3, "why": ["Yanlış. 24 aylık bir süre öngörülmemiştir; PCT’de süre rüçhandan itibaren 30 aydır.", "Yanlış. 18 ay uluslararası yayım süresidir (PCT m.21).", "Yanlış. EPO bölgesel aşamaya giriş için 31 ay öngörür (EPC Kural 159/1).", "Doğru. PCT m.22/1’e göre ulusal aşama süresi rüçhan tarihinden itibaren 30 ay (15.07.2026), EPO’da ise Kural 159/1 uyarınca 31 aydır (15.08.2026).", "Yanlış. 36 ay ve 37 ay gibi süreler öngörülmemiştir."], "ref": "PCT m.22; EPC Kural 159"}, {"id": "PAT2-029", "exam": "patent", "topic": "PCT", "q": "PCT sistemi ile ilgili aşağıdaki aşamalar kronolojik olarak (kural olarak) hangi sırayla gerçekleşir?\nI. Uluslararası yayım\nII. Ulusal aşamaya giriş\nIII. Uluslararası araştırma raporu ve yazılı görüşün düzenlenmesi\nIV. Rüçhan hakkı talep edilen ilk başvurunun yapılması", "options": ["IV – I – III – II", "III – IV – I – II", "IV – III – II – I", "IV – II – III – I", "IV – III – I – II"], "answer": 4, "why": ["Yanlış. Araştırma raporu (kural olarak en geç 9. ay civarı) yayımdan (18. ay) önce düzenlenir.", "Yanlış. Rüçhan dayanağı ilk başvuru her şeyden önce gelir.", "Yanlış. Ulusal aşamaya giriş (30. ay) uluslararası yayımdan (18. ay) sonradır.", "Yanlış. Ulusal aşama süreçteki son aşamadır (PCT m.22).", "Doğru. Sıra: ilk başvuru (0. ay) → ISR ve yazılı görüş (Kural 42: 3 ay/9 ay) → uluslararası yayım (18. ay, m.21) → ulusal aşama (30. ay, m.22)."], "ref": "PCT m.21, 22; Kural 42"}, {"id": "PAT2-030", "exam": "patent", "topic": "EPC", "q": "Avrupa Patent Sözleşmesi’ne (EPC) göre Avrupa patentine itiraz ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["İtiraz, patentin verildiğine ilişkin bildirimin Avrupa Patent Bülteninde yayımlanmasından itibaren dokuz ay içinde yapılabilir.", "İtiraz, verilme kararının yayımından itibaren altı ay içinde yapılabilir.", "İtiraz yalnızca belirlenmiş devletlerin ulusal ofislerine yapılabilir.", "İtiraz yalnızca menfaati olduğunu ispatlayan kişilerce yapılabilir.", "İtiraz yalnızca itiraz edenin belirttiği devlet bakımından sonuç doğurur."], "answer": 0, "why": ["Doğru. EPC m.99/1’e göre herkes, verilme bildiriminin Avrupa Patent Bülteninde yayımlanmasından itibaren dokuz ay içinde EPO’ya itiraz edebilir.", "Yanlış. Altı ay, SMK’daki ulusal patent itiraz süresidir (SMK m.99/1); EPC’de süre dokuz aydır.", "Yanlış. İtiraz EPO nezdinde yapılır ve itiraz birimleri tarafından incelenir (EPC m.99, 19).", "Yanlış. EPC m.99/1 “herkes” ifadesini kullanır; menfaat ispatı aranmaz.", "Yanlış. İtiraz, patentin hüküm ifade ettiği tüm taraf devletler bakımından sonuç doğurur (EPC m.99/2)."], "ref": "EPC m.99"}, {"id": "PAT2-031", "exam": "patent", "topic": "EPC", "q": "EPO uygulamasında buluş basamağının değerlendirilmesinde kullanılan “problem-çözüm yaklaşımı” (problem-solution approach) ile ilgili aşağıdakilerden hangisi bu yaklaşımın aşamalarından biri değildir?", "options": ["En yakın önceki tekniğin belirlenmesi", "Objektif teknik problemin belirlenmesi", "İstem konusu buluşun, en yakın önceki teknik ve objektif teknik problemden hareketle uzman kişi için aşikâr olup olmadığının değerlendirilmesi", "Buluşun ticari başarısının, buluş basamağının tek ve belirleyici ölçütü olarak esas alınması", "En yakın önceki teknikle istem arasındaki ayırt edici teknik özelliklerin ve bunların teknik etkisinin tespiti"], "answer": 3, "why": ["Yaklaşımın ilk aşamasıdır.", "Yaklaşımın ikinci aşamasıdır; ayırt edici özelliklerin teknik etkisinden hareketle belirlenir.", "Yaklaşımın üçüncü aşamasıdır (“could-would” yaklaşımı ile değerlendirilir).", "Doğru cevap. Ticari başarı en fazla yardımcı bir gösterge olabilir; problem-çözüm yaklaşımının bir aşaması değildir.", "Objektif teknik problemin belirlenmesi için yapılan zorunlu bir tespittir."], "ref": "EPC m.56; EPO İnceleme Kılavuzu"}, {"id": "PAT2-032", "exam": "patent", "topic": "EPC", "q": "EPC’ye göre aşağıdaki ifadelerden hangileri doğrudur?\nI. Avrupa Patent Teşkilatının organları Avrupa Patent Ofisi (EPO) ve İdari Konsey’dir.\nII. EPO’nun resmî dilleri İngilizce, Fransızca ve Almancadır.\nIII. Avrupa patenti, verildiği her taraf devlette o devletin ulusal patenti ile aynı etkiyi doğurur.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 4, "why": ["Eksik. II ve III de doğrudur (EPC m.14/1, m.2/2).", "Eksik. I ve III de doğrudur (EPC m.4/2, m.2/2).", "Eksik. III de doğrudur; Avrupa patenti her taraf devlette ulusal patent etkisine sahiptir (EPC m.2/2, m.64/1).", "Eksik. I de doğrudur (EPC m.4/2).", "Doğru. Organlar EPO ve İdari Konsey’dir (EPC m.4/2); resmî diller İngilizce, Fransızca ve Almancadır (EPC m.14/1); Avrupa patenti ulusal patent etkisi doğurur (EPC m.2/2)."], "ref": "EPC m.2, 4, 14"}, {"id": "PAT2-033", "exam": "patent", "topic": "EPC", "q": "Birim etkili Avrupa patenti (Unitary Patent) ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Birim etkili patent sistemi 1 Haziran 2023 tarihinde uygulanmaya başlamıştır.", "Birim etki talebi, Avrupa patentinin verildiğine ilişkin bildirimin yayımından itibaren bir ay içinde EPO’ya yapılır.", "Birim etkili patent, Birleşik Patent Mahkemesi Anlaşmasını onaylamış katılımcı AB üyesi devletlerde tek bir hak olarak etki doğurur.", "Türkiye EPC’ye taraf olduğundan birim etkili patent Türkiye’yi de kapsar.", "Birim etkili patent, EPO tarafından verilmiş bir Avrupa patentine dayanır."], "answer": 3, "why": ["Doğrudur; sistem 1 Haziran 2023’te yürürlüğe girmiştir.", "Doğrudur; birim etki talebi verilme bildiriminin yayımından itibaren bir ay içinde yapılır (AB Tüzüğü 1257/2012 ve EPO uygulama kuralları).", "Doğrudur; birim etki yalnızca katılımcı AB üyesi devletleri kapsar.", "Yanlış ifade, doğru cevap. Birim etkili patent AB hukukuna (Tüzük 1257/2012) dayanır; AB üyesi olmayan Türkiye’yi kapsamaz. Türkiye için klasik validasyon gerekir.", "Doğrudur; birim etki, EPC hükümlerine göre verilen Avrupa patentine sonradan tanınır."], "ref": "AB Tüzüğü 1257/2012"}, {"id": "PAT2-034", "exam": "patent", "topic": "EPC", "q": "Buluşun başvuru öncesinde açıklanmasının yeniliği etkilemeyeceği hâllere (ihmal edilebilir/zararsız açıklama) ilişkin SMK ve EPC hükümleri karşılaştırıldığında aşağıdakilerden hangisi doğrudur?", "options": ["Her iki düzenlemede de süre on iki aydır ve buluşu yapanın kendi açıklaması kapsamdadır.", "EPC’de süre altı ay olup açıklamanın açık bir kötüye kullanımdan veya resmî/resmen tanınmış uluslararası sergide teşhirden kaynaklanması gerekir; SMK’da ise süre on iki aydır ve buluşu yapanın kendi açıklaması da kapsamdadır.", "SMK’da süre altı ay, EPC’de on iki aydır.", "Her iki düzenlemede de böyle bir istisna bulunmamaktadır.", "SMK’da istisna yalnızca faydalı model için, EPC’de yalnızca patent için geçerlidir."], "answer": 1, "why": ["Yanlış. EPC m.55 buluşu yapanın kendi açıklamasını genel olarak kapsamaz ve süre altı aydır.", "Doğru. EPC m.55/1 altı aylık süre ve sınırlı hâller (açık kötüye kullanım, resmî sergi) öngörür; SMK m.84/1 on iki aylık süre içinde buluşu yapanın kendi açıklamasını da kapsar.", "Yanlış. Süreler tersine verilmiştir (SMK m.84/1, EPC m.55/1).", "Yanlış. Her iki düzenlemede de istisna mevcuttur (SMK m.84, EPC m.55).", "Yanlış. SMK m.84 hem patent hem faydalı model için uygulanır."], "ref": "SMK m.84; EPC m.55"}, {"id": "PAT2-035", "exam": "patent", "topic": "EPC", "q": "EPC’ye göre başvuru tarihinden önceki tarihli olup başvuru tarihinde veya sonrasında yayımlanan Avrupa patent başvurularının içeriği ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Hem yenilik hem buluş basamağı değerlendirmesinde tekniğin bilinen durumu sayılır.", "Hiçbir şekilde tekniğin bilinen durumu sayılmaz.", "Yalnızca buluş basamağı değerlendirmesinde dikkate alınır.", "Yalnızca sanayiye uygulanabilirlik değerlendirmesinde dikkate alınır.", "Yalnızca yenilik değerlendirmesinde tekniğin bilinen durumu sayılır; buluş basamağı değerlendirmesinde dikkate alınmaz."], "answer": 4, "why": ["Yanlış. EPC m.56 ikinci cümlesi bu belgeleri buluş basamağı değerlendirmesinden hariç tutar.", "Yanlış. EPC m.54/3 bu başvuruları yenilik bakımından tekniğin bilinen durumuna dâhil eder.", "Yanlış. Durum tersidir (EPC m.54/3, m.56).", "Yanlış. Sanayiye uygulanabilirlik tekniğin bilinen durumuyla değerlendirilmez (EPC m.57).", "Doğru. EPC m.54/3 uyarınca yalnızca yenilikte dikkate alınır, m.56 uyarınca buluş basamağında dikkate alınmaz; SMK m.83/3 ve 83/5 de aynı yaklaşımı benimser."], "ref": "EPC m.54/3, 56; SMK m.83/5"}, {"id": "PAT2-036", "exam": "patent", "topic": "Uluslararası Patent Sınıflandırması", "q": "Strasbourg Anlaşması ile kurulan Uluslararası Patent Sınıflandırması (IPC) ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["IPC, A’dan H’ye kadar sekiz bölümden (section) oluşur.", "IPC, mal ve hizmetlerin sınıflandırılmasına ilişkindir.", "IPC, endüstriyel tasarımların sınıflandırılmasına ilişkindir.", "IPC’de “C” bölümü elektriğe ayrılmıştır.", "IPC sembolleri yalnızca Avrupa patentlerinde kullanılır."], "answer": 0, "why": ["Doğru. IPC sekiz bölümden (A–H) oluşur; örneğin A insan ihtiyaçları, C kimya/metalurji, H elektriktir.", "Yanlış. Mal ve hizmetlerin sınıflandırılması Nis Anlaşmasına dayanır (SMK m.8/3).", "Yanlış. Endüstriyel tasarımlar Locarno Anlaşmasına göre sınıflandırılır.", "Yanlış. “C” bölümü kimya ve metalurjiye, “H” bölümü elektriğe ayrılmıştır.", "Yanlış. IPC, ulusal, bölgesel ve PCT belgelerinde dünya genelinde kullanılan bir sınıflandırmadır."], "ref": "Strasbourg Anlaşması (IPC)"}, {"id": "PAT2-037", "exam": "patent", "topic": "Uluslararası Patent Sınıflandırması", "q": "IPC’de “A61K 31/00” sembolünde yer alan “A61K” kısmı hangi hiyerarşik düzeyi ifade eder?", "options": ["Bölüm", "Sınıf", "Ana grup", "Alt grup", "Alt sınıf"], "answer": 4, "why": ["Yanlış. Bölüm tek harfle (“A”) gösterilir.", "Yanlış. Sınıf, bölüm harfi ve iki rakamla (“A61”) gösterilir.", "Yanlış. Ana grup, alt sınıftan sonra gelen ve “/00” ile biten kısımdır (“31/00”).", "Yanlış. Alt grup, eğik çizgiden sonra “00” dışındaki rakamlarla gösterilir (ör. “31/12”).", "Doğru. IPC hiyerarşisi bölüm (A) → sınıf (A61) → alt sınıf (A61K) → ana grup (31/00) → alt grup şeklindedir."], "ref": "Strasbourg Anlaşması (IPC)"}, {"id": "PAT2-038", "exam": "patent", "topic": "Budapeşte Antlaşması", "q": "Patent işlemleri amacıyla mikroorganizmaların tevdi edilmesinin uluslararası kabulüne ilişkin Budapeşte Antlaşması ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Herhangi bir uluslararası tevdi kuruluşuna yapılan tek bir tevdi, tüm taraf devletlerin patent ofisleri bakımından kabul edilir.\nII. Tevdi edilen materyal, kural olarak en az otuz yıl ve materyal örneği için yapılan son talepten sonra en az beş yıl süreyle saklanır.\nIII. Antlaşma, her taraf devlette ayrı ayrı tevdi yapılmasını zorunlu kılar.", "options": ["Yalnız I", "I ve II", "Yalnız II", "II ve III", "I, II ve III"], "answer": 1, "why": ["Eksik. II de doğrudur (Budapeşte Antlaşması Yönetmeliği Kural 9.1).", "Doğru. Antlaşmanın temel amacı tek tevdiin tüm taraf devletlerde tanınmasıdır (m.3); saklama süresi en az 30 yıl ve son talepten sonra en az 5 yıldır (Kural 9.1).", "Eksik. I de doğrudur; tek tevdi tüm taraflarca tanınır (Budapeşte Antlaşması m.3).", "III yanlıştır; Antlaşma ayrı ayrı tevdi zorunluluğunu ortadan kaldırmayı amaçlar.", "III yanlıştır; tek bir tevdi yeterlidir."], "ref": "Budapeşte Antlaşması m.3; Kural 9.1; SMK m.92/3"}, {"id": "PAT2-039", "exam": "patent", "topic": "Budapeşte Antlaşması", "q": "(H)’nin patent başvurusu, toplumca erişilemeyen bir biyolojik materyalin kullanımını içermekte olup materyal tevdi edilmiştir. Daha sonra materyal tevdi kuruluşunda erişilebilir olmaktan çıkmıştır. SMK’ya göre erişimin kesintiye uğramadığının kabul edilmesi için aşağıdakilerden hangisi gerekir?", "options": ["Materyalin Budapeşte Antlaşmasına uygun olarak yeniden tevdi edilmesi ve tevdi kuruluşunun verdiği alındı belgesinin suretinin, tevdi tarihinden itibaren dört ay içinde başvuru/belge numarası belirtilerek Kuruma gönderilmesi", "Materyalin yeniden tevdi edilmesi ve belgenin iki ay içinde Kuruma gönderilmesi", "Yeni bir patent başvurusu yapılması", "Materyalin yalnızca Kuruma doğrudan teslim edilmesi", "Materyalin yeniden tevdi edilmesi ve belgenin altı ay içinde Kuruma gönderilmesi"], "answer": 0, "why": ["Doğru. Budapeşte Antlaşmasına uygun yeniden tevdi ve belgenin tevdi tarihinden itibaren dört ay içinde, başvuru veya belge numarası belirtilerek Kuruma gönderilmesi hâlinde erişim kesintiye uğramamış sayılır (SMK m.92/3).", "Yanlış. Süre iki ay değil dört aydır (SMK m.92/3).", "Yanlış. Yeni başvuru gerekmez; yeniden tevdi yeterlidir (SMK m.92/3).", "Yanlış. Tevdi, tevdi kuruluşuna Budapeşte Antlaşmasına uygun şekilde yapılır (SMK m.92/3).", "Yanlış. Süre altı ay değil dört aydır (SMK m.92/3)."], "ref": "SMK m.92/2-3"}, {"id": "PAT2-040", "exam": "patent", "topic": "Paris Sözleşmesi", "q": "Paris Sözleşmesi ve SMK’daki rüçhan hakkı hükümleri birlikte değerlendirildiğinde aşağıdaki ifadelerden hangileri doğrudur?\nI. Patent ve faydalı model başvuruları için rüçhan süresi ilk başvuru tarihinden itibaren on iki aydır.\nII. Türkiye’de veya Paris Sözleşmesine taraf ülkelerde açılan resmî ya da resmen tanınmış uluslararası sergilerde ürününü teşhir eden kişi, teşhir tarihinden itibaren on iki ay içinde Türkiye’de rüçhan hakkından yararlanarak başvuru yapabilir.\nIII. Paris Sözleşmesine göre bir ülkede verilen patentin hükümsüz kılınması, aynı buluş için diğer ülkelerde verilen patentleri de kendiliğinden hükümsüz kılar.", "options": ["Yalnız I", "Yalnız II", "I ve III", "I ve II", "I, II ve III"], "answer": 3, "why": ["Eksik. II de doğrudur (SMK m.93/6).", "Eksik. I de doğrudur (SMK m.93/1; Paris Sözleşmesi m.4/C-1).", "III yanlıştır; Paris Sözleşmesi m.4bis patentlerin bağımsızlığı ilkesini öngörür.", "Doğru. On iki aylık rüçhan süresi (SMK m.93/1; Paris m.4/C) ve sergi rüçhanı (SMK m.93/6) doğrudur; III ise patentlerin bağımsızlığı ilkesine (Paris m.4bis) aykırıdır.", "III yanlıştır; her ülkedeki patent birbirinden bağımsızdır (Paris m.4bis)."], "ref": "SMK m.93; Paris Sözleşmesi m.4, 4bis"}, {"id": "PAT-001", "exam": "patent", "topic": "Patentlenebilirlik", "q": "6769 sayılı SMK'ya göre bir buluşa patent verilebilmesi için aranan şartlar aşağıdakilerden hangisinde doğru olarak verilmiştir?", "options": ["Yeni olması ve sanayiye uygulanabilir olması", "Yeni olması, buluş basamağı içermesi ve sanayiye uygulanabilir olması", "Yeni olması, buluş basamağı içermesi ve ticari olarak kullanılıyor olması", "Yeni olması, ayırt edici niteliğe sahip olması ve sanayiye uygulanabilir olması", "Buluş basamağı içermesi, sanayiye uygulanabilir olması ve Türkiye'de üretilmesi"], "answer": 1, "why": ["Yanlış. Yenilik ve sanayiye uygulanabilirlik faydalı model için yeterlidir (SMK m.142/1); patentte ayrıca buluş basamağı aranır (SMK m.82/1).", "Doğru. Teknolojinin her alanındaki buluşlara yeni olması, buluş basamağı içermesi ve sanayiye uygulanabilir olması şartıyla patent verilir (SMK m.82/1).", "Yanlış. Ticari kullanım bir patentlenebilirlik şartı değildir; kullanma zorunluluğu patent verildikten sonraki bir yükümlülüktür (SMK m.82/1, m.130).", "Yanlış. Ayırt edici nitelik tasarım korumasına ilişkin bir kavramdır; patentte aranan üçüncü şart buluş basamağıdır (SMK m.82/1).", "Yanlış. Yenilik şartı atlanmıştır; ayrıca patent sahibi ürünlerin ithal veya yerli üretim olmasına bakılmaksızın haktan yararlanır (SMK m.82/1, m.85/1)."], "ref": "SMK m.82"}, {"id": "PAT-002", "exam": "patent", "topic": "Buluş Sayılmayanlar", "q": "SMK m.82/2 uyarınca aşağıdakilerden hangisi buluş niteliğinde sayılmayanlar arasında yer almaz?", "options": ["Mikrobiyolojik işlemler sonucu elde edilen ürünler", "Bilgisayar programları", "Bilginin sunumu", "Oyunlara ilişkin plan, kural ve yöntemler", "Bilimsel teoriler ve matematiksel yöntemler"], "answer": 0, "why": ["Doğru. Mikrobiyolojik işlemler ve bu işlemler sonucu elde edilen ürünler buluş sayılmayanlar listesinde yer almadığı gibi, bitki çeşitleri ve esas olarak biyolojik işlemlere ilişkin istisnanın da dışında tutulmuştur (SMK m.82/3-b).", "Yanlış. Bilgisayar programları buluş niteliğinde sayılmaz (SMK m.82/2-c).", "Yanlış. Bilginin sunumu buluş niteliğinde sayılmaz (SMK m.82/2-d).", "Yanlış. Zihni faaliyetler, iş faaliyetleri veya oyunlara ilişkin plan, kural ve yöntemler buluş sayılmaz (SMK m.82/2-b).", "Yanlış. Keşifler, bilimsel teoriler ve matematiksel yöntemler buluş sayılmaz (SMK m.82/2-a)."], "ref": "SMK m.82"}, {"id": "PAT-003", "exam": "patent", "topic": "Patent Verilemeyecek Konular", "q": "Aşağıdakilerden hangisine SMK hükümleri uyarınca patent verilmesi mümkündür?", "options": ["İnsan vücuduna uygulanan bir teşhis yöntemi", "Hayvan vücuduna uygulanan bir cerrahi yöntem", "Melezleme yoluyla elde edilmiş yeni bir bitki çeşidi", "İnsan klonlama işlemi", "Cerrahi bir tedavi yönteminde kullanılan yeni bir ilaç terkibi"], "answer": 4, "why": ["Yanlış. İnsan veya hayvan vücuduna uygulanacak teşhis yöntemlerine patent verilmez (SMK m.82/3-c).", "Yanlış. Cerrahi yöntemler dâhil tüm tedavi yöntemlerine patent verilmez (SMK m.82/3-c).", "Yanlış. Bitki çeşitlerine ve esas olarak biyolojik işlemlere patent verilmez; melezleme esas olarak biyolojik işlem sayılır (SMK m.82/3-b, m.82/5).", "Yanlış. İnsan klonlama işlemlerine patent verilmez (SMK m.82/3-d).", "Doğru. Teşhis, cerrahi ve tedavi yöntemlerine ilişkin istisna, bu yöntemlerde kullanılan ürünler, özellikle madde ve terkipler hakkında uygulanmaz (SMK m.82/6)."], "ref": "SMK m.82"}, {"id": "PAT-004", "exam": "patent", "topic": "Buluş Sayılmayanlar", "q": "Bir patent başvurusunun istemleri, bir bilgisayar programıyla kontrol edilen ve fren mesafesini kısaltan bir taşıt fren sistemine yöneliktir. SMK m.82/2 bakımından aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Başvuru bilgisayar programıyla ilgili olsa da yalnızca programın kendisi patentlenebilirliğin dışında kalır; buluş diğer şartları taşıyorsa korunabilir.", "Bilgisayar programı içeren her buluş buluş niteliğinde sayılmadığından başvuru doğrudan reddedilir.", "Bilgisayar programları kamu düzenine aykırı sayıldığından bu buluşa patent verilemez.", "Bu tür buluşlar yalnızca faydalı model ile korunabilir.", "Bilgisayar programı içeren buluşlar ancak programın kaynak kodu tarifnameye eklenirse buluş sayılır."], "answer": 0, "why": ["Doğru. Başvurunun m.82/2'de sayılan konularla ilgili olması hâlinde sadece bu konu veya faaliyetlerin kendisi patentlenebilirliğin dışında kalır (SMK m.82/2).", "Yanlış. Kanun yalnızca programın 'kendisini' dışlar; program içerdiği için buluşun tamamı dışlanmaz (SMK m.82/2).", "Yanlış. Bilgisayar programları buluş sayılmayanlar arasındadır (m.82/2-c); kamu düzenine aykırılık ayrı bir istisnadır (SMK m.82/3-a).", "Yanlış. Kanunda böyle bir yönlendirme yoktur; faydalı modelde de m.82/2 ve m.82/3 istisnaları aynen geçerlidir (SMK m.142/3).", "Yanlış. Kanunda kaynak kodu şartı yoktur; belirleyici olan korunması istenen konunun programın kendisi olup olmadığıdır (SMK m.82/2)."], "ref": "SMK m.82"}, {"id": "PAT-005", "exam": "patent", "topic": "Yenilik ve Tekniğin Bilinen Durumu", "q": "Başvuru tarihinden önceki tarihli olup başvuru tarihinde veya bu tarihten sonra yayımlanan bir ulusal patent başvurusunun ilk içeriği ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Yenilik değerlendirmesinde tekniğin bilinen durumu olarak dikkate alınır.\nII. Buluş basamağının değerlendirilmesinde dikkate alınmaz.\nIII. Bu başvurunun özeti de söz konusu kural kapsamında tekniğin bilinen durumu olarak kullanılır.", "options": ["Yalnız I", "Yalnız II", "I ve II", "I ve III", "I, II ve III"], "answer": 2, "why": ["Yanlış. II de doğrudur; bu başvuruların içerikleri buluş basamağının değerlendirilmesinde dikkate alınmaz (SMK m.83/5).", "Yanlış. I de doğrudur; bu başvuruların ilk içerikleri tekniğin bilinen durumu olarak dikkate alınır (SMK m.83/3).", "Doğru. I (SMK m.83/3) ve II (SMK m.83/5) doğrudur; III yanlıştır, çünkü özet m.83/3'ün uygulanmasında kullanılmaz (SMK m.92/5).", "Yanlış. III yanlıştır; özet yalnızca teknik bilgi verme amacı taşır ve m.83/3'ün uygulanmasında kullanılmaz (SMK m.92/5).", "Yanlış. III yanlıştır (SMK m.92/5)."], "ref": "SMK m.83"}, {"id": "PAT-006", "exam": "patent", "topic": "Yenilik ve Tekniğin Bilinen Durumu", "q": "SMK'ya göre tekniğin bilinen durumu ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Yalnızca Türkiye'de yapılmış açıklamaları kapsar.", "Başvuru tarihinden önce dünyanın herhangi bir yerinde yazılı veya sözlü tanıtım, kullanım ya da başka herhangi bir biçimde açıklanmış, toplumca erişilebilir her şeyi kapsar.", "Yalnızca yazılı yayınları kapsar; sözlü açıklamalar ve kullanım yoluyla yapılan açıklamalar dikkate alınmaz.", "Başvuru tarihinden önceki on sekiz ay içinde yapılmış açıklamalarla sınırlıdır.", "Toplumca erişilebilir olmasa bile gizlilik yükümlülüğü altında yapılmış açıklamaları da kapsar."], "answer": 1, "why": ["Yanlış. Açıklamanın dünyanın herhangi bir yerinde yapılmış olması yeterlidir (SMK m.83/2).", "Doğru. Tekniğin bilinen durumu bu şekilde tanımlanmıştır; mutlak (dünya çapında) yenilik ilkesi benimsenmiştir (SMK m.83/2).", "Yanlış. Sözlü tanıtım, kullanım veya başka herhangi bir biçimdeki açıklamalar da kapsama girer (SMK m.83/2).", "Yanlış. Tekniğin bilinen durumu için zaman sınırı yoktur; on sekiz ay başvurunun yayım süresidir (SMK m.83/2, m.97/1).", "Yanlış. Tekniğin bilinen durumu yalnızca toplumca erişilebilir olanları kapsar (SMK m.83/2)."], "ref": "SMK m.83"}, {"id": "PAT-007", "exam": "patent", "topic": "Buluş Basamağı ve Sanayiye Uygulanabilirlik", "q": "SMK'ya göre bir buluşun buluş basamağı içerdiği hangi durumda kabul edilir?", "options": ["Tekniğin bilinen durumuna dâhil olmaması", "Tekniğin bilinen durumu dikkate alındığında, ilgili teknik alandaki uzmana göre aşikâr olmaması", "Tarım dâhil sanayinin herhangi bir dalında üretilebilir veya kullanılabilir olması", "Ortalama bir tüketiciye göre bilinen ürünlerden farklı bir genel izlenim bırakması", "Buluşu yapanın uzun süreli araştırma ve yüksek maliyet sonucunda buluşa ulaşmış olması"], "answer": 1, "why": ["Yanlış. Bu, yenilik şartının tanımıdır (SMK m.83/1).", "Doğru. Buluş basamağı bu şekilde tanımlanmıştır (SMK m.83/4).", "Yanlış. Bu, sanayiye uygulanabilirlik şartının tanımıdır (SMK m.83/6).", "Yanlış. Genel izlenim ölçütü patente değil tasarım korumasına ilişkindir; patentte ölçüt uzmana göre aşikâr olmamaktır (SMK m.83/4).", "Yanlış. Harcanan emek veya maliyet kanuni ölçüt değildir; belirleyici olan uzmana göre aşikâr olmamaktır (SMK m.83/4)."], "ref": "SMK m.83"}, {"id": "PAT-008", "exam": "patent", "topic": "Zararsız Açıklamalar", "q": "Buluşu yapan A, buluşunu 10.01.2024 tarihinde uluslararası bir konferansta sunmuştur. A, aynı buluş için 05.09.2024 tarihinde Paris Sözleşmesine taraf Almanya'da ilk patent başvurusunu yapmış, bu başvuruya dayanarak rüçhan hakkı talebiyle 01.09.2025 tarihinde Türkiye'de patent başvurusunda bulunmuştur. Konferanstaki açıklamanın Türkiye başvurusuna etkisi bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Açıklama, Türkiye'deki başvuru tarihinden on iki aydan daha önce yapıldığından yeniliği ortadan kaldırır.", "Zararsız açıklama süresi altı ay olduğundan açıklama yeniliği ortadan kaldırır.", "Açıklama, rüçhan tarihinden önceki on iki ay içinde buluşu yapan tarafından yapıldığından patent verilmesini etkilemez.", "Açıklama buluşu yapanın kendisi tarafından yapıldığından, süre sınırı olmaksızın her durumda zararsızdır.", "Rüçhan hakkı on iki aylık süre geçtikten sonra talep edildiğinden geçersizdir; bu nedenle açıklama yeniliği ortadan kaldırır."], "answer": 2, "why": ["Yanlış. Rüçhan hakkı talep edilmişse on iki aylık süre rüçhan tarihinden geriye doğru hesaplanır (SMK m.84/1).", "Yanlış. Zararsız açıklama süresi altı ay değil, on iki aydır (SMK m.84/1).", "Doğru. Rüçhan hakkı talep edilmişse rüçhan tarihinden önceki on iki ay içinde buluşu yapan tarafından yapılan açıklama patent verilmesini etkilemez (SMK m.84/1-a); rüçhan da ilk başvurudan itibaren on iki ay içinde talep edilmiştir (SMK m.93/1).", "Yanlış. Buluşu yapanın açıklaması da ancak başvuru veya rüçhan tarihinden önceki on iki ay içinde yapılmışsa zararsızdır (SMK m.84/1).", "Yanlış. Türkiye başvurusu 05.09.2024 tarihli ilk başvurudan itibaren on iki ay içinde (01.09.2025) yapılmıştır; rüçhan hakkı geçerlidir (SMK m.93/1)."], "ref": "SMK m.84"}, {"id": "PAT-009", "exam": "patent", "topic": "Zararsız Açıklamalar", "q": "SMK m.84'te düzenlenen, patent verilmesini etkilemeyen açıklamalar hakkında aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Başvurunun yapıldığı tarihte patent isteme hakkına sahip olan her kişi, bu madde bakımından buluşu yapan sayılır.", "Hükmün uygulanması gerektiğini ileri süren taraf, şartların gerçekleştiğini veya gerçekleşmesinin beklendiğini ispatla yükümlüdür.", "Zararsız açıklama hükmünden yararlanılabilmesi için bu durumun başvuru tarihinde beyan edilmesi gerekir; sonradan ileri sürülemez.", "Açıklamanın, buluşu yapandan doğrudan veya dolaylı olarak bilgi elde eden üçüncü kişi tarafından yapılması da bu hükmün kapsamındadır.", "Hüküm, faydalı model başvuruları bakımından da uygulanır."], "answer": 2, "why": ["Doğru ifade. Bu kişiler m.84/1 bakımından buluşu yapan sayılır (SMK m.84/2).", "Doğru ifade. İspat yükü hükmün uygulanmasını ileri sürene aittir (SMK m.84/4).", "Doğru cevap (yanlış ifade). Birinci fıkranın uygulanmasından doğan sonuçlar süreyle sınırlı değildir ve her zaman ileri sürülebilir (SMK m.84/3).", "Doğru ifade. Bu durum m.84/1-c'de açıkça sayılmıştır (SMK m.84/1-c).", "Doğru ifade. Madde, patent veya faydalı model verilmesini etkilemeyen açıklamaları düzenler (SMK m.84/1)."], "ref": "SMK m.84"}, {"id": "PAT-010", "exam": "patent", "topic": "Zararsız Açıklamalar", "q": "Aşağıdaki açıklamalardan hangisi, başvuru tarihinden önceki on iki ay içinde yapılmış olsa bile SMK m.84 kapsamında patent verilmesini etkilemeyen açıklama sayılmaz?", "options": ["Aynı buluşu, buluşu yapandan bağımsız olarak kendi çalışmalarıyla gerçekleştiren bir üçüncü kişinin yaptığı açıklama", "Buluşu yapanın kendisinin bir fuarda yaptığı açıklama", "Buluşu yapanın başka bir başvurusunda yer alan bilginin, açıklanmaması gerektiği hâlde patent başvurusu yapılan merci tarafından açıklanması", "Buluşu yapandan bilgi edinen üçüncü kişinin, buluşu yapanın bilgisi veya izni olmadan yaptığı başvuruda yer alan bilginin merci tarafından açıklanması", "Buluşu yapandan dolaylı olarak bilgi elde eden bir üçüncü kişinin yaptığı açıklama"], "answer": 0, "why": ["Doğru. m.84/1-c yalnızca buluşu yapandan doğrudan veya dolaylı olarak bilgi elde eden üçüncü kişinin açıklamasını kapsar; bağımsız buluşçunun açıklaması bu kapsamda değildir (SMK m.84/1).", "Yanlış. Buluşu yapan tarafından yapılan açıklama zararsızdır (SMK m.84/1-a).", "Yanlış. Bu durum zararsız açıklama olarak sayılmıştır (SMK m.84/1-b-1).", "Yanlış. Bu durum zararsız açıklama olarak sayılmıştır (SMK m.84/1-b-2).", "Yanlış. Buluşu yapandan doğrudan veya dolaylı bilgi elde eden üçüncü kişinin açıklaması zararsızdır (SMK m.84/1-c)."], "ref": "SMK m.84"}, {"id": "PAT-011", "exam": "patent", "topic": "Patent İsteme Hakkı", "q": "A ve B, birbirinden bağımsız olarak aynı buluşu gerçekleştirmiştir. A 01.03.2024, B ise 15.03.2024 tarihinde Türkiye'de patent başvurusu yapmıştır. SMK'ya göre patent isteme hakkı kime aittir?", "options": ["Buluşu ilk gerçekleştirdiğini ispat eden kişiye", "A'nın başvurusunun yayımlanmış olması şartıyla A'ya", "A ve B'ye birlikte, paylı mülkiyet esaslarına göre", "Başvurusu önce yayımlanan kişiye, başvuru tarihine bakılmaksızın", "Buluşu ilk kez kullanmaya başlayan kişiye"], "answer": 1, "why": ["Yanlış. Kanun buluşu ilk gerçekleştirene değil, önce başvurana öncelik tanır (SMK m.109/3).", "Doğru. Aynı buluş bağımsız olarak birden çok kişi tarafından gerçekleştirilmişse patent isteme hakkı, önceki tarihli başvurunun yayımlanmış olması şartıyla daha önce başvuru yapana aittir (SMK m.109/3).", "Yanlış. Ortak hak sahipliği, buluşun birlikte gerçekleştirilmesi hâline ilişkindir (SMK m.109/2, m.112); bağımsız buluşlarda hak önce başvurana aittir (SMK m.109/3).", "Yanlış. Belirleyici olan başvuru tarihidir; yayım yalnızca önceki tarihli başvuru için aranan şarttır (SMK m.109/3).", "Yanlış. Önceki kullanım patent isteme hakkı vermez; yalnızca şartları varsa önceki kullanımdan doğan hakkı sağlar (SMK m.87, m.109/3)."], "ref": "SMK m.109"}, {"id": "PAT-012", "exam": "patent", "topic": "Patent İsteme Hakkı", "q": "Patent isteme hakkına ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Patent isteme hakkı buluşu yapana veya onun haleflerine aittir ve bu hakkın başkalarına devri mümkündür.\nII. Buluş birden çok kişi tarafından birlikte gerçekleştirilmişse patent isteme hakkı, aralarından ilk başvuruyu yapan kişiye aittir.\nIII. Patent almak için ilk başvuran kişi, aksi ispat edilinceye kadar patent isteme hakkının sahibidir.", "options": ["Yalnız I", "Yalnız III", "I ve II", "I ve III", "I, II ve III"], "answer": 3, "why": ["Yanlış. III de doğrudur (SMK m.109/4).", "Yanlış. I de doğrudur (SMK m.109/1).", "Yanlış. II yanlıştır; birlikte gerçekleştirilen buluşta patent isteme hakkı, taraflar başka türlü kararlaştırmamışsa bunların tamamına aittir (SMK m.109/2).", "Doğru. I (SMK m.109/1) ve III (SMK m.109/4) doğrudur; II yanlıştır (SMK m.109/2).", "Yanlış. II yanlıştır (SMK m.109/2)."], "ref": "SMK m.109"}, {"id": "PAT-013", "exam": "patent", "topic": "Hak Sahipliği ve Gasp", "q": "Patent başvurusu sürecinde açılan hak sahipliği davasının davacı lehine kesinleşmesi hâlinde, davacı geçerliliği devam eden başvuru için kararın kesinleşme tarihinden itibaren hangi süre içinde talepte bulunabilir ve bu süre içinde hiçbir talepte bulunmazsa sonuç ne olur?", "options": ["İki ay; başvuru davacı adına kendiliğinden yürütülmeye devam eder.", "Üç ay; başvuru, önceki başvuru sahibi adına işlemlere devam eder.", "Altı ay; başvuru reddedilir.", "Bir yıl; başvuru konusu buluş kamuya ait olur.", "Üç ay; dava konusu başvuru geri çekilmiş sayılır."], "answer": 4, "why": ["Yanlış. Süre üç aydır ve talepte bulunulmazsa başvuru geri çekilmiş sayılır (SMK m.110/3, m.110/5).", "Yanlış. Süre doğru olmakla birlikte sonuç yanlıştır; başvuru geri çekilmiş sayılır (SMK m.110/5).", "Yanlış. Süre üç aydır; ret, davacının talep edebileceği seçeneklerden biridir, sessiz kalmanın sonucu değildir (SMK m.110/3-c, m.110/5).", "Yanlış. Süre üç aydır ve kanuni sonuç başvurunun geri çekilmiş sayılmasıdır (SMK m.110/3, m.110/5).", "Doğru. Davacı üç ay içinde başvuruyu kendi başvurusu olarak yürütme, aynı rüçhanla yeni başvuru yapma veya başvurunun reddini isteme seçeneklerine sahiptir (SMK m.110/3); talepte bulunmazsa başvuru geri çekilmiş sayılır (SMK m.110/5)."], "ref": "SMK m.110"}, {"id": "PAT-014", "exam": "patent", "topic": "Hak Sahipliği ve Gasp", "q": "Gerçek hak sahibinden başkasına verilmiş bir patentin kendisine devrini mahkemeden talep etmek isteyen gerçek hak sahibi, bu hakkını hangi süre içinde kullanmalıdır?", "options": ["Patentin verildiğine ilişkin yayım tarihinden itibaren iki yıl içinde; kötüniyet hâlinde ise patentin koruma süresinin bitimine kadar", "Başvuru tarihinden itibaren iki yıl içinde; kötüniyet hâlinde ise beş yıl içinde", "Patentin verildiğine ilişkin yayım tarihinden itibaren altı ay içinde", "Gaspı öğrenme tarihinden itibaren bir yıl içinde", "Patentin koruma süresince ve hakkın sona ermesini izleyen beş yıl içinde"], "answer": 0, "why": ["Doğru. Gasp hâlinde devir talebi bu sürelerde kullanılır (SMK m.111/3).", "Yanlış. Süre verilme yayımından başlar ve kötüniyet hâlinde koruma süresinin bitimine kadar uzar (SMK m.111/3).", "Yanlış. Altı ay, patentin verilmesine karşı itiraz süresidir (SMK m.99/1); gasp hâlinde süre iki yıldır (SMK m.111/3).", "Yanlış. Kanun öğrenme tarihini değil, verilme yayım tarihini esas alır (SMK m.111/3).", "Yanlış. Bu süre hükümsüzlük davasına ilişkindir (SMK m.138/5); gaspta süre iki yıldır (SMK m.111/3)."], "ref": "SMK m.111"}, {"id": "PAT-015", "exam": "patent", "topic": "Çalışan Buluşları", "q": "Çalışan buluşlarına ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Öğrenciler ile ücretsiz olarak belirli bir süreye bağlı olmaksızın hizmet gören stajyerler hakkında çalışanlara ilişkin hükümler uygulanır.\nII. Kamu kurum ve kuruluşlarında çalışanlara buluşları için ödenecek bedel, buluştan elde edilen gelirin üçte birinden az olamaz.\nIII. Buluşun kamu kurumunun kendisi tarafından kullanılması hâlinde çalışana ödenecek bedel, çalışanın net ücretinin yirmi katından az olamaz.", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 1, "why": ["Yanlış. II de doğrudur (SMK m.113/5).", "Doğru. I (SMK m.113/3) ve II (SMK m.113/5) doğrudur; III yanlıştır, bu hâlde bedel bir defaya mahsus olmak üzere bedelin ödendiği ay için ödenen net ücretin on katından fazla olamaz (SMK m.113/5).", "Yanlış. III yanlıştır; kanun bir alt sınır değil, net ücretin on katı şeklinde bir üst sınır öngörür (SMK m.113/5).", "Yanlış. III yanlıştır, I ise doğrudur (SMK m.113/3, m.113/5).", "Yanlış. III yanlıştır (SMK m.113/5)."], "ref": "SMK m.113"}, {"id": "PAT-016", "exam": "patent", "topic": "Çalışan Buluşları", "q": "Hizmet buluşunu bildiren çalışanın bildiriminde düzeltilmesi gereken hususlar varsa, işveren bunu bildirimin kendisine ulaştığı tarihten itibaren hangi süre içinde çalışana bildirmelidir?", "options": ["İki ay", "Bir ay", "Üç ay", "Dört ay", "Altı ay"], "answer": 0, "why": ["Doğru. İşveren iki ay içinde düzeltme gereken hususları bildirir; talepte bulunmazsa bildirim geçerli sayılır (SMK m.114/4).", "Yanlış. Düzeltme talebi süresi iki aydır (SMK m.114/4).", "Yanlış. Üç ay, işverenin serbest buluş bildirimine itiraz süresidir (SMK m.119/2); düzeltme talebi süresi iki aydır (SMK m.114/4).", "Yanlış. Dört ay, işverenin hak talebi süresidir (SMK m.115/1); düzeltme talebi süresi iki aydır (SMK m.114/4).", "Yanlış. Kanunda düzeltme talebi için altı aylık süre öngörülmemiştir; süre iki aydır (SMK m.114/4)."], "ref": "SMK m.114"}, {"id": "PAT-017", "exam": "patent", "topic": "Çalışan Buluşları", "q": "İşveren, hizmet buluşu üzerinde hak talebinde bulunmak istiyorsa bu talebi hangi süre içinde ve hangi şekilde yapmalıdır; aksi hâlde sonuç nedir?", "options": ["Bildirimden itibaren iki ay içinde yazılı olarak; aksi hâlde işveren tam hak talep etmiş sayılır.", "Bildirimden itibaren dört ay içinde herhangi bir şekilde; aksi hâlde işveren kısmi hak talep etmiş sayılır.", "Çalışanın bildiriminin kendisine ulaştığı tarihten itibaren dört ay içinde yazılı olarak; aksi hâlde hizmet buluşu serbest buluş niteliği kazanır.", "Bildirimden itibaren altı ay içinde yazılı olarak; aksi hâlde buluş kamuya ait olur.", "Bildirimden itibaren üç ay içinde noter aracılığıyla; aksi hâlde çalışan bedel talep edemez."], "answer": 2, "why": ["Yanlış. Süre dört aydır ve sessizlik tam hak talebi değil, buluşun serbest buluşa dönüşmesi sonucunu doğurur (SMK m.115/1).", "Yanlış. Talebin yazılı olması zorunludur ve sessizliğin sonucu serbest buluştur (SMK m.115/1).", "Doğru. Talep dört ay içinde yazılı olarak bildirilmelidir; süresinde bildirim yapılmazsa buluş serbest buluş niteliği kazanır (SMK m.115/1).", "Yanlış. Süre dört aydır; buluş kamuya değil çalışana serbest buluş olarak kalır (SMK m.115/1).", "Yanlış. Süre dört aydır, noter şartı yoktur, yazılı bildirim yeterlidir (SMK m.115/1)."], "ref": "SMK m.115"}, {"id": "PAT-018", "exam": "patent", "topic": "Çalışan Buluşları", "q": "İşverenin hizmet buluşu üzerinde kısmi hak talep etmesi hâlinde aşağıdakilerden hangisi doğrudur?", "options": ["Buluş üzerindeki tüm haklar, bildirimin çalışana ulaşmasıyla işverene geçer.", "İşveren buluşu kullansa dahi çalışan bedel talep edemez.", "İşverenin kullanımı çalışanın buluşu değerlendirmesini önemli ölçüde güçleştirse bile çalışanın işverenden herhangi bir talep hakkı yoktur.", "Hizmet buluşu serbest buluş niteliği kazanır; ancak işveren kısmi hakka dayanarak buluşu kullanabilir.", "Çalışanın tam devralma veya vazgeçme isteğine işveren altı ay içinde cevap vermezse işverenin kullanma hakkı sona erer."], "answer": 3, "why": ["Yanlış. Bu sonuç tam hak talebine özgüdür (SMK m.115/2).", "Yanlış. Kısmi hak talebinde işveren buluşu kullanırsa çalışanın makul bedel isteme hakkı doğar (SMK m.115/6).", "Yanlış. Bu durumda çalışan, hakkın tamamen devralınmasını veya kısmi hakka dayalı kullanımdan vazgeçilmesini isteyebilir (SMK m.115/3).", "Doğru. Kısmi hak talebinde buluş serbest buluş niteliği kazanır, işveren kısmi hakka dayanarak buluşu kullanabilir (SMK m.115/3).", "Yanlış. Cevap süresi tebellüğden itibaren iki aydır (SMK m.115/3)."], "ref": "SMK m.115"}, {"id": "PAT-019", "exam": "patent", "topic": "Çalışan Buluşları", "q": "Hizmet buluşu için patent başvurusu yapılmasına ilişkin aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Çalışanın, buluşu için başvuru yapılmamasına rıza göstermesi, işverenin ilk başvuru yükümlülüğünü ortadan kaldırır.", "İşletme sırlarının korunmasının başvuru yapmamayı gerektirmesi, işverenin ilk başvuru yükümlülüğünü ortadan kaldırır.", "İşveren, tam hak talep ettiği hizmet buluşu için yalnızca Türkiye'de başvuru yapabilir; yabancı ülkelerde başvuru hakkı çalışana aittir.", "Hizmet buluşu serbest buluş niteliği kazanmışsa çalışan bizzat başvuru yapma hakkına sahiptir.", "İşveren, tam hak talep ettiği buluş için başvuru yapmaz ve çalışanın belirleyeceği süre içinde de yapmazsa buluş serbest buluş niteliği kazanır."], "answer": 2, "why": ["Doğru ifade (SMK m.116/2-b).", "Doğru ifade (SMK m.116/2-c).", "Doğru cevap (yanlış ifade). Tam hak talep eden işveren, buluşun yabancı ülkede korunması için de başvuruda bulunabilir; çalışana yalnızca işverenin patent almak istemediği ülkeler için buluşu serbest bırakma yükümlülüğü vardır (SMK m.116/5-6).", "Doğru ifade (SMK m.116/3).", "Doğru ifade (SMK m.116/4)."], "ref": "SMK m.116"}, {"id": "PAT-020", "exam": "patent", "topic": "Çalışan Buluşları", "q": "İşveren ile çalışan arasında yapılan çalışan buluşuna ilişkin sözleşmenin veya belirlenen bedelin hakkaniyete aykırı olduğuna dair itiraz hangi süre içinde ve hangi şekilde ileri sürülebilir?", "options": ["Sözleşmenin imzalandığı tarihten itibaren altı ay içinde, yazılı olarak", "İş sözleşmesinin bitiminden itibaren iki yıl içinde, herhangi bir şekilde", "Bedelin ödendiği tarihten itibaren üç ay içinde, yazılı olarak", "Süre sınırı olmaksızın her zaman", "İş sözleşmesinin bitiminden itibaren en geç altı ay içinde, yazılı olarak"], "answer": 4, "why": ["Yanlış. Süre sözleşmenin imzasından değil, iş sözleşmesinin bitiminden başlar (SMK m.117/3).", "Yanlış. Süre altı aydır ve itirazın yazılı yapılması gerekir (SMK m.117/3).", "Yanlış. Başlangıç iş sözleşmesinin bitimi, süre altı aydır (SMK m.117/3).", "Yanlış. Kanun iş sözleşmesinin bitiminden itibaren en geç altı aylık süre öngörmüştür (SMK m.117/3).", "Doğru. Hakkaniyete aykırılık itirazı bu süre ve şekilde ileri sürülür (SMK m.117/3)."], "ref": "SMK m.117"}, {"id": "PAT-021", "exam": "patent", "topic": "Çalışan Buluşları", "q": "Serbest buluşlara ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Serbest buluşun işverenin faaliyet alanı içinde değerlendirilebilir olmadığı açıksa, çalışanın bildirim yükümlülüğü yoktur.\nII. İşveren, buluşun serbest buluş olmadığına ilişkin itirazını kendisine yapılan bildirim tarihinden itibaren üç ay içinde yazılı bir bildirimle ileri sürebilir.\nIII. Çalışanın yükümlü olduğu yararlanma teklifine işveren, teklifin kendisine ulaştığı tarihten itibaren üç ay içinde cevap vermezse bu konudaki öncelik hakkını kaybeder.", "options": ["Yalnız I", "Yalnız II", "I ve III", "II ve III", "I, II ve III"], "answer": 4, "why": ["Yanlış. II (SMK m.119/2) ve III (SMK m.119/4) de doğrudur.", "Yanlış. I (SMK m.119/3) ve III (SMK m.119/4) de doğrudur.", "Yanlış. II de doğrudur (SMK m.119/2).", "Yanlış. I de doğrudur (SMK m.119/3).", "Doğru. Üç ifade de kanuna uygundur (SMK m.119/2, m.119/3, m.119/4)."], "ref": "SMK m.119"}, {"id": "PAT-022", "exam": "patent", "topic": "Yükseköğretim Buluşları", "q": "Yükseköğretim kurumlarında gerçekleştirilen bir buluştan elde edilen gelirin paylaşımında buluşu yapana verilecek asgari pay nedir?", "options": ["Gelirin en az yarısı", "Gelirin en az dörtte biri", "Gelirin tamamı; kurum yalnızca masraflarını alır", "Gelirin en az üçte biri", "Taraflarca serbestçe belirlenir; kanunda asgari pay öngörülmemiştir"], "answer": 3, "why": ["Yanlış. Kanuni asgari pay üçte birdir (SMK m.121/8).", "Yanlış. Kanuni asgari pay üçte birdir (SMK m.121/8).", "Yanlış. Gelir kurum ile buluşu yapan arasında paylaşılır; kurumun hissesi bütçeye özgelir olarak kaydedilir (SMK m.121/8).", "Doğru. Paylaşım, buluşu yapana gelirin en az üçte biri verilecek şekilde belirlenir (SMK m.121/8).", "Yanlış. Kanun buluşu yapan için gelirin en az üçte biri şeklinde asgari pay öngörmüştür (SMK m.121/8)."], "ref": "SMK m.121"}, {"id": "PAT-023", "exam": "patent", "topic": "Yükseköğretim Buluşları", "q": "SMK m.121/5 uyarınca aşağıdaki düzenlemelerden hangisi yükseköğretim kurumlarında gerçekleştirilen buluşlar hakkında uygulanmaz?", "options": ["Buluşu yapanın buluşunu yazılı olarak ve geciktirmeksizin yükseköğretim kurumuna bildirmesi", "Hak sahipliği talebinde bulunan yükseköğretim kurumunun patent başvurusu yapmakla yükümlü olması", "Buluşu yapanın, kurumun hak sahipliği talebine buluşunun serbest buluş olduğunu ileri sürerek itiraz edebilmesi", "İşverenin, çalışanın bildiriminden itibaren dört ay içinde yazılı olarak tam veya kısmi hak talep etmesine ilişkin hüküm", "Kurumun kusuruyla patent hakkının sona ermesine sebep olması hâlinde buluşu yapanın zararını tazmin etmesi"], "answer": 3, "why": ["Yanlış. Bu yükümlülük m.121/2'de bizzat düzenlenmiştir ve uygulanır (SMK m.121/2).", "Yanlış. Bu yükümlülük uygulanır; aksi hâlde buluş serbest buluş niteliği kazanır (SMK m.121/3).", "Yanlış. Bu itiraz hakkı m.121/4'te düzenlenmiştir ve uygulanır (SMK m.121/4).", "Doğru. Yükseköğretim kurumlarındaki buluşlarda m.115, m.116, m.118 ve m.119/4 uygulanmaz (SMK m.121/5); dört aylık hak talebi m.115/1'de düzenlenmiştir.", "Yanlış. Bu tazmin yükümlülüğü uygulanır (SMK m.121/7)."], "ref": "SMK m.121"}, {"id": "PAT-024", "exam": "patent", "topic": "Başvuru ve Başvuru Tarihi", "q": "SMK'ya göre aşağıdakilerden hangisi, patent başvuru tarihinin kesinleşmesi için Kuruma verilmesi gereken unsurlardan biri değildir?", "options": ["Patent verilmesi talebi", "Başvuru sahibinin kimlik bilgileri", "Başvuru sahibinin iletişim bilgileri", "Tarifname yerine önceki bir başvuruya yapılan atıf", "İstemler"], "answer": 4, "why": ["Yanlış. Başvuru tarihinin kesinleşmesi için gerekli unsurlardandır (SMK m.90/3-a).", "Yanlış. Başvuru tarihinin kesinleşmesi için gerekli unsurlardandır (SMK m.90/3-b).", "Yanlış. Başvuru tarihinin kesinleşmesi için gerekli unsurlardandır (SMK m.90/3-b).", "Yanlış. Tarifname veya önceki bir başvuruya yapılan atıf başvuru tarihi için yeterli unsurdur (SMK m.90/3-c).", "Doğru. Başvuru tarihi için yalnızca patent verilmesi talebi, başvuru sahibinin kimlik ve iletişim bilgileri ve tarifname (veya önceki başvuruya atıf) gerekir (SMK m.90/3); istemler m.90/1 unsurudur ve eksikliği sonradan giderilebilir (SMK m.95/2)."], "ref": "SMK m.90"}, {"id": "PAT-025", "exam": "patent", "topic": "Başvuru ve Başvuru Tarihi", "q": "İşleme alınan bir patent başvurusunda özet eksiktir ve tarifname İngilizce olarak verilmiştir. SMK'ya göre bu durumla ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Eksiklikler Kurumun bildirim tarihinden itibaren iki ay içinde giderilmelidir; aksi takdirde başvuru reddedilir.", "Tarifname yalnızca Türkçe verilebileceğinden başvuru işleme alınmaz.", "Bildirime gerek olmaksızın başvuru tarihinden itibaren iki ay içinde eksiklik giderilmeli ve Türkçe çeviri verilmelidir; aksi takdirde başvuru geri çekilmiş sayılır.", "Eksiklikler başvuru tarihinden itibaren üç ay içinde giderilmelidir; aksi hâlde başvuru tarihi eksikliklerin giderildiği tarih olur.", "Eksiklikler araştırma talebiyle birlikte, başvuru tarihinden itibaren on iki ay içinde giderilebilir."], "answer": 2, "why": ["Yanlış. Bu kural şeklî şartlara uygunluk incelemesinde tespit edilen eksikliklere ilişkindir (SMK m.95/4); m.90/1 unsurları için bildirim beklenmez (SMK m.95/2).", "Yanlış. Tarifname Paris Sözleşmesi veya DTÖ'ye taraf ya da karşılıklılık ilkesini uygulayan devletlerin resmî dillerinden birinde verilebilir (SMK m.90/2, m.90/3-c).", "Doğru. m.90/1 unsurlarından birinin eksikliği veya yabancı dilde verilmesi hâlinde bu kural uygulanır (SMK m.95/2).", "Yanlış. Süre iki aydır ve sonuç başvurunun geri çekilmiş sayılmasıdır (SMK m.95/2).", "Yanlış. On iki ay araştırma talebi süresidir (SMK m.96/1); bu eksiklikler için süre iki aydır (SMK m.95/2)."], "ref": "SMK m.95"}, {"id": "PAT-026", "exam": "patent", "topic": "Bölünmüş Başvuru", "q": "Bölünmüş başvuruya ilişkin aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Buluş bütünlüğüne bakılmaksızın, başvuru sahibinin talebi üzerine her başvuru için bölünmüş başvuru yapılabilir.", "Bölünmüş başvurunun başvuru tarihi, bölünmüş başvurunun Kuruma verildiği tarihtir.", "Bölünmüş başvuruyla birlikte geçmiş yıllara ait yıllık ücretler de ödenir.", "İlk başvuruda rüçhan hakkı talep edilmişse bu hak bölünmüş her başvuruya da tanınır.", "Bölünmüş başvuru, işlemleri devam eden başvuru konusunun kapsamını aşmayacak şekilde yapılır."], "answer": 1, "why": ["Doğru ifade (SMK m.91/2).", "Doğru cevap (yanlış ifade). Bölünmüş her başvuru için başvuru tarihi ilk başvurunun tarihidir (SMK m.91/4); Kuruma verildiği tarihin esas alınması ek patent başvurusuna özgüdür (SMK m.123/2).", "Doğru ifade (SMK m.91/3).", "Doğru ifade (SMK m.91/4).", "Doğru ifade (SMK m.91/3)."], "ref": "SMK m.91"}, {"id": "PAT-027", "exam": "patent", "topic": "Rüçhan Hakkı", "q": "SMK'ya göre rüçhan hakkı talebi ve buna ilişkin belgelerin sunulması hangi süreler içinde yapılır?", "options": ["Talep yalnızca başvuruyla birlikte yapılabilir; belgeler başvuru tarihinden itibaren üç ay içinde sunulur.", "Talep başvuru tarihinden itibaren üç ay içinde yapılır; belgeler altı ay içinde sunulur.", "Talep ve belgeler, rüçhan tarihinden itibaren on altı ay içinde sunulur.", "Talep, ücreti ödenerek başvuruyla birlikte veya başvuru tarihinden itibaren iki ay içinde yapılır; belgeler başvuru tarihinden itibaren üç ay içinde sunulur.", "Talep başvuru tarihinden itibaren iki ay içinde yapılır; belgeler için Kurum bildirim yapar ve bildirimden itibaren iki ay süre verilir."], "answer": 3, "why": ["Yanlış. Talep başvuru tarihinden itibaren iki ay içinde de yapılabilir (SMK m.94/1).", "Yanlış. Talep süresi iki ay, belge süresi üç aydır (SMK m.94/1).", "Yanlış. SMK'da süreler rüçhan tarihinden değil başvuru tarihinden itibaren iki ve üç ay olarak düzenlenmiştir (SMK m.94/1).", "Doğru. Aksi takdirde rüçhan hakkı talebi yapılmamış sayılır (SMK m.94/1).", "Yanlış. Belgeler için bildirim beklenmez; başvuru tarihinden itibaren üç ay içinde sunulmalıdır (SMK m.94/1)."], "ref": "SMK m.94"}, {"id": "PAT-028", "exam": "patent", "topic": "Araştırma ve İnceleme", "q": "Patent başvurusunda araştırma talebine ilişkin aşağıdakilerden hangisi doğrudur?", "options": ["Araştırma talebi Kurumun bildiriminden itibaren üç ay içinde yapılır; aksi takdirde başvuru reddedilir.", "Araştırma talebi süresi on iki aydır ve Cumhurbaşkanı bu süreyi iki katına kadar uzatmaya yetkilidir.", "Araştırma talebi rüçhan tarihinden itibaren on sekiz ay içinde yapılır.", "Başvuru konusunun m.82/2 kapsamına girdiği sonucuna varılsa dahi araştırma raporu her durumda düzenlenir.", "Başvuru sahibi, başvuruyla birlikte veya bildirime gerek olmaksızın başvuru tarihinden itibaren on iki ay içinde ücretini ödeyerek araştırma talebinde bulunur; aksi takdirde başvuru geri çekilmiş sayılır."], "answer": 4, "why": ["Yanlış. Süre bildirime gerek olmaksızın başvuru tarihinden itibaren on iki aydır ve sonuç geri çekilmiş sayılmadır (SMK m.96/1).", "Yanlış. Cumhurbaşkanı on iki aylık süreyi yarısına kadar indirmeye yetkilidir (SMK m.96/4).", "Yanlış. On sekiz ay yayım süresidir (SMK m.97/1); araştırma talebi başvuru tarihinden itibaren on iki ay içinde yapılır (SMK m.96/1).", "Yanlış. Bu durumda araştırma raporu düzenlenmez ve başvuru sahibinden üç ay içinde itiraz veya değişiklik sunması istenir (SMK m.96/3).", "Doğru (SMK m.96/1)."], "ref": "SMK m.96"}, {"id": "PAT-029", "exam": "patent", "topic": "Yayım", "q": "Patent başvurusunun yayımı ve etkilerine ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Başvuru, başvuru veya varsa rüçhan tarihinden itibaren on sekiz aylık sürenin dolmasıyla ya da bu süre dolmadan başvuru sahibinin erken yayım talebi üzerine Bültende yayımlanır.\nII. Üçüncü kişiler, yayım tarihinden itibaren buluşun patent verilebilirliğine ilişkin görüş sunabilir ve bu suretle Kurum nezdindeki işlemlere taraf olurlar.\nIII. Patente sağlanan koruma başvuru sahibine yayım tarihinden itibaren geçici olarak tanınır; başvurudan ve kapsamından haberdar edilmiş kullanıcıya karşı yayımdan önce de söz konusu olur.", "options": ["Yalnız I", "Yalnız II", "I ve II", "I ve III", "II ve III"], "answer": 3, "why": ["Yanlış. III de doğrudur (SMK m.97/4-5).", "Yanlış. II yanlıştır; üçüncü kişiler görüş sunabilir ancak bu aşamada Kurum nezdindeki işlemlere taraf olamaz (SMK m.97/2).", "Yanlış. II yanlıştır (SMK m.97/2).", "Doğru. I (SMK m.97/1) ve III (SMK m.97/4-5) doğrudur; II yanlıştır (SMK m.97/2).", "Yanlış. II yanlıştır (SMK m.97/2)."], "ref": "SMK m.97"}, {"id": "PAT-030", "exam": "patent", "topic": "Araştırma ve İnceleme", "q": "SMK m.98'e göre inceleme aşamasına ilişkin aşağıdaki ifadelerden hangisi doğrudur?", "options": ["İnceleme talebi başvuru tarihinden itibaren üç ay içinde yapılır.", "Başvurunun Kanuna uygun olmadığının tespiti hâlinde başvuru sahibine yapılacak bildirimlerin sayısı üçten fazla olamaz.", "Başvuru sahibine görüş sunması veya değişiklik yapması için bildirim tarihinden itibaren bir aylık süre verilir.", "İnceleme talebi süresinde yapılmazsa başvuru reddedilir.", "Patentin verilmiş olması, geçerliliği ve yararlılığı konusunda Kurumun garantisi niteliğindedir."], "answer": 1, "why": ["Yanlış. Süre araştırma raporunun bildirim tarihinden itibaren üç aydır (SMK m.98/1).", "Doğru (SMK m.98/3).", "Yanlış. Bu süre üç aydır (SMK m.98/4).", "Yanlış. Bu durumda başvuru geri çekilmiş sayılır (SMK m.98/1).", "Yanlış. Patentin verilmesi Kurumun garantisi olarak yorumlanamaz ve Kurumun sorumluluğunu doğurmaz (SMK m.98/9)."], "ref": "SMK m.98"}, {"id": "PAT-031", "exam": "patent", "topic": "İtiraz", "q": "Patentin verilmesi kararının Bültende yayımlanmasından sonra üçüncü kişilerce Kurum nezdinde yapılacak itirazda aşağıdakilerden hangisi itiraz gerekçesi olarak ileri sürülemez?", "options": ["Patent konusunun yeni olmadığı", "Buluşun, uzmanın uygulayabileceği şekilde yeterince açıklanmadığı", "Patent sahibinin m.109 uyarınca patent isteme hakkına sahip olmadığı", "Patent konusunun başvurunun ilk hâlinin kapsamını aştığı", "Patent konusunun m.82 uyarınca patent verilemeyecek konulardan olduğu"], "answer": 2, "why": ["Yanlış. m.82 ve m.83'e göre patent verilebilirlik şartlarının taşınmaması itiraz gerekçesidir (SMK m.99/1-a).", "Yanlış. Buluşun m.92/1-3 uyarınca yeterince açıklanmaması itiraz gerekçesidir (SMK m.99/1-b).", "Doğru. Bu gerekçe m.99/1'de sayılmamıştır; mahkemede ileri sürülebilen bir hükümsüzlük nedenidir ve yalnızca buluşu yapan veya halefleri tarafından ileri sürülebilir (SMK m.138/1-ç, m.138/6).", "Yanlış. Bu durum itiraz gerekçesidir (SMK m.99/1-c).", "Yanlış. m.82'ye göre patent verilebilirlik şartlarını taşımama itiraz gerekçesidir (SMK m.99/1-a)."], "ref": "SMK m.99"}, {"id": "PAT-032", "exam": "patent", "topic": "İtiraz", "q": "Patentin verilmesinden sonra üçüncü kişilerin yapacağı itiraz ve sonrasındaki süreç bakımından aşağıdakilerden hangisi doğrudur?", "options": ["İtiraz, verilme kararının bildirim tarihinden itibaren iki ay içinde yapılır.", "İtiraz, patent sahibinin görüşü alınmaksızın Kurul tarafından doğrudan karara bağlanır.", "İtiraz ücretinin süresi içinde ödenmemesi hâlinde Kurum eksikliğin giderilmesi için ek süre verir.", "Kurul itirazı haklı bulursa patentin hükümsüzlüğüne karar verir; ancak bu kararın geçmişe etkisi yoktur.", "İtiraz, verilme kararının Bültende yayımlanmasından itibaren altı ay içinde ücreti ödenerek yapılır; patent sahibi itirazın bildiriminden itibaren üç ay içinde görüş sunabilir veya patentte değişiklik yapabilir."], "answer": 4, "why": ["Yanlış. İki ay, Kurum kararlarına karşı genel itiraz süresidir (SMK m.100); patentin verilmesine itiraz süresi yayımdan itibaren altı aydır (SMK m.99/1).", "Yanlış. İtiraz patent sahibine bildirilir ve onun görüşleri ile değişiklik talepleri dikkate alınarak incelenir (SMK m.99/4).", "Yanlış. Ücretin süresi içinde ödenmemesi hâlinde itiraz yapılmamış sayılır (SMK m.99/2).", "Yanlış. Bu durumda m.139'daki hükümsüzlük sonuçları doğar; hükümsüzlük geçmişe dönük etkilidir (SMK m.99/5, m.139/1).", "Doğru (SMK m.99/1, m.99/4)."], "ref": "SMK m.99"}, {"id": "PAT-033", "exam": "patent", "topic": "Koruma Süresi ve Yıllık Ücretler", "q": "SMK'ya göre patentin koruma süresi ve yıllık ücretlere ilişkin aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Koruma süresi patentin verilme tarihinden itibaren yirmi yıldır.", "Koruma süresi yirmi yıldır; ancak ilaç patentlerinde beş yıla kadar uzatılabilir.", "Koruma süresi başvuru tarihinden başlamak üzere yirmi yıldır ve uzatılamaz; yıllık ücretler başvuru tarihinden itibaren ikinci yılın sona erdiği tarihte ödenmeye başlanır.", "Yıllık ücretlerin vade tarihi, patentin verildiği tarihe tekabül eden ay ve gündür.", "Ek patent için de asıl patentten ayrı olarak yıllık ücret ödenir."], "answer": 2, "why": ["Yanlış. Süre başvuru tarihinden başlar (SMK m.101/1).", "Yanlış. Koruma süreleri uzatılamaz (SMK m.101/1).", "Doğru (SMK m.101/1-2).", "Yanlış. Vade tarihi başvuru tarihine tekabül eden ay ve gündür (SMK m.101/2).", "Yanlış. Ek patent başvuruları ve ek patentler için yıllık ücret ödenmez (SMK m.123/6)."], "ref": "SMK m.101"}, {"id": "PAT-034", "exam": "patent", "topic": "Koruma Süresi ve Yıllık Ücretler", "q": "Başvuru tarihi 15.05.2022 olan bir patentin 15.05.2025 vade tarihli yıllık ücreti vadesinde ödenmemiştir. SMK m.101'e göre aşağıdakilerden hangisi doğrudur?", "options": ["Ücret ek ücretle birlikte 15.11.2025 tarihine kadar ödenebilir; bu sürede de ödenmezse patent hakkı 15.05.2025 vade tarihi itibarıyla sona erer.", "Ücret ödenmediğinden patent hakkı 15.05.2025 tarihinde kesin olarak sona erer; ek süre tanınmaz.", "Ücret ek ücretle birlikte 15.08.2025 tarihine kadar ödenebilir.", "Ek süre de geçirilirse patent hakkı, ek sürenin bittiği 15.11.2025 tarihi itibarıyla sona erer.", "Ek süre de geçirilirse patent hakkı sona erer ve hiçbir şekilde yeniden geçerlilik kazanamaz."], "answer": 0, "why": ["Doğru. Vadeyi takip eden altı ay içinde ek ücretle ödeme yapılabilir (SMK m.101/3); ödenmezse hak vade tarihi itibarıyla sona erer (SMK m.101/4).", "Yanlış. Vadeyi takip eden altı aylık ek ödeme süresi vardır (SMK m.101/3).", "Yanlış. Ek ödeme süresi üç ay değil altı aydır (SMK m.101/3).", "Yanlış. Hak, ücretin vade tarihi itibarıyla sona erer (SMK m.101/4).", "Yanlış. Sona erme bildiriminden itibaren iki ay içinde telafi ücreti ödenirse hak yeniden geçerlilik kazanır (SMK m.101/4)."], "ref": "SMK m.101"}, {"id": "PAT-035", "exam": "patent", "topic": "Patent Hakkının Kapsamı ve Sınırları", "q": "Aşağıdaki fiillerden hangisi SMK m.85/3 uyarınca patentin sağladığı hakkın kapsamı dışında kalmaz?", "options": ["Bir eczanede patentli bir ilacın reçeteye bağlı olmaksızın seri üretimle hazırlanıp satılması", "Sınai veya ticari bir amaç taşımayan ve özel maksatla sınırlı kalan fiiller", "İlaç ruhsatı için gerekli test ve deneyler dâhil, patent konusu buluşu içeren deneme amaçlı fiiller", "Paris Sözleşmesine taraf bir devlete ait geminin geçici olarak Türkiye'de bulunduğu sırada patentli buluşun gemide kullanılması", "Patent konusu buluşu içeren deneme amaçlı fiiller"], "answer": 0, "why": ["Doğru. İstisna yalnızca sadece bir reçetenin oluşturulması için eczanelerde seri üretim olmadan hazırlanan ilaçları kapsar (SMK m.85/3-ç); seri üretim patent sahibinin hakkı kapsamındadır.", "Yanlış. Bu fiiller hakkın kapsamı dışındadır (SMK m.85/3-a).", "Yanlış. Bu fiiller hakkın kapsamı dışındadır (SMK m.85/3-c).", "Yanlış. Bu kullanım hakkın kapsamı dışındadır (SMK m.85/3-d).", "Yanlış. Bu fiiller hakkın kapsamı dışındadır (SMK m.85/3-b)."], "ref": "SMK m.85"}, {"id": "PAT-036", "exam": "patent", "topic": "Önceki Kullanım Hakkı", "q": "Başvuru tarihinden önce buluşu Türkiye'de iyiniyetle kullanmakta olan kişinin önceki kullanımdan doğan hakkı ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Bu kişi, buluşun kullanımını herhangi bir sınırlama olmaksızın genişletebilir.", "Hak yalnızca buluşu fiilen kullanmaya başlamış olanlara tanınır; kullanım için ciddi ve gerçek tedbir almış olmak yeterli değildir.", "Bu kişi tarafından satışa sunulmuş ürünlerle ilgili sonraki fiiller patent hakkına tecavüz oluşturur.", "Önceki kullanım hakkı, yurt dışında yapılan iyiniyetli kullanımlar için de tanınır.", "Bu hak, lisans verilmesi suretiyle genişletilemez ve ancak işletme ile birlikte devredilebilir."], "answer": 4, "why": ["Yanlış. Kullanım, sahip olunan işletmenin makul ihtiyaçlarını giderecek ölçüde olabilir (SMK m.87/1).", "Yanlış. Kullanım için ciddi ve gerçek tedbirler almış kişiler de bu haktan yararlanır (SMK m.87/1).", "Yanlış. Bu ürünlerle ilgili fiiller patentin sağladığı hakkın kapsamı dışındadır (SMK m.87/2).", "Yanlış. Hak, buluşu ülke içinde kullanan veya ülke içinde ciddi tedbir alanlara tanınır (SMK m.87/1).", "Doğru (SMK m.87/1)."], "ref": "SMK m.87"}, {"id": "PAT-037", "exam": "patent", "topic": "Kullanma Zorunluluğu ve Zorunlu Lisans", "q": "Başvuru tarihi 10.02.2020 olan bir patentin verilmesi kararı 20.06.2021 tarihinde Bültende yayımlanmıştır. Patent konusu buluşun kullanılmaması gerekçesiyle zorunlu lisans en erken hangi tarihten itibaren talep edilebilir?", "options": ["10.02.2024", "10.02.2023", "20.06.2023", "20.06.2024", "20.06.2025"], "answer": 3, "why": ["Yanlış. Bu, başvurudan itibaren dört yıllık sürenin bitimidir; ancak daha geç sona eren süre esas alınır (SMK m.130/2).", "Yanlış. Başvuru tarihinden itibaren süre üç değil dört yıldır ve daha geç sona eren süre esas alınır (SMK m.130/2).", "Yanlış. Verilme yayımından itibaren süre iki değil üç yıldır (SMK m.130/2).", "Doğru. Verilme kararının yayımından itibaren üç yıl (20.06.2024) ile başvuru tarihinden itibaren dört yıldan (10.02.2024) hangisi daha geç sona eriyorsa o sürenin bitiminden itibaren talep edilebilir (SMK m.130/2).", "Yanlış. Verilme yayımından itibaren dört yıl değil üç yıl esas alınır (SMK m.130/2)."], "ref": "SMK m.130"}, {"id": "PAT-038", "exam": "patent", "topic": "Kullanma Zorunluluğu ve Zorunlu Lisans", "q": "SMK'ya göre zorunlu lisans gerekçesi ile talebin yöneltileceği veya kararı verecek merci arasındaki eşleştirmelerden hangisi doğrudur?", "options": ["Patent sahibinin rekabeti engelleyici, bozucu veya kısıtlayıcı faaliyetlerde bulunması – Rekabet Kurumu", "Patent konusu buluşun kullanılmaması – Türk Patent ve Marka Kurumu", "Patent konularının bağımlılığı – Rekabet Kurumu", "Kamu sağlığı veya millî güvenlik nedeniyle kamu yararı – Mahkeme", "Başka ülkelerdeki kamu sağlığı sorunları sebebiyle eczacılık ürünlerinin ihracatı – Cumhurbaşkanı"], "answer": 0, "why": ["Doğru. m.129/1-e kapsamındaki zorunlu lisans Rekabet Kurumundan talep edilir (SMK m.129/2).", "Yanlış. Kullanmama gerekçeli zorunlu lisans mahkemeden talep edilir (SMK m.129/2).", "Yanlış. Bağımlılık gerekçeli zorunlu lisans mahkemeden talep edilir (SMK m.129/2).", "Yanlış. Kamu yararı nedeniyle zorunlu lisansa Cumhurbaşkanınca karar verilir (SMK m.132/1).", "Yanlış. m.129/1-ç kapsamındaki zorunlu lisans mahkemeden talep edilir (SMK m.129/2)."], "ref": "SMK m.129"}, {"id": "PAT-039", "exam": "patent", "topic": "Kullanma Zorunluluğu ve Zorunlu Lisans", "q": "Zorunlu lisansın hukuki niteliğine ilişkin aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Zorunlu lisans alan kural olarak alt lisans verebilir.", "Zorunlu lisans kural olarak inhisari değildir; ancak kamu yararı gerekçesiyle verilen zorunlu lisanslar inhisari olabilir.", "Zorunlu lisans alan, patent konusu ürünü her durumda ithal edebilir.", "Zorunlu lisans, işletmeden bağımsız olarak serbestçe devredilebilir.", "Mahkeme bedeli belirlerken patentin ekonomik değerini dikkate alamaz."], "answer": 1, "why": ["Yanlış. Zorunlu lisans alanın alt lisans verme hakkı yoktur (SMK m.133/2).", "Doğru (SMK m.133/1, m.132/3).", "Yanlış. Kural olarak ithal hakkı yoktur; yalnızca kamu yararı gerekçeli lisansta açıkça yetkilendirilmişse, ihtiyaçla sınırlı ve geçici olarak ithal edilebilir (SMK m.133/2).", "Yanlış. Devrin geçerliliği için işletme veya işletmenin lisansın değerlendirildiği kısmı ile birlikte devredilmesi gerekir (SMK m.135).", "Yanlış. Mahkeme bedeli belirlerken patentin ekonomik değerini göz önüne alır (SMK m.133/1)."], "ref": "SMK m.133"}, {"id": "PAT-040", "exam": "patent", "topic": "Sözleşmeye Dayalı Lisans", "q": "Bir patent lisans sözleşmesinde lisansın türü ve alt lisans konusunda hiçbir hüküm bulunmamaktadır. SMK'ya göre aşağıdakilerden hangisi doğrudur?", "options": ["Lisans inhisari nitelikte sayılır; lisans veren başkasına lisans veremez.", "Lisans inhisari değildir ve lisans alan haklarını üçüncü kişilere serbestçe devredebilir.", "Lisans veren, patent konusu buluşu kendisi kullanamaz.", "Lisans inhisari olmayan nitelikte olup lisans alan alt lisans veremez.", "Lisans alan, buluşu yalnızca sözleşmenin yapıldığı yıl boyunca kullanabilir."], "answer": 3, "why": ["Yanlış. Aksi kararlaştırılmamışsa lisans inhisari değildir (SMK m.125/2).", "Yanlış. Aksi kararlaştırılmamışsa lisans alan haklarını devredemez (SMK m.125/3).", "Yanlış. Bu kısıtlama inhisari lisansa özgüdür; inhisari olmayan lisansta lisans veren buluşu kendisi de kullanabilir (SMK m.125/2).", "Doğru. Aksi kararlaştırılmamışsa lisans inhisari değildir (SMK m.125/2) ve lisans alan haklarını devredemez veya alt lisans veremez (SMK m.125/3).", "Yanlış. Aksi kararlaştırılmamışsa lisans alan patentin koruma süresi boyunca her türlü kullanma tasarrufunda bulunabilir (SMK m.125/4)."], "ref": "SMK m.125"}, {"id": "PAT-041", "exam": "patent", "topic": "Sözleşmeye Dayalı Lisans", "q": "Lisans verme teklifine ilişkin aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Patent başvurusu sahibi de lisans verme teklifinde bulunabilir.", "Lisans verme teklifi bir kez Bültende yayımlandıktan sonra geri alınamaz.", "Teklif, Kuruma yapılacak yazılı taleple yapılır.", "Sicilde kayıtlı inhisari lisans varsa lisans verme teklifinde bulunulamaz.", "Lisans verme teklifi Bültende yayımlanır."], "answer": 1, "why": ["Doğru ifade (SMK m.128/1).", "Doğru cevap (yanlış ifade). Patent başvurusu veya patent sahibi lisans verme teklifini her zaman geri alabilir; geri alma Bültende yayımlanır (SMK m.128/3).", "Doğru ifade (SMK m.128/1).", "Doğru ifade (SMK m.128/2).", "Doğru ifade (SMK m.128/1)."], "ref": "SMK m.128"}, {"id": "PAT-042", "exam": "patent", "topic": "Hükümsüzlük", "q": "Patentin hükümsüzlüğüne ilişkin aşağıdaki ifadelerden hangileri doğrudur?\nI. Hükümsüzlük davası, patentin koruma süresince veya hakkın sona ermesini izleyen beş yıl içinde, sicile patent sahibi olarak kayıtlı kişiye karşı açılabilir.\nII. Patent sahibinin m.109'a göre patent isteme hakkına sahip olmadığı gerekçesiyle hükümsüzlüğü Cumhuriyet savcısı da isteyebilir.\nIII. Hükümsüzlük nedeni bir istemin yalnızca bir bölümüne ilişkinse mahkeme o istemin kısmen hükümsüzlüğüne karar verebilir.", "options": ["Yalnız I", "Yalnız II", "I ve II", "I ve III", "I, II ve III"], "answer": 0, "why": ["Doğru. Yalnız I doğrudur (SMK m.138/5); II yanlıştır, bu gerekçeyle hükümsüzlüğü ancak buluşu yapan veya halefleri isteyebilir (SMK m.138/6); III yanlıştır, bir istemin kısmen hükümsüzlüğüne karar verilemez (SMK m.138/4).", "Yanlış. II yanlıştır; m.109'a dayalı hükümsüzlüğü yalnızca buluşu yapan veya halefleri isteyebilir (SMK m.138/3, m.138/6).", "Yanlış. II yanlıştır (SMK m.138/6).", "Yanlış. III yanlıştır; bir istemin kısmen hükümsüzlüğüne karar verilemez (SMK m.138/4).", "Yanlış. II ve III yanlıştır (SMK m.138/4, m.138/6)."], "ref": "SMK m.138"}, {"id": "PAT-043", "exam": "patent", "topic": "Hükümsüzlük", "q": "Patentin hükümsüzlüğüne karar verilmesinin etkileri bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Hükümsüzlük kararı ileriye dönük etkilidir; karar tarihine kadar patent koruması geçerli kabul edilir.", "Kesinleşmiş hükümsüzlük kararı yalnızca davanın taraflarını bağlar.", "Tecavüz sebebiyle verilmiş, kesinleşmiş ve uygulanmış kararlar hükümsüzlük nedeniyle kendiliğinden ortadan kalkar.", "Patent sahibinin ağır ihmali veya kötüniyeti bulunsa bile zarar görenler tazminat talep edemez.", "Hükümsüzlük kararından önce yapılmış ve uygulanmış sözleşmeler kural olarak etkilenmez; ancak ödenmiş bedelin hakkaniyet gereğince kısmen veya tamamen iadesi talep edilebilir."], "answer": 4, "why": ["Yanlış. Kararın sonuçları geçmişe dönük etkilidir ve koruma hiç doğmamış sayılır (SMK m.139/1).", "Yanlış. Kesinleşmiş hükümsüzlük kararı herkese karşı hüküm doğurur (SMK m.139/4).", "Yanlış. Bu kararlar hükümsüzlüğün geçmişe etkisinden etkilenmez (SMK m.139/2-a).", "Yanlış. Ağır ihmal veya kötüniyetten zarar görenlerin tazminat talepleri saklıdır (SMK m.139/2).", "Doğru (SMK m.139/2-b, m.139/3)."], "ref": "SMK m.139"}, {"id": "PAT-044", "exam": "patent", "topic": "Hakkın Sona Ermesi", "q": "Patent hakkının sona ermesine ilişkin aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Patent sahibi ancak patentin tamamından vazgeçebilir; istemlerden kısmen vazgeçme mümkün değildir.", "Sicilde kayıtlı lisans sahiplerinin izni aranmaksızın patentten vazgeçilebilir.", "Hakkı sona eren patentin konusu, sona ermenin Bültende yayımlandığı tarihten itibaren kamuya ait olur.", "Patentten vazgeçme Kuruma yazılı olarak bildirilir ve sicile kayıt tarihi itibarıyla hüküm doğurur.", "Yıllık ücretlerin ödenmemesi patent hakkının sona erme sebepleri arasında yer almaz."], "answer": 3, "why": ["Yanlış. Patent sahibi bir ya da birden çok istemden de vazgeçebilir (SMK m.140/3).", "Yanlış. Sicile kayıtlı hak ve lisans sahiplerinin izni olmadıkça patentten vazgeçilemez (SMK m.140/5).", "Yanlış. Patent konusu, sona erme nedeninin gerçekleştiği andan itibaren kamuya ait olur (SMK m.140/2).", "Doğru (SMK m.140/4).", "Yanlış. Yıllık ücretlerin m.101'deki sürelerde ödenmemesi bir sona erme sebebidir (SMK m.140/1-c)."], "ref": "SMK m.140"}, {"id": "PAT-045", "exam": "patent", "topic": "İspat Yükü (Usul Patenti)", "q": "Konusu yeni bir kimyasal maddenin elde edilmesine ilişkin usul olan bir patente tecavüz davasında, davalının patent sahibinin izni olmadan aynı maddeyi ürettiği tespit edilmiştir. SMK m.141/2'ye göre ispat yükü bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Patent sahibi, davalının patentli usulü kullandığını her durumda ispat etmek zorundadır.", "Ürün yeni olsa dahi karine uygulanmaz; mahkeme ispat yükünü değiştiremez.", "Aynı maddenin patentli usulle elde edildiği kabul edilir; aksini iddia eden davalı bunu ispatla yükümlüdür.", "Davalı farklı usul kullandığını ispat ederken üretim ve işletme sırlarını açıklamak zorundadır; haklı menfaati dikkate alınmaz.", "Bu karine yalnızca ürün patentleri için geçerlidir; usul patentlerinde uygulanmaz."], "answer": 2, "why": ["Yanlış. Ürün yeniyse ispat yükü davalıya geçer (SMK m.141/2).", "Yanlış. Mahkeme davalıdan farklı usul kullandığını ispatlamasını isteyebilir ve yeni ürünlerde karine uygulanır (SMK m.141/2).", "Doğru. Usulle elde edilen ürün yeniyse izinsiz üretilen aynı ürünün patentli usulle elde edildiği kabul edilir ve aksini iddia eden ispatla yükümlüdür (SMK m.141/2).", "Yanlış. Davalının üretim ve işletme sırlarının korunmasındaki haklı menfaati göz önünde tutulur (SMK m.141/2).", "Yanlış. Karine tam olarak bir ürün veya maddenin elde edilmesine ilişkin usul patentleri için öngörülmüştür (SMK m.141/2)."], "ref": "SMK m.141"}, {"id": "HUK-001", "exam": "ortak", "topic": "Medeni Hukuk – Başlangıç Hükümleri", "q": "Türk Medeni Kanunu'na göre, bir uyuşmazlıkta uygulanabilir bir kanun hükmü bulunmadığı takdirde hâkim öncelikle neye göre karar verir?", "options": ["Kendisi kanun koyucu olsaydı koyacağı kurala göre", "Örf ve âdet hukukuna göre", "Yargıtay kararlarına göre", "Bilimsel görüşlere göre", "Tarafların ortak iradesine göre"], "answer": 1, "why": ["Yanlış. Hâkimin kanun koyucu gibi kural koyması, örf ve âdet hukuku da bulunmadığında başvurulan son aşamadır (TMK m.1/2).", "Doğru. Uygulanabilir kanun hükmü yoksa hâkim önce örf ve âdet hukukuna göre karar verir (TMK m.1/2).", "Yanlış. Hâkim karar verirken yargı kararlarından yararlanır; ancak bunlar örf ve âdetten önce gelen bağlayıcı bir kaynak olarak sayılmamıştır (TMK m.1/3).", "Yanlış. Bilimsel görüşler, hâkimin yararlandığı yardımcı kaynaklardır; bağlayıcı kaynak değildir (TMK m.1/3).", "Yanlış. TMK m.1'de kanun boşluğunda başvurulacak kaynak olarak tarafların ortak iradesi sayılmamıştır."], "ref": "TMK m.1"}, {"id": "HUK-002", "exam": "ortak", "topic": "Medeni Hukuk – Dürüstlük Kuralı", "q": "Dürüstlük kuralı ve hakkın kötüye kullanılması yasağı ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "options": ["Dürüstlük kuralı yalnızca borçların yerine getirilmesinde uygulanır; hakların kullanılmasında uygulanmaz.", "Hakkın kötüye kullanılması, ancak taraflardan biri ileri sürerse dikkate alınabilir.", "Dürüstlük kuralı yalnızca tacirler arasındaki ilişkilerde uygulanır.", "Bir hakkın açıkça kötüye kullanılmasını hukuk düzeni korumaz.", "Hakkın kötüye kullanılmasından söz edebilmek için hak sahibinin zarar verme kastıyla hareket etmesi şarttır."], "answer": 3, "why": ["Yanlış. Herkes hem haklarını kullanırken hem de borçlarını yerine getirirken dürüstlük kurallarına uymak zorundadır (TMK m.2/1).", "Yanlış. Dürüstlük kuralı ve hakkın kötüye kullanılması yasağı, hâkim tarafından kendiliğinden (re'sen) gözetilir.", "Yanlış. TMK m.2 'herkes' için geçerli genel bir ilkedir; tacir olma koşulu aranmaz.", "Doğru. TMK m.2/2 aynen bu hükmü içerir.", "Yanlış. Hakkın kötüye kullanılması objektif bir ölçüte dayanır; kast aranmaz, hakkın açıkça amacı dışında kullanılması yeterlidir."], "ref": "TMK m.2"}, {"id": "HUK-003", "exam": "ortak", "topic": "Medeni Hukuk – İyiniyet", "q": "Kanunun iyiniyete hukuki sonuç bağladığı durumlarla ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Asıl olan iyiniyetin varlığıdır; ancak durumun gereklerine göre kendisinden beklenen özeni göstermeyen kimse iyiniyet iddiasında bulunamaz.", "İyiniyet iddiasında bulunan kişi, iyiniyetini ispatla yükümlüdür.", "Kötüniyet karine olarak kabul edilir.", "İyiniyet ancak resmî senetle ispat edilebilir.", "Beklenen özeni göstermeyen kişi de iyiniyetli sayılmaya devam eder; özen eksikliği yalnızca tazminatı azaltır."], "answer": 0, "why": ["Doğru. TMK m.3 iyiniyetin karine olarak varlığını ve özen göstermeyenin iyiniyet iddia edemeyeceğini düzenler.", "Yanlış. İyiniyet karine olarak var sayılır; ispat yükü kötüniyeti iddia edendedir (TMK m.3/1).", "Yanlış. Kanunun kabul ettiği karine iyiniyetin varlığıdır, kötüniyetin değil (TMK m.3/1).", "Yanlış. İyiniyet zaten karinedir; resmî senetle ispat şartı yoktur.", "Yanlış. Durumun gereklerine göre beklenen özeni göstermeyen kişi iyiniyet iddiasında bulunamaz (TMK m.3/2)."], "ref": "TMK m.3"}, {"id": "HUK-004", "exam": "ortak", "topic": "Medeni Hukuk – İspat Yükü", "q": "Aşağıdaki ifadelerden hangileri Türk Medeni Kanunu'na göre doğrudur?\nI. Kanunda aksine bir hüküm bulunmadıkça, taraflardan her biri hakkını dayandırdığı olguların varlığını ispatla yükümlüdür.\nII. Resmî sicil ve senetler, belgeledikleri olguların doğruluğuna kanıt oluşturur.\nIII. Resmî sicil ve senetlerin içeriğinin doğru olmadığı ancak yazılı delille ispat edilebilir.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 2, "why": ["Yanlış. II. öncül de doğrudur; resmî sicil ve senetler belgeledikleri olguların doğruluğuna kanıt oluşturur (TMK m.7).", "Yanlış. I. öncül TMK m.6'daki genel ispat yükü kuralıdır ve doğrudur.", "Doğru. I (TMK m.6) ve II (TMK m.7/1) doğrudur; III yanlıştır çünkü içeriğin doğru olmadığının ispatı özel bir şekle bağlı değildir (TMK m.7/2).", "Yanlış. III. öncül yanlıştır: resmî belgenin aksinin ispatı herhangi bir şekle bağlı tutulmamıştır (TMK m.7/2).", "Yanlış. III. öncül yanlış olduğundan tüm öncüller doğru değildir (TMK m.7/2)."], "ref": "TMK m.6, m.7"}, {"id": "HUK-005", "exam": "ortak", "topic": "Kişiler Hukuku – Hak Ehliyeti", "q": "Türk Medeni Kanunu'na göre ceninin (ana rahmindeki çocuğun) hak ehliyeti ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Cenin hiçbir şekilde hak ehliyetine sahip değildir; hak ehliyeti yalnızca doğumla başlar.", "Ceninin hak ehliyeti, nüfus siciline tescil edildiği anda başlar.", "Cenin, ayırt etme gücüne sahip olduğu andan itibaren hak ehliyeti kazanır.", "Cenin, ölü doğsa bile ana rahmine düştüğü andan itibaren kazandığı hakları korur.", "Cenin, sağ doğmak koşuluyla ana rahmine düştüğü andan başlayarak hak ehliyetine sahiptir."], "answer": 4, "why": ["Yanlış. Kişilik tam ve sağ doğumla başlasa da cenin, sağ doğmak koşuluyla ana rahmine düştüğü andan itibaren hak ehliyetine sahiptir (TMK m.28).", "Yanlış. Hak ehliyeti nüfus siciline tescile bağlı değildir (TMK m.28).", "Yanlış. Ayırt etme gücü fiil ehliyetinin koşuludur; hak ehliyetiyle ilgisi yoktur (TMK m.8, m.10).", "Yanlış. Ceninin hak ehliyeti sağ doğma koşuluna bağlıdır (TMK m.28/2).", "Doğru. TMK m.28/2 ceninin sağ doğmak koşuluyla ana rahmine düştüğü andan itibaren hak ehliyetine sahip olduğunu düzenler."], "ref": "TMK m.28"}, {"id": "HUK-006", "exam": "ortak", "topic": "Kişiler Hukuku – Erginlik", "q": "Türk Medeni Kanunu'na göre bir küçüğün mahkeme kararıyla ergin kılınabilmesi (kazai rüşt) için en az kaç yaşını doldurmuş olması gerekir?", "options": ["12", "14", "15", "16", "17"], "answer": 2, "why": ["Yanlış. Kanunda öngörülen alt yaş sınırı 15'tir (TMK m.12).", "Yanlış. Kanunda öngörülen alt yaş sınırı 15'tir (TMK m.12).", "Doğru. On beş yaşını dolduran küçük, kendi isteği ve velisinin rızasıyla mahkeme kararıyla ergin kılınabilir (TMK m.12).", "Yanlış. 16 yaş, kazai rüşt için değil; alt yaş sınırı 15'tir (TMK m.12).", "Yanlış. Kazai rüşt için 15 yaşın doldurulması yeterlidir; erginlik ise kural olarak 18 yaşın doldurulmasıyla başlar (TMK m.11, m.12)."], "ref": "TMK m.12"}, {"id": "HUK-007", "exam": "ortak", "topic": "Kişiler Hukuku – Sınırlı Ehliyetsizler", "q": "16 yaşındaki ve ayırt etme gücüne sahip Can, velisinin rızası olmaksızın aşağıdaki işlemlerden hangisini tek başına geçerli olarak yapabilir?", "options": ["Taksitle bir otomobil satın almak", "Bir bankadan tüketici kredisi almak", "Bir konut için kira sözleşmesi yapmak", "Kendisine yapılan karşılıksız (yükümsüz) bir bağışlamayı kabul etmek", "Bir arkadaşının borcuna kefil olmak"], "answer": 3, "why": ["Yanlış. Ayırt etme gücüne sahip küçükler, yasal temsilcilerinin rızası olmadıkça kendi işlemleriyle borç altına giremez (TMK m.16/1).", "Yanlış. Bu işlem küçüğü borç altına sokar; yasal temsilcinin rızası gerekir (TMK m.16/1).", "Yanlış. Kira sözleşmesi kira bedeli ödeme borcu doğurur; yasal temsilcinin rızası olmaksızın yapılamaz (TMK m.16/1).", "Doğru. Ayırt etme gücüne sahip küçükler, karşılıksız kazanmalar için yasal temsilcinin rızasına muhtaç değildir (TMK m.16/2).", "Yanlış. Kefalet küçüğü borç altına sokan bir işlemdir; küçük bunu yasal temsilcisinin rızası olmadan yapamaz (TMK m.16/1)."], "ref": "TMK m.16"}, {"id": "HUK-008", "exam": "ortak", "topic": "Kişiler Hukuku – Ayırt Etme Gücü", "q": "Ayırt etme gücü bulunmayan bir kişinin yaptığı hukuki işlemler bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Kanunda gösterilen ayrık durumlar saklı kalmak üzere, fiilleri hukuki sonuç doğurmaz.", "Yasal temsilcisinin sonradan onay vermesiyle geçerli hâle gelir.", "Karşı taraf iyiniyetliyse işlem geçerli olur.", "Yalnızca karşılıklı borç doğuran işlemleri geçersizdir; tek taraflı işlemleri geçerlidir.", "İşlem iptal edilebilir niteliktedir; bir yıl içinde iptal edilmezse geçerli hâle gelir."], "answer": 0, "why": ["Doğru. TMK m.14 aynen bu kuralı koyar.", "Yanlış. Sonradan onayla geçerlilik, ayırt etme gücüne sahip sınırlı ehliyetsizler için söz konusudur; ayırt etme gücü olmayanın işlemi hukuki sonuç doğurmaz (TMK m.14, m.16).", "Yanlış. Karşı tarafın iyiniyeti, ayırt etme gücü bulunmayanın işlemini geçerli kılmaz (TMK m.14).", "Yanlış. Kanun böyle bir ayrım yapmaz; kural olarak fiilleri hukuki sonuç doğurmaz (TMK m.14).", "Yanlış. TMK m.14'e göre işlem hukuki sonuç doğurmaz; bir yıllık iptal süresi öngörülmemiştir."], "ref": "TMK m.14"}, {"id": "HUK-009", "exam": "ortak", "topic": "Kişiler Hukuku – Kısıtlılık", "q": "Aşağıdakilerden hangisi Türk Medeni Kanunu'nda düzenlenen kısıtlama sebeplerinden biri değildir?", "options": ["Akıl hastalığı veya akıl zayıflığı", "Savurganlık, alkol veya uyuşturucu bağımlılığı ya da kötü yönetim", "Bir yıl veya daha uzun süreli özgürlüğü bağlayıcı bir cezaya hükümlü olmak", "Yaşlılık, engellilik, deneyimsizlik veya ağır hastalık sebebiyle kişinin kendi isteği", "İflas etmiş olmak"], "answer": 4, "why": ["Yanlış. Akıl hastalığı veya akıl zayıflığı kısıtlama sebebidir (TMK m.405).", "Yanlış. Bunlar TMK m.406'da sayılan kısıtlama sebepleridir.", "Yanlış. Bu durum kısıtlama sebebidir (TMK m.407).", "Yanlış. Kişinin kendi isteği üzerine kısıtlanması mümkündür (TMK m.408).", "Doğru (kısıtlama sebebi değildir). İflas, TMK'da sayılan kısıtlama sebepleri arasında yer almaz."], "ref": "TMK m.405-408"}, {"id": "HUK-010", "exam": "ortak", "topic": "Kişiler Hukuku – Kişiliğin Korunması", "q": "Türk Medeni Kanunu'na göre aşağıdakilerden hangileri kişilik hakkına yapılan saldırıyı hukuka uygun kılan sebeplerdendir?\nI. Kişilik hakkı zedelenen kimsenin rızası\nII. Daha üstün nitelikte özel veya kamusal yarar\nIII. Kanunun verdiği yetkinin kullanılması", "options": ["Yalnız I", "I ve II", "I ve III", "II ve III", "I, II ve III"], "answer": 4, "why": ["Yanlış. II ve III de TMK m.24/2'de sayılan hukuka uygunluk sebepleridir.", "Yanlış. Kanunun verdiği yetkinin kullanılması (III) da hukuka uygunluk sebebidir (TMK m.24/2).", "Yanlış. Üstün nitelikte özel veya kamusal yarar (II) da hukuka uygunluk sebebidir (TMK m.24/2).", "Yanlış. Zarar görenin rızası (I) da hukuka uygunluk sebebidir (TMK m.24/2).", "Doğru. TMK m.24/2'ye göre rıza, daha üstün nitelikte özel veya kamusal yarar ya da kanunun verdiği yetkinin kullanılması ile haklı kılınmayan her saldırı hukuka aykırıdır."], "ref": "TMK m.24"}, {"id": "HUK-011", "exam": "ortak", "topic": "Kişiler Hukuku – Ad Üzerindeki Hak", "q": "Türk Medeni Kanunu'na göre adın değiştirilmesinden zarar gören kişi, değiştirmeyi öğrendiği tarihten başlayarak hangi süre içinde dava açabilir?", "options": ["3 ay", "1 yıl", "6 ay", "2 yıl", "5 yıl"], "answer": 1, "why": ["Yanlış. Kanunda öngörülen süre bir yıldır (TMK m.27/2).", "Doğru. Adın değiştirilmesinden zarar gören kişi, değiştirmeyi öğrendiği tarihten başlayarak bir yıl içinde dava açabilir (TMK m.27/2).", "Yanlış. Kanunda öngörülen süre bir yıldır (TMK m.27/2).", "Yanlış. Kanunda öngörülen süre bir yıldır (TMK m.27/2).", "Yanlış. Kanunda öngörülen süre bir yıldır (TMK m.27/2)."], "ref": "TMK m.27"}, {"id": "HUK-012", "exam": "ortak", "topic": "Kişiler Hukuku – Yerleşim Yeri", "q": "Yerleşim yeri ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Velayet altındaki çocuğun yerleşim yeri, vesayet makamının bulunduğu yerdir.", "Yerleşim yeri, bir kimsenin sürekli kalma niyetiyle oturduğu yerdir.", "Kimse aynı anda birden çok yerleşim yerine sahip olamaz.", "Bir kimsenin aynı anda birden çok yerleşim yerine sahip olamayacağına ilişkin kural, ticari ve sınai kuruluşlar için uygulanmaz.", "Yeni bir yerleşim yeri edinilmedikçe önceki yerleşim yeri devam eder."], "answer": 0, "why": ["Yanlış ifade (doğru cevap). Velayet altındaki çocuğun yerleşim yeri ana ve babasının yerleşim yeridir; vesayet makamının bulunduğu yer, vesayet altındaki kişilerin yerleşim yeridir (TMK m.21).", "Doğru ifade. TMK m.19/1'deki tanımdır.", "Doğru ifade. TMK m.19/2 yerleşim yerinin tekliği ilkesini koyar.", "Doğru ifade. TMK m.19/2 bu istisnayı açıkça öngörür.", "Doğru ifade. Yerleşim yerinin devamlılığı ilkesi (TMK m.20)."], "ref": "TMK m.19-21"}, {"id": "HUK-013", "exam": "ortak", "topic": "Kişiler Hukuku – Dernek", "q": "Türk Medeni Kanunu'na göre bir derneğin kurulabilmesi için en az kaç gerçek veya tüzel kişinin bir araya gelmesi gerekir?", "options": ["3", "5", "7", "10", "15"], "answer": 2, "why": ["Yanlış. Kanunda aranan asgari sayı yedidir (TMK m.56).", "Yanlış. Kanunda aranan asgari sayı yedidir (TMK m.56).", "Doğru. Dernek, en az yedi gerçek veya tüzel kişinin kazanç paylaşma dışında belirli ve ortak bir amacı gerçekleştirmek için bilgi ve çalışmalarını sürekli olarak birleştirmeleriyle oluşan kişi topluluğudur (TMK m.56).", "Yanlış. Kanunda aranan asgari sayı yedidir (TMK m.56).", "Yanlış. Kanunda aranan asgari sayı yedidir (TMK m.56)."], "ref": "TMK m.56"}, {"id": "HUK-014", "exam": "ortak", "topic": "Kişiler Hukuku – Vakıf", "q": "Vakıflar ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Vakıf, gerçek veya tüzel kişilerin yeterli mal ve haklarını belirli ve sürekli bir amaca özgülemeleriyle oluşan tüzel kişiliğe sahip mal topluluğudur.", "Vakıf, resmî senetle veya ölüme bağlı tasarrufla kurulur.", "Vakıf, vakfın yerleşim yeri mahkemesince sicile tescili ile tüzel kişilik kazanır.", "Vakıf, kuruluş bildiriminin mülki idare amirliğine verilmesiyle tüzel kişilik kazanır.", "Belirli bir ırk veya cemaat mensuplarını desteklemek amacıyla vakıf kurulamaz."], "answer": 3, "why": ["Doğru ifade. TMK m.101/1'deki tanımdır.", "Doğru ifade. Vakfın kuruluş şekli resmî senet veya ölüme bağlı tasarruftur (TMK m.101).", "Doğru ifade. TMK m.102 vakfın tescille tüzel kişilik kazanacağını düzenler.", "Yanlış ifade (doğru cevap). Kuruluş bildiriminin mülki idare amirliğine verilmesiyle tüzel kişilik kazanılması derneklere özgüdür; vakıf, yerleşim yeri mahkemesince sicile tescil ile tüzel kişilik kazanır (TMK m.102).", "Doğru ifade. TMK m.101/4 bu amaçla vakıf kurulmasını yasaklar."], "ref": "TMK m.101-102"}, {"id": "HUK-015", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Türk Borçlar Kanunu'na göre vekilin vekâlet sözleşmesinden dolayı ücrete hak kazanması bakımından aşağıdakilerden hangisi doğrudur?", "options": ["Vekâlet sözleşmesi her durumda ücretlidir.", "Ücret, ancak yazılı olarak kararlaştırılmışsa istenebilir.", "Vekil, yalnızca tacir ise ücret isteyebilir.", "Ücret açıkça kararlaştırılmamışsa, teamül bulunsa bile ücret istenemez.", "Sözleşmede kararlaştırılmışsa veya teamül varsa vekil ücrete hak kazanır."], "answer": 4, "why": ["Yanlış. Vekâlet ücretsiz de olabilir; ücret ancak kararlaştırılmış veya teamül varsa doğar (TBK m.502/2).", "Yanlış. Kanun yazılı şekil aramaz; teamül bulunması da ücret hakkı doğurur (TBK m.502/2).", "Yanlış. TBK m.502'de tacir olma koşulu yoktur; ölçüt anlaşma veya teamüldür.", "Yanlış. Teamül varsa ücret açıkça kararlaştırılmasa da istenebilir (TBK m.502/2).", "Doğru. TBK m.502/2'ye göre sözleşmede kararlaştırılmışsa veya teamül varsa vekil ücrete hak kazanır."], "ref": "TBK m.502"}, {"id": "HUK-016", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Marka vekilliği hizmetini meslek olarak yürüten ve bunu ilanla duyuran X'e, bir müşterisi marka başvurusu yapılması için öneride bulunmuştur. X öneriyi hemen reddetmemiş, ancak açıkça kabul ettiğini de bildirmemiştir. Türk Borçlar Kanunu'na göre bu durumda aşağıdakilerden hangisi doğrudur?", "options": ["Açık kabul bulunmadığından sözleşme hiçbir şekilde kurulmamıştır.", "Sözleşme, ancak yazılı vekâletname düzenlendiği anda kurulur.", "Vekâlet sözleşmesi kurulmuş sayılır.", "Sözleşme kurulmuş sayılır, ancak X ücret isteyemez.", "Müşteri, X'in sessiz kalmasını kabul sayması için noter ihtarı göndermek zorundadır."], "answer": 2, "why": ["Yanlış. Meslek olarak iş görenler için susma, öneriyi hemen reddetmeme hâlinde kabul sayılır (TBK m.503/2).", "Yanlış. Vekâlet sözleşmesinin kurulması kanunda yazılı şekle bağlanmamıştır; TBK m.503/2'deki karine uygulanır.", "Doğru. Belirli işleri meslek olarak yapan veya yapmayı ilanla bildiren kişi, bu işlere ilişkin öneriyi hemen reddetmezse vekâlet kurulmuş sayılır (TBK m.503/2).", "Yanlış. Ücret, teamül varsa istenebilir; mesleki olarak yürütülen vekillik hizmetlerinde ücret teamülü bulunur (TBK m.502/2).", "Yanlış. Kanun böyle bir ihtar koşulu öngörmez (TBK m.503/2)."], "ref": "TBK m.503"}, {"id": "HUK-017", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Türk Borçlar Kanunu'na göre aşağıdaki işlemlerden hangisini yapabilmek için vekilin ayrıca özel olarak yetkili kılınması gerekmez?", "options": ["Dava açmak", "Sulh olmak", "Bağışlama yapmak", "Kefil olmak", "Üstlendiği işin görülmesi için gerekli olan olağan hukuki işlemleri yapmak"], "answer": 4, "why": ["Yanlış. Vekil özel olarak yetkili kılınmadıkça dava açamaz (TBK m.504/3).", "Yanlış. Sulh olmak özel yetki gerektirir (TBK m.504/3).", "Yanlış. Bağışlama yapmak özel yetki gerektirir (TBK m.504/3).", "Yanlış. Kefil olmak özel yetki gerektirir (TBK m.504/3).", "Doğru. Vekâlet, üstlenilen işin görülmesi için gerekli hukuki işlemleri yapma yetkisini de kapsar (TBK m.504/2)."], "ref": "TBK m.504"}, {"id": "HUK-018", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Türk Borçlar Kanunu'na göre vekilin özen borcunun belirlenmesinde esas alınan ölçüt aşağıdakilerden hangisidir?", "options": ["Vekilin kendi işlerinde gösterdiği özen", "Benzer alanda iş ve hizmetleri üstlenen basiretli bir vekilin göstermesi gereken davranış", "Vekâlet verenin kendi işlerinde göstereceği özen", "Yalnızca vekâlet verenin yazılı talimatında belirtilen özen", "Vekil yalnızca kastından sorumludur; özen ölçüsü aranmaz."], "answer": 1, "why": ["Yanlış. Kanun sübjektif ölçütü değil, basiretli bir vekilin davranışını esas alır (TBK m.506).", "Doğru. TBK m.506/2 özen borcunun belirlenmesinde bu objektif ölçütü esas alır.", "Yanlış. Ölçüt vekâlet verenin özeni değil, basiretli vekilin davranışıdır (TBK m.506).", "Yanlış. Talimata uyma ayrı bir borçtur; özen ölçüsü kanunda objektif olarak belirlenmiştir (TBK m.505, m.506).", "Yanlış. Vekil, işi sadakat ve özenle ifa etmekle yükümlüdür; sorumluluğu kastla sınırlı değildir (TBK m.506)."], "ref": "TBK m.506"}, {"id": "HUK-019", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Vekâlet sözleşmesinde işin başkasına gördürülmesi ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Vekil, vekâlet verenin izni olmadıkça işi kural olarak bizzat görmek zorundadır.\nII. Vekil, yetkisi olmaksızın işi başkasına gördürürse, onun fiillerinden kendisi yapmış gibi sorumlu olur.\nIII. Vekil, yetkili olarak işi başkasına gördürmüşse, alt vekilin bütün fiillerinden kusuru aranmaksızın sorumludur.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 2, "why": ["Yanlış. II. öncül de doğrudur (TBK m.507/1).", "Yanlış. I. öncül de doğrudur; vekil kural olarak işi bizzat görmek zorundadır (TBK m.506/3).", "Doğru. I (TBK m.506/3) ve II (TBK m.507/1) doğrudur. III yanlıştır: yetkili olarak işi başkasına gördüren vekil, yalnızca alt vekili seçmede ve ona talimat vermede gerekli özeni göstermemesinden sorumludur (TBK m.507/2).", "Yanlış. III. öncül yanlıştır; yetkili alt vekil hâlinde sorumluluk seçme ve talimat vermede özenle sınırlıdır (TBK m.507/2).", "Yanlış. III. öncül yanlış olduğundan tüm öncüller doğru değildir (TBK m.507/2)."], "ref": "TBK m.506, m.507"}, {"id": "HUK-020", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Aşağıdakilerden hangisi vekâlet sözleşmesinde vekilin değil, vekâlet verenin borçlarındandır?", "options": ["Vekilin vekâleti gereği gibi ifa ederken yaptığı giderleri faiziyle birlikte ödemek ve vekili üstlendiği borçlardan kurtarmak", "Vekâlet verenin açık talimatına uymak", "İşi sadakat ve özenle ifa etmek", "İstem üzerine yürütülen işin hesabını vermek", "Vekâlet gereği aldıklarını vekâlet verene vermek"], "answer": 0, "why": ["Doğru. Bu, vekâlet verenin borcudur (TBK m.510).", "Yanlış. Talimata uyma vekilin borcudur (TBK m.505).", "Yanlış. Sadakat ve özen borcu vekile aittir (TBK m.506).", "Yanlış. Hesap verme vekilin borcudur (TBK m.508).", "Yanlış. Bu da vekilin hesap verme ve teslim borcunun parçasıdır; geciktirirse faiz öder (TBK m.508)."], "ref": "TBK m.505-510"}, {"id": "HUK-021", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Türk Borçlar Kanunu'na göre vekâlet sözleşmesinin tek taraflı olarak sona erdirilmesi (azil ve istifa) ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Taraflardan her biri sözleşmeyi her zaman sona erdirebilir; ancak uygun olmayan zamanda sona erdiren taraf, diğer tarafın bundan doğan zararını gidermekle yükümlüdür.", "Vekâlet sözleşmesi ancak haklı bir sebebin varlığı hâlinde sona erdirilebilir.", "Yalnızca vekâlet veren sözleşmeyi sona erdirebilir; vekil istifa edemez.", "Uygun olmayan zamanda yapılan azil veya istifa geçersizdir; sözleşme devam eder.", "Sona erdirme ancak bir aylık bildirim süresine uyularak yapılabilir."], "answer": 0, "why": ["Doğru. TBK m.512 vekâlet sözleşmesinin her zaman tek taraflı sona erdirilebileceğini ve uygun olmayan zamanda sona erdirenin zararı gidereceğini düzenler.", "Yanlış. Azil ve istifa her zaman mümkündür; haklı sebep aranmaz (TBK m.512).", "Yanlış. Her iki taraf da sözleşmeyi tek taraflı sona erdirebilir (TBK m.512).", "Yanlış. Uygun olmayan zamanda sona erdirme geçerlidir; sonucu yalnızca zararın giderilmesi yükümlülüğüdür (TBK m.512).", "Yanlış. Kanunda vekâlet için böyle bir bildirim süresi öngörülmemiştir (TBK m.512)."], "ref": "TBK m.512"}, {"id": "HUK-022", "exam": "ortak", "topic": "Vekâlet Sözleşmesi", "q": "Sözleşmeden veya işin niteliğinden aksi anlaşılmadıkça, aşağıdakilerden hangisi vekâlet sözleşmesini sona erdiren hâllerden biri değildir?", "options": ["Vekilin ölümü", "Vekilin, aynı konuda başka bir kişiyle de vekâlet sözleşmesi yapması", "Vekâlet verenin ölümü", "Vekilin ehliyetini kaybetmesi", "Vekâlet verenin iflası"], "answer": 1, "why": ["Yanlış. Vekilin ölümü vekâleti sona erdirir (TBK m.513/1).", "Doğru (sona erme sebebi değildir). Kanunda böyle bir sona erme sebebi öngörülmemiştir.", "Yanlış. Vekâlet verenin ölümü vekâleti sona erdirir; ancak sona erme vekâlet veren için zararlıysa vekil, mirasçılar işi üstlenene kadar işleri yürütmeye devam eder (TBK m.513).", "Yanlış. Ehliyet kaybı sona erme sebebidir (TBK m.513/1).", "Yanlış. İflas sona erme sebebidir (TBK m.513/1)."], "ref": "TBK m.513"}, {"id": "HUK-023", "exam": "ortak", "topic": "Temsil – Yetkisiz Temsil", "q": "B, temsil yetkisi olmadığı hâlde A adına C ile bir sözleşme yapmıştır. C, A'ya uygun bir süre vererek sözleşmeyi onaylayıp onaylamayacağını sormuş; A bu süre içinde herhangi bir açıklama yapmamıştır. Türk Borçlar Kanunu'na göre bu durumda aşağıdakilerden hangisi doğrudur?", "options": ["A'nın susması onay sayılır ve sözleşme A ile C arasında kurulur.", "Sözleşme B ile C arasında kendiliğinden kurulmuş olur.", "Sözleşmenin akıbeti hakkında mahkeme karar verir.", "C, sözleşmeyle bağlı olmaktan kurtulur.", "A, süre geçtikten sonra da sınırsız olarak onay verebilir ve C bununla bağlıdır."], "answer": 3, "why": ["Yanlış. Susma onay sayılmaz; süre içinde onay verilmezse karşı taraf bağlı olmaktan kurtulur (TBK m.46).", "Yanlış. Yetkisiz temsilci sözleşmenin tarafı olmaz; onaylanmayan sözleşme nedeniyle ancak tazminat sorumluluğu doğabilir (TBK m.47).", "Yanlış. Sonuç kanunda doğrudan belirlenmiştir (TBK m.46/2).", "Doğru. Temsil olunan, verilen uygun süre içinde onaylamazsa diğer taraf sözleşmeyle bağlı olmaktan kurtulur (TBK m.46/2).", "Yanlış. Süre içinde onay verilmezse C bağlı olmaktan kurtulur (TBK m.46/2)."], "ref": "TBK m.46"}, {"id": "HUK-024", "exam": "ortak", "topic": "Temsil – Yetkisiz Temsil", "q": "Temsil olunanın yetkisiz temsilcinin yaptığı sözleşmeyi onaylamaması hâlinde, aşağıdaki ifadelerden hangileri doğrudur?\nI. Yetkisiz temsilci, sözleşmenin hükümsüz kalmasından doğan zararı gidermekle yükümlüdür.\nII. Karşı taraf, yetkisizliği biliyor veya bilmesi gerekiyorsa yetkisiz temsilci bu zarardan sorumlu değildir.\nIII. Yetkisiz temsilci kusurlu ise ve hakkaniyet gerektiriyorsa hâkim daha kapsamlı bir tazminata hükmedebilir.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 4, "why": ["Yanlış. II ve III de TBK m.47'de düzenlenmiştir.", "Yanlış. I ve III de doğrudur (TBK m.47).", "Yanlış. III de doğrudur; kusur ve hakkaniyet hâlinde daha kapsamlı tazminata hükmedilebilir (TBK m.47).", "Yanlış. I de doğrudur; yetkisiz temsilcinin temel sorumluluğu hükümsüzlükten doğan zarardır (TBK m.47).", "Doğru. Üç öncül de TBK m.47'de düzenlenen yetkisiz temsilcinin sorumluluğuna ilişkindir."], "ref": "TBK m.47"}, {"id": "HUK-025", "exam": "ortak", "topic": "Temsil", "q": "Temsilci, işlemi yaptığı sırada temsilci sıfatını bildirmemiştir. Türk Borçlar Kanunu'na göre bu durumda kural olarak aşağıdakilerden hangisi doğrudur?", "options": ["İşlemin sonuçları her durumda doğrudan temsil olunanı bağlar.", "İşlem kesin olarak hükümsüzdür.", "İşlemin sonuçları temsilciye ait olur; ancak karşı taraf temsil ilişkisini durumdan çıkarmak zorundaysa veya kiminle işlem yaptığı onun için önemsizse sonuçlar doğrudan temsil olunanı bağlar.", "İşlemin sonuçları temsilci ve temsil olunan arasında yarı yarıya paylaşılır.", "İşlem, karşı tarafın onayına kadar askıda kalır."], "answer": 2, "why": ["Yanlış. Temsil sıfatı bildirilmemişse kural olarak sonuçlar temsilciye ait olur (TBK m.40/2).", "Yanlış. İşlem hükümsüz değildir; sonuçları kural olarak temsilciye ait olur (TBK m.40/2).", "Doğru. TBK m.40/2 bu kuralı ve istisnalarını düzenler.", "Yanlış. Kanunda böyle bir paylaşım öngörülmemiştir (TBK m.40).", "Yanlış. Bu durumda askıda hükümsüzlük söz konusu değildir; askıda kalma yetkisiz temsile özgüdür (TBK m.40, m.46)."], "ref": "TBK m.40"}, {"id": "HUK-026", "exam": "ortak", "topic": "Ticari İşletme", "q": "Ticari işletme ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "options": ["Ticari işletme, esnaf işletmesi için öngörülen sınırı aşan düzeyde gelir sağlamayı hedef tutan faaliyetlerin devamlı ve bağımsız şekilde yürütüldüğü işletmedir.", "Bir işletmenin ticari işletme sayılabilmesi için faaliyetin mutlaka bir tüzel kişi tarafından yürütülmesi gerekir.", "Ticari işletme, işletmeye özgülenen ve işletmenin devamlılığı için gerekli olan unsurların tümünü kapsar.", "Ticari işletme bir bütün hâlinde devredilebilir.", "Ticari işletme bir bütün hâlinde diğer hukuki işlemlere de konu olabilir."], "answer": 1, "why": ["Doğru ifade. TTK m.11/1'deki tanımdır.", "Yanlış ifade (doğru cevap). Ticari işletme gerçek kişi tarafından da işletilebilir; tacir tanımı gerçek ve tüzel kişileri kapsar (TTK m.11, m.12).", "Doğru ifade. TTK m.11/2.", "Doğru ifade. TTK m.11/2.", "Doğru ifade. TTK m.11/2."], "ref": "TTK m.11"}, {"id": "HUK-027", "exam": "ortak", "topic": "Tacir", "q": "Tacir sıfatı ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Bir ticari işletmeyi kısmen de olsa kendi adına işleten kişiye tacir denir.\nII. Kanunen veya meslek ilişkisi nedeniyle ticaret yapması yasak olan kişiler, ticari işletme işletseler bile tacir sayılmaz.\nIII. Fiil ehliyeti bulunmayanlar adına ticari işletme yasal temsilcileri tarafından işletilirse, tacir sıfatı temsil edilene ait olur.", "options": ["Yalnız I", "Yalnız III", "I ve II", "I ve III", "I, II ve III"], "answer": 3, "why": ["Yanlış. III. öncül de doğrudur (TTK m.12/1).", "Yanlış. I. öncül tacirin kanuni tanımıdır ve doğrudur (TTK m.12/1).", "Yanlış. II. öncül yanlıştır; ticaret yapması yasak olanlar ticari işletme işletirlerse yine tacir sayılır (TTK m.12/2).", "Doğru. I ve III TTK m.12/1'e uygundur; II yanlıştır, çünkü ticaret yapması yasak olanlar ticari işletme işletirlerse yine tacir sayılır (TTK m.12/2).", "Yanlış. II. öncül yanlıştır (TTK m.12/2)."], "ref": "TTK m.12"}, {"id": "HUK-028", "exam": "ortak", "topic": "Tacir", "q": "Aşağıdakilerden hangisi ticari işletme kursa veya işletse bile tacir sıfatını kazanmaz?", "options": ["Belediye", "Anonim şirket", "Limited şirket", "Amacını gerçekleştirmek için ticari işletme işleten bir vakıf", "Amacını gerçekleştirmek için ticari işletme işleten, kamu yararına çalışmayan bir dernek"], "answer": 0, "why": ["Doğru. Devlet, il özel idaresi, belediye ve köy gibi kamu tüzel kişileri ticari işletme kursalar veya işletseler bile tacir sıfatını kazanmaz (TTK m.16/2).", "Yanlış. Ticaret şirketleri tacir sayılır (TTK m.16/1).", "Yanlış. Ticaret şirketleri tacir sayılır (TTK m.16/1).", "Yanlış. Amaçlarını gerçekleştirmek için ticari işletme işleten vakıflar tacir sayılır (TTK m.16/1).", "Yanlış. Bu tür dernekler tacir sayılır; kamu yararına çalışan dernekler ise tacir sıfatını kazanmaz (TTK m.16)."], "ref": "TTK m.16"}, {"id": "HUK-029", "exam": "ortak", "topic": "Ticaret Sicili", "q": "Türk Ticaret Kanunu'na göre her tacir, ticari işletmesini ve seçtiği ticaret unvanını, ticari işletmenin açıldığı günden itibaren kaç gün içinde işletme merkezinin bulunduğu yer ticaret sicili müdürlüğüne tescil ve ilan ettirmekle yükümlüdür?", "options": ["7", "15", "10", "30", "60"], "answer": 1, "why": ["Yanlış. Kanunda öngörülen süre on beş gündür (TTK m.40/1).", "Doğru. Tescil ve ilan süresi ticari işletmenin açıldığı günden itibaren on beş gündür (TTK m.40/1).", "Yanlış. Kanunda öngörülen süre on beş gündür (TTK m.40/1).", "Yanlış. Kanunda öngörülen süre on beş gündür (TTK m.40/1).", "Yanlış. Kanunda öngörülen süre on beş gündür (TTK m.40/1)."], "ref": "TTK m.40"}, {"id": "HUK-030", "exam": "ortak", "topic": "Ticaret Sicili", "q": "Türk Ticaret Kanunu'na göre ticaret sicili kayıtları, kural olarak hangi andan itibaren üçüncü kişilere karşı hüküm ifade eder?", "options": ["Tescil başvurusunun sicil müdürlüğüne yapıldığı andan itibaren", "İlanın yapıldığı tarihten itibaren on beş gün geçtikten sonra", "İlanın yapıldığı tarihten itibaren bir ay geçtikten sonra", "İlgili üçüncü kişiye noter aracılığıyla tebliğ edildiği andan itibaren", "Tescilin Türkiye Ticaret Sicili Gazetesinde ilan edildiği günü izleyen iş gününden itibaren"], "answer": 4, "why": ["Yanlış. Başvuru anı değil, ilanı izleyen iş günü esas alınır (TTK).", "Yanlış. Kanun kural olarak ilanı izleyen iş gününü esas alır (TTK).", "Yanlış. Kanun kural olarak ilanı izleyen iş gününü esas alır (TTK).", "Yanlış. Sicilin aleniyeti ilan yoluyla sağlanır; ayrıca tebliğ aranmaz (TTK).", "Doğru. Sicil kayıtları, tescilin TTSG'de ilan edildiği günü izleyen iş gününden itibaren üçüncü kişilere karşı hüküm ifade eder (TTK)."], "ref": "TTK (ticaret sicili hükümleri)"}, {"id": "HUK-031", "exam": "ortak", "topic": "Ticaret Unvanı", "q": "Ticari işletme sahibi gerçek kişinin ticaret unvanı ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Tacir tarafından serbestçe seçilebilir; ad ve soyadın yer alması zorunlu değildir.", "Yalnızca tacirin soyadından oluşur.", "Tacirin ad ve soyadının baş harflerinden oluşturulabilir.", "Kısaltılmamış ad ve soyadından oluşur.", "İşletme konusunun unvanda gösterilmesi zorunludur."], "answer": 3, "why": ["Yanlış. Serbest seçim sermaye şirketleri ve kooperatifler içindir; gerçek kişi tacirin unvanında ad ve soyadı zorunludur (TTK m.41, m.43).", "Yanlış. Unvan, kısaltılmamış ad ve soyadından oluşur (TTK m.41).", "Yanlış. Ad ve soyadın kısaltılmamış olması gerekir (TTK m.41).", "Doğru. Gerçek kişi tacirin ticaret unvanı, kısaltılmamış ad ve soyadından oluşur (TTK m.41).", "Yanlış. Gerçek kişi tacir için zorunlu unsur kısaltılmamış ad ve soyadıdır; işletme konusunu gösterme zorunluluğu sermaye şirketleri ve kooperatifler için öngörülmüştür (TTK m.41, m.43)."], "ref": "TTK m.41"}, {"id": "HUK-032", "exam": "ortak", "topic": "Ticaret Unvanı", "q": "Anonim ve limited şirketlerin ticaret unvanı ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Ortaklardan en az birinin ad ve soyadını içermek zorundadır.", "Bütün ortakların ad ve soyadlarını içermek zorundadır.", "İşletme konusu gösterilmek ve şirket türünü belirten ek bulunmak şartıyla serbestçe seçilebilir.", "Unvanda bir gerçek kişinin adı bulunuyorsa şirket türünü gösteren ek mutlaka kısaltılarak yazılır.", "İşletme konusunun unvanda gösterilmesi gerekmez."], "answer": 2, "why": ["Yanlış. Bu zorunluluk şahıs şirketleri içindir; sermaye şirketleri unvanlarını serbestçe seçebilir (TTK m.43).", "Yanlış. Sermaye şirketlerinde ortakların adlarının unvanda yer alması zorunlu değildir (TTK m.43).", "Doğru. Sermaye şirketleri ve kooperatiflerin unvanı, işletme konusu gösterilmek ve tür eki bulunmak şartıyla serbestçe seçilebilir (TTK m.43).", "Yanlış. Unvanda bir gerçek kişinin adı bulunursa şirket türünü gösteren ek kısaltma olmaksızın yazılır (TTK m.43).", "Yanlış. İşletme konusunun gösterilmesi serbest seçimin şartlarındandır (TTK m.43)."], "ref": "TTK m.43"}, {"id": "HUK-033", "exam": "ortak", "topic": "Ticaret Unvanı", "q": "Ticaret unvanı ile ilgili aşağıdaki ifadelerden hangileri doğrudur?\nI. Ticaret unvanı, işletmeden ayrı olarak başkasına devredilemez.\nII. Tacir, ticari işletmesine ilişkin işlemleri ticaret unvanıyla yapmak ve işletmesine ait senetleri ve diğer belgeleri bu unvanla imzalamak zorundadır.\nIII. Şubeler, merkezin ticaret unvanını aynen kullanmak ve şube olduklarını belirtmek şartıyla şubeye ilişkin ekler içeren bir unvan kullanabilir.", "options": ["Yalnız I", "Yalnız II", "I ve II", "II ve III", "I, II ve III"], "answer": 4, "why": ["Yanlış. II ve III de doğrudur (TTK m.39 vd.).", "Yanlış. I ve III de doğrudur (TTK).", "Yanlış. III de doğrudur; şube unvanı merkezin unvanını aynen içerir ve şube olduğunu belirtir (TTK).", "Yanlış. I de doğrudur; ticaret unvanı işletmeden ayrı olarak devredilemez (TTK).", "Doğru. Unvan işletmeden ayrı devredilemez, tacir işlemlerini unvanıyla yapmak zorundadır (TTK m.39) ve şubeler merkezin unvanını şube olduklarını belirterek kullanır (TTK)."], "ref": "TTK m.39 vd."}, {"id": "HUK-034", "exam": "ortak", "topic": "Ticaret Unvanı", "q": "Ticaret unvanı haksız olarak kullanılan kimsenin Türk Ticaret Kanunu'na göre talep edebileceği hususlar arasında aşağıdakilerden hangisi yer almaz?", "options": ["Haksız kullananın ticari işletmesinin kapatılması", "Haksız kullanmanın tespiti", "Haksız kullanmanın durdurulması", "Unvan sicile kaydedilmişse değiştirilmesi veya silinmesi", "Kusur varsa zararın tazmini"], "answer": 0, "why": ["Doğru (talep edilemez). Unvanın korunmasına ilişkin davalarda işletmenin kapatılması talebi öngörülmemiştir (TTK).", "Yanlış. Tespit talebi unvanın korunması kapsamında istenebilir (TTK).", "Yanlış. Durdurma (men) talep edilebilir (TTK).", "Yanlış. Haksız unvanın değiştirilmesi ve sicile kaydedilmişse silinmesi istenebilir (TTK).", "Yanlış. Kusur varsa tazminat istenebilir (TTK)."], "ref": "TTK (ticaret unvanının korunması)"}, {"id": "HUK-035", "exam": "ortak", "topic": "İşletme Adı", "q": "İşletme adı ile ticaret unvanı arasındaki ilişki bakımından aşağıdakilerden hangisi doğrudur?", "options": ["İşletme adı kullanmak her tacir için zorunludur.", "Ticaret unvanı tacirin ticari işletmesine ilişkin işlemlerde kullandığı addır; işletme adı ise işletmeyi tanıtmak ve diğer işletmelerden ayırmak için kullanılan addır.", "Tacir, işletmesine ait senetleri ticaret unvanı yerine işletme adıyla imzalayabilir.", "İşletme adı ticaret siciline hiçbir şekilde tescil edilemez.", "İşletme adı ile ticaret unvanı aynı kavramı ifade eder."], "answer": 1, "why": ["Yanlış. Ticaret unvanı kullanmak zorunludur; işletme adı kullanmak ise isteğe bağlıdır (TTK).", "Doğru. Ticaret unvanı tacire (süjeye), işletme adı ise işletmeye (objeye) ilişkin bir addır (TTK).", "Yanlış. Tacir işletmesine ait senet ve belgeleri ticaret unvanıyla imzalamak zorundadır (TTK m.39).", "Yanlış. İşletme adı ticaret siciline tescil ettirilebilir ve koruma görür (TTK).", "Yanlış. Unvan tacirin, işletme adı ise işletmenin adıdır; farklı kavramlardır (TTK)."], "ref": "TTK m.39; TTK (işletme adı)"}, {"id": "HUK-036", "exam": "ortak", "topic": "Haksız Rekabet", "q": "Türk Ticaret Kanunu'ndaki haksız rekabet hükümleri ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Haksız rekabetten söz edilebilmesi için taraflar arasında mutlaka bir rekabet ilişkisi bulunmalıdır.", "Haksız rekabet hükümleri yalnızca tacirler arasında uygulanır.", "Kanunda sayılan haksız rekabet hâlleri sınırlı sayıdadır; bunlar dışındaki davranışlar haksız rekabet oluşturmaz.", "Rakipler arasında veya tedarik edenlerle müşteriler arasındaki ilişkileri etkileyen aldatıcı veya dürüstlük kuralına diğer şekillerdeki aykırı davranışlar ile ticari uygulamalar haksız ve hukuka aykırıdır.", "Bir davranışın haksız rekabet sayılması için failin kusurlu olması şarttır."], "answer": 3, "why": ["Yanlış. TTK m.54/2 tedarik edenlerle müşteriler arasındaki ilişkileri de kapsar; rakip olma şartı aranmaz.", "Yanlış. Haksız rekabet hükümlerinin amacı tüm katılanların menfaatine dürüst rekabeti sağlamaktır; yalnız tacirlerle sınırlı değildir (TTK m.54).", "Yanlış. TTK m.55'teki hâller örnek niteliğindedir; m.54'teki genel hüküm diğer davranışları da kapsar.", "Doğru. TTK m.54/2'deki genel ilkedir.", "Yanlış. Kusur yalnızca tazminat talepleri için aranır; tespit, men ve ortadan kaldırma davaları için gerekli değildir (TTK m.56)."], "ref": "TTK m.54"}, {"id": "HUK-037", "exam": "ortak", "topic": "Haksız Rekabet", "q": "Aşağıdakilerden hangisi Türk Ticaret Kanunu'nda dürüstlük kuralına aykırı davranış (haksız rekabet) olarak sayılan hâllerden biri değildir?", "options": ["Kendi ürününü, rakibinden daha düşük ancak maliyetinin üstünde bir fiyatla satışa sunmak", "Başkalarını, mallarını, iş ürünlerini veya faaliyetlerini yanlış, yanıltıcı veya gereksiz yere incitici açıklamalarla kötülemek", "Başkasının malları, iş ürünleri, faaliyetleri veya işletmesiyle karışıklık yaratmaya elverişli önlemler almak", "Müşterileri, başkalarıyla yaptıkları sözleşmeleri ihlale yöneltmek", "Hukuka aykırı olarak elde ettiği imalat veya iş sırlarını değerlendirmek veya başkalarına bildirmek"], "answer": 0, "why": ["Doğru (haksız rekabet değildir). Maliyetin üstünde fiyatla rekabet etmek olağan rekabettir; kanun, seçilmiş malların maliyet fiyatının altında tekrarlanan biçimde satışa sunulması gibi özel durumları haksız sayar (TTK m.55).", "Yanlış. Bu, dürüstlük kuralına aykırı reklam ve satış yöntemleri arasında sayılmıştır (TTK m.55).", "Yanlış. Karıştırılma tehlikesi yaratmak haksız rekabet hâlidir (TTK m.55).", "Yanlış. Sözleşmeyi ihlale yöneltmek haksız rekabet hâlidir (TTK m.55).", "Yanlış. İmalat ve iş sırlarının hukuka aykırı ifşası haksız rekabet hâlidir (TTK m.55)."], "ref": "TTK m.55"}, {"id": "HUK-038", "exam": "ortak", "topic": "Haksız Rekabet", "q": "Ticaret ve sanayi odaları, meslek birlikleri ve tüketicinin korunmasını amaçlayan kuruluşlar gibi kurumlar, haksız rekabet nedeniyle aşağıdaki davalardan hangisini açamaz?", "options": ["Fiilin haksız olup olmadığının tespiti davası", "Haksız rekabetin men'i davası", "Haksız rekabetin sonucu olan maddi durumun ortadan kaldırılması davası", "Maddi ve manevi tazminat davası", "Haksız rekabet yanlış veya yanıltıcı beyanlarla yapılmışsa bu beyanların düzeltilmesi talebi"], "answer": 3, "why": ["Yanlış. Tespit davası bu kuruluşlarca açılabilir (TTK m.56).", "Yanlış. Men davası bu kuruluşlarca açılabilir (TTK m.56).", "Yanlış. Bu dava da bu kuruluşlarca açılabilir (TTK m.56).", "Doğru (açamazlar). Bu kuruluşlar tespit, men ve maddi durumun ortadan kaldırılması davalarını açabilir; tazminat davası açma hakları yoktur (TTK m.56).", "Yanlış. Düzeltme talebi, maddi durumun ortadan kaldırılması davası kapsamındadır ve bu kuruluşlarca istenebilir (TTK m.56)."], "ref": "TTK m.56"}, {"id": "HUK-039", "exam": "ortak", "topic": "Haksız Rekabet", "q": "Türk Ticaret Kanunu'na göre haksız rekabet nedeniyle açılacak davaların zamanaşımı süresi aşağıdakilerden hangisinde doğru olarak verilmiştir? (Ceza kanunlarında daha uzun bir süre öngörülmediği varsayılmaktadır.)", "options": ["Öğrenmeden itibaren 6 ay ve her hâlde 2 yıl", "Hak sahibinin hakların doğumunu öğrendiği tarihten itibaren 1 yıl ve her hâlde doğumlarından itibaren 3 yıl", "Öğrenmeden itibaren 2 yıl ve her hâlde 5 yıl", "Öğrenmeden itibaren 1 yıl ve her hâlde 10 yıl", "Öğrenmeden itibaren 2 yıl ve her hâlde 10 yıl"], "answer": 1, "why": ["Yanlış. Kanundaki süreler 1 yıl ve 3 yıldır (TTK).", "Doğru. Haksız rekabet davaları öğrenmeden itibaren bir yıl, her hâlde doğumdan itibaren üç yıl içinde zamanaşımına uğrar; ceza kanunlarında daha uzun süre öngörülmüşse o süre uygulanır (TTK).", "Yanlış. Kanundaki süreler 1 yıl ve 3 yıldır (TTK).", "Yanlış. Mutlak süre 10 değil 3 yıldır (TTK).", "Yanlış. Bu süreler TBK'daki genel haksız fiil zamanaşımına ilişkindir; haksız rekabette 1 ve 3 yıllık süreler uygulanır (TTK, TBK m.72)."], "ref": "TTK (haksız rekabet – zamanaşımı)"}, {"id": "HUK-040", "exam": "ortak", "topic": "Haksız Rekabet", "q": "X AŞ'nin satış temsilcisi olarak çalışan E, işini görürken müşterilere rakip Y Ltd. Şti.'nin ürünleri hakkında gerçeğe aykırı ve kötüleyici açıklamalar yapmıştır. Bu durumda aşağıdakilerden hangisi doğrudur?", "options": ["Y Ltd. Şti. yalnızca E aleyhine dava açabilir; X AŞ'nin sorumluluğu söz konusu olamaz.", "E bir tacir olmadığından eylemi haksız rekabet oluşturmaz.", "Y Ltd. Şti., haksız rekabet davalarını E'nin yanı sıra işveren X AŞ aleyhine de açabilir.", "Y Ltd. Şti. ancak X AŞ'nin E'ye yazılı talimat verdiğini ispat ederse X AŞ aleyhine dava açabilir.", "Kötüleme, karşılaştırmalı reklam niteliğinde olduğundan her durumda hukuka uygundur."], "answer": 2, "why": ["Yanlış. İşçinin işini görürken yaptığı haksız rekabetten dolayı işveren aleyhine de dava açılabilir (TTK).", "Yanlış. Haksız rekabet için failin tacir olması şart değildir; dürüstlük kuralına aykırı davranış yeterlidir (TTK m.54, m.55).", "Doğru. Haksız rekabet işçiler veya diğer yardımcılar tarafından işlerini görürken yapılmışsa, işveren veya işletme sahibi aleyhine de haksız rekabet davaları açılabilir (TTK).", "Yanlış. Kanun, işverene karşı dava için yazılı talimat koşulu aramaz (TTK).", "Yanlış. Başkalarını gerçeğe aykırı açıklamalarla kötülemek açıkça haksız rekabet hâlidir (TTK m.55)."], "ref": "TTK (haksız rekabet – işçilerin fiilleri)"}, {"id": "KLV-001", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "SMK m.5/2'ye göre kullanım yoluyla kazanılmış ayırt edicilik, m.5/1'in hangi bentlerindeki ret nedenlerini aşmaya imkân verir?", "options": ["(a), (b) ve (c)", "(b), (c), (d) ve (e)", "(b), (c) ve (d)", "(c), (d) ve (f)", "Yalnızca (b)"], "answer": 2, "why": ["Yanlış. (a) bendi m.4 anlamında marka olamayacak işaretlere ilişkindir; kullanım bu eksikliği gidermez.", "Yanlış. (e) bendi (doğal, teknik veya asli değer veren şekil) kullanım yoluyla aşılamaz.", "Doğru. m.5/2 açıkça (b), (c) ve (d) bentlerini sayar.", "Yanlış. (f) bendi (yanıltıcılık) m.5/2 kapsamında değildir.", "Yanlış. İstisna yalnızca (b) ile sınırlı değildir; (c) ve (d) bentlerini de kapsar."], "ref": "SMK m.5/2"}, {"id": "KLV-002", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Paris Sözleşmesinin 6ter maddesine göre reddedilecek işaretler SMK m.5/1'in hangi bendinde düzenlenmiştir?", "options": ["(g) bendi", "(ğ) bendi", "(h) bendi", "(f) bendi", "(i) bendi"], "answer": 0, "why": ["Doğru. m.5/1-g, Paris Sözleşmesinin 6ter maddesine göre reddedilecek işaretleri düzenler.", "Yanlış. (ğ) bendi 6ter kapsamı dışında kalan, kamuyu ilgilendiren ve halka mal olmuş işaretler ile izinsiz armalara ilişkindir.", "Yanlış. (h) bendi dinî değer ve sembolleri içeren işaretlere ilişkindir.", "Yanlış. (f) bendi halkı yanıltacak işaretlere ilişkindir.", "Yanlış. (i) bendi tescilli coğrafi işaretlere ilişkindir."], "ref": "SMK m.5/1-g"}, {"id": "KLV-003", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Birbirine geçerek kenetlenmeyi sağlayan çıkıntılara sahip bir oyuncak yapı tuğlasının şekli için yapılan üç boyutlu marka başvurusunda başvuru sahibi, şeklin 20 yıldır yoğun kullanıldığını ve tüketicilerce tanındığını ispatlıyor. Kurumun yaklaşımı ne olmalıdır?", "options": ["Kullanım ispatlandığı için başvuru m.5/2 gereğince kabul edilir.", "Başvuru yalnızca itiraz gelirse reddedilebilir.", "Başvuru m.5/1-b gereğince reddedilir, ancak muvafakatname sunulursa kabul edilir.", "Şekil ses veya renk içermediğinden m.4 gereğince marka olamaz.", "Şekil teknik bir sonucu elde etmek için zorunlu olduğundan m.5/1-e gereğince reddedilir; kazanılmış ayırt edicilik bu bendi aşmaz."], "answer": 4, "why": ["Yanlış. m.5/2 yalnızca (b), (c) ve (d) bentlerine istisna getirir; (e) bendine uygulanmaz.", "Yanlış. Mutlak ret nedenleri Kurum tarafından resen incelenir (m.16/1).", "Yanlış. Muvafakatname yalnızca m.5/1-ç'deki reddi aşmaya yarar (m.5/3).", "Yanlış. m.4, malların veya ambalajlarının biçimini de marka olabilecek işaretler arasında sayar.", "Doğru. Teknik sonuç için zorunlu şekil (e) bendine girer ve kullanım bunu aşmaz."], "ref": "SMK m.5/1-e, m.5/2"}, {"id": "KLV-004", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "SMK m.5/1-ç kapsamındaki ret nedeni ile ilgili aşağıdakilerden hangisi doğrudur?", "options": ["Yalnızca önceki marka sahibinin itirazı üzerine incelenir.", "Önceki marka sahibinin noter onaylı açık muvafakatini gösteren belge sunulursa bu bent gereğince ret yapılamaz.", "Benzer mal ve hizmetler bakımından karıştırılma ihtimali bulunan tüm markaları kapsar.", "Üçüncü kişiler bu bende dayanarak m.17 uyarınca görüş sunabilir.", "Önceki markanın Türkiye'de tanınmış olmasını şart koşar."], "answer": 1, "why": ["Yanlış. m.5/1-ç bir mutlak ret nedenidir ve resen incelenir; itiraza bağlı olan m.6/1'dir.", "Doğru. m.5/3 bu imkânı açıkça tanır.", "Yanlış. (ç) bendi aynı veya aynı türdeki mallarda aynı veya ayırt edilemeyecek kadar benzer işaretlerle sınırlıdır; karıştırılma ihtimali m.6/1'in ölçütüdür.", "Yanlış. m.17, (ç) bendini görüş kapsamından açıkça çıkarır.", "Yanlış. Bentte tanınmışlık şartı yoktur."], "ref": "SMK m.5/1-ç, m.5/3, m.17"}, {"id": "KLV-005", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Dinî değerleri veya sembolleri içeren işaretler SMK m.5/1'in hangi bendine göre reddedilir?", "options": ["(ğ) bendi", "(ı) bendi", "(g) bendi", "(h) bendi", "(d) bendi"], "answer": 3, "why": ["Yanlış. (ğ) bendi kamuyu ilgilendiren, tarihî ve kültürel değerler bakımından halka mal olmuş işaretler ile izinsiz armaları düzenler.", "Yanlış. (ı) bendi kamu düzenine veya genel ahlaka aykırı işaretleri düzenler.", "Yanlış. (g) bendi Paris Sözleşmesi 6ter kapsamındaki işaretleri düzenler.", "Doğru. m.5/1-h dinî değerleri veya sembolleri içeren işaretleri düzenler.", "Yanlış. (d) bendi ticaret alanında herkesçe kullanılan işaretleri düzenler."], "ref": "SMK m.5/1-h"}, {"id": "KLV-006", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "SMK m.4'e göre bir işaretin marka olabilmesi için aranan şartlar aşağıdakilerden hangisinde doğru verilmiştir?", "options": ["Malları/hizmetleri ayırt etmeye elverişli olması ve korumanın konusu açık ve kesin anlaşılacak şekilde sicilde gösterilebilir olması", "Çizimle görüntülenebilmesi ve basılabilir olması", "Yalnızca kelime veya şekilden oluşması", "Türkiye'de başvuru tarihinden önce kullanılmış olması", "Türkçe olması ve en az iki harften oluşması"], "answer": 0, "why": ["Doğru. m.4 bu iki şartı birlikte arar.", "Yanlış. Çizimle görüntülenebilme KHK dönemine ait bir şarttı; SMK 'sicilde gösterilebilirlik' ölçütünü getirmiştir.", "Yanlış. m.4 renkleri, sesleri, harfleri, sayıları ve malların/ambalajların biçimini de sayar.", "Yanlış. Marka koruması tescil yoluyla elde edilir; önceki kullanım tescil şartı değildir.", "Yanlış. Böyle bir şart yoktur; m.4 harfleri ve sayıları da sayar."], "ref": "SMK m.4"}, {"id": "KLV-007", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Taze meyveler (31. sınıf) için yapılan 'UŞAK' ibareli bir başvuru ile halılar (27. sınıf) için yapılan 'UŞAK' ibareli bir başvuru değerlendirilirken hangi yaklaşım doğrudur?", "options": ["Her iki başvuru da coğrafi yer adı içerdiği için hiçbir koşulda tescil edilemez.", "Her iki başvuru da m.5/1-ğ gereğince reddedilir.", "Yer adının o mallar için coğrafi kaynak gösterip göstermediği mal bazında incelenir; halılar için bilinen bir üretim merkezi olarak tanımlayıcı sayılması beklenir.", "Yer adları yalnızca m.6/3 kapsamında itiraz üzerine incelenir.", "Yer adları ayırt edici olduğundan her iki başvuru da kabul edilir."], "answer": 2, "why": ["Yanlış. Yer adları kendiliğinden reddedilmez; mallarla bağlantısına bakılır.", "Yanlış. (ğ) bendi kamusal/tarihî işaretler ve armalarla ilgilidir; coğrafi kaynak belirten ibareler (c) bendinde değerlendirilir.", "Doğru. Tanımlayıcılık mal/hizmet bazında değerlendirilir (m.5/1-c, m.16/1).", "Yanlış. Coğrafi kaynak belirtme bir mutlak ret nedenidir ve resen incelenir.", "Yanlış. Bilinen bir üretim merkezinin adı ilgili mallar için tanımlayıcıdır."], "ref": "SMK m.5/1-c"}, {"id": "KLV-008", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Aşağıdakilerden hangisi SMK m.6'da düzenlenen ve itiraz üzerine incelenen bir ret nedeni değildir?", "options": ["Kötü niyetle yapılan başvuru", "Ticari vekil veya temsilcinin izinsiz başvurusu", "Başkasına ait ticaret unvanını içeren başvuru", "Tescilsiz marka üzerinde önceden hak elde edilmiş olması", "Kamu düzenine veya genel ahlaka aykırı işaret"], "answer": 4, "why": ["Yanlış. Kötü niyet m.6/9'da nispi ret nedeni olarak düzenlenmiştir.", "Yanlış. m.6/2'de düzenlenmiştir.", "Yanlış. m.6/6'da düzenlenmiştir.", "Yanlış. m.6/3'te düzenlenmiştir.", "Doğru. Kamu düzenine ve genel ahlaka aykırılık m.5/1-ı'da düzenlenen bir mutlak ret nedenidir."], "ref": "SMK m.5/1-ı, m.6"}, {"id": "KLV-009", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Karıştırılma ihtimali değerlendirmesindeki 'karşılıklı bağımlılık' ilkesi neyi ifade eder?", "options": ["Önceki marka sahibinin itirazı ile başvuru sahibinin cevabının birlikte değerlendirilmesini", "İşaretler arasındaki düşük benzerliğin mallar arasındaki yüksek benzerlikle (veya tersi) dengelenebilmesini", "Aynı sınıftaki malların her zaman benzer kabul edilmesini", "Mutlak ve nispi ret nedenlerinin birlikte incelenmesi zorunluluğunu", "Seri markaların tek bir marka gibi değerlendirilmesini"], "answer": 1, "why": ["Yanlış. Bu bir usul kuralıdır (m.19/1); karşılıklı bağımlılık ilkesi değildir.", "Doğru. Global değerlendirmede etkenler birbirini dengeler.", "Yanlış. Sınıf aynılığı veya farklılığı tek başına belirleyici değildir.", "Yanlış. İlkenin bu ayrımla ilgisi yoktur.", "Yanlış. Seri markalar ayrı bir değerlendirme konusudur."], "ref": "SMK m.6/1"}, {"id": "KLV-010", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Yenilenmediği için koruma süresi sona eren bireysel bir markaya dayalı itirazla ilgili hangisi doğrudur?", "options": ["Koruma süresinin sona ermesinden itibaren üç yıl içinde yapılan başvurulara, kullanım şartı aranmaksızın itiraz edilebilir.", "Yenilenmeyen markaya dayanılarak hiçbir şekilde itiraz edilemez.", "Bir yıl içinde yapılan başvurulara itiraz edilebilir.", "Sona ermeden itibaren iki yıl içinde yapılan aynı/benzer başvurular, markanın bu süre içinde kullanılmış olması şartıyla itiraz üzerine reddedilir.", "Sona ermeden itibaren beş yıl içinde Kurum resen ret kararı verir."], "answer": 3, "why": ["Yanlış. Üç yıllık süre ortak ve garanti markalarına ilişkindir (m.6/7) ve orada kullanım şartı yoktur.", "Yanlış. m.6/8 bu imkânı tanır.", "Yanlış. Süre bir yıl değil iki yıldır.", "Doğru. m.6/8 iki yıllık süreyi ve kullanım şartını öngörür.", "Yanlış. Bu nispi bir ret nedenidir; resen incelenmez."], "ref": "SMK m.6/8"}, {"id": "KLV-011", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Bir yabancı üreticinin Türkiye distribütörü, sözleşme ilişkisi sürerken üreticinin markasını izinsiz olarak kendi adına başvuruyor. Üreticinin dayanabileceği en özel ret nedeni hangisidir?", "options": ["SMK m.5/1-f", "SMK m.6/7", "SMK m.6/2", "SMK m.5/1-b", "SMK m.6/8"], "answer": 2, "why": ["Yanlış. Yanıltıcılık, malın niteliği ve kaynağı gibi konulara ilişkin bir mutlak ret nedenidir.", "Yanlış. m.6/7 yenilenmeyen ortak ve garanti markalarına ilişkindir.", "Doğru. m.6/2 ticari vekil veya temsilcinin izinsiz ve haklı sebebe dayanmayan başvurusunu düzenler.", "Yanlış. İşaret ayırt edici olabilir; sorun ayırt edicilik değil, hak sahipliğidir.", "Yanlış. m.6/8 yenilenmeyen bireysel markalara ilişkindir."], "ref": "SMK m.6/2"}, {"id": "KLV-012", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Paris Sözleşmesi 6bis anlamında tanınmış bir markaya dayanan itiraz (SMK m.6/4) ile Türkiye'de tanınmışlığa dayanan itiraz (SMK m.6/5) karşılaştırıldığında hangisi doğrudur?", "options": ["m.6/4 aynı veya benzer mal/hizmetlerle sınırlıdır; m.6/5 ise farklı mal/hizmetler için yapılan başvuruları da kapsar.", "Her ikisi de yalnızca aynı mal/hizmetler için uygulanır.", "m.6/4 Kurum tarafından resen uygulanır.", "m.6/5 için önceki markanın tescilli olması veya önceki tarihli başvurusunun bulunması aranmaz.", "m.6/5'te haklı sebep savunması kabul edilmez."], "answer": 0, "why": ["Doğru. Bu, iki fıkranın lafzından doğrudan çıkar.", "Yanlış. m.6/5 açıkça 'aynı, benzer veya farklı' mal/hizmetlerden söz eder.", "Yanlış. m.6/4 de 'itiraz üzerine' uygulanır.", "Yanlış. m.6/5, tescil edilmiş veya daha önce başvurusu yapılmış bir markayı arar.", "Yanlış. m.6/5'te 'haklı bir sebebe dayanma hâli saklı kalmak kaydıyla' ifadesi yer alır."], "ref": "SMK m.6/4, m.6/5"}, {"id": "KLV-013", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Kılavuz ve yerleşik uygulamaya göre 'SUPER' veya 'PREMIUM' gibi övücü terimlerle ilgili hangisi doğrudur?", "options": ["Yabancı dilde olduklarından Türkiye'de her zaman ayırt edici kabul edilirler.", "Yalnızca 6ter kapsamında değerlendirilirler.", "Kullanım yoluyla ayırt edicilik kazanmaları hukuken mümkün değildir.", "Kötü niyet göstergesi sayılırlar.", "Tek başlarına kalite belirten, ayırt edicilikten yoksun ibarelerdir; ayırt edici bir esas unsurla birlikte işaret bütün olarak tescil edilebilir."], "answer": 4, "why": ["Yanlış. Türk tüketicisinin anlayabileceği yaygın yabancı kelimeler Türkçe karşılıkları gibi değerlendirilir.", "Yanlış. 6ter, devlet amblemleri ve uluslararası kuruluşların işaretleriyle ilgilidir.", "Yanlış. Bu terimler (b) ve (c) bentlerine girer ve m.5/2 bu bentler için kazanılmış ayırt ediciliği kabul eder.", "Yanlış. Övücü terim kullanmanın kötü niyetle bir ilgisi yoktur.", "Doğru. Kalite belirtme (c) ve ayırt edicilik (b) bakımından tek başına ret; birleşik işarette kabul mümkündür."], "ref": "SMK m.5/1-b, m.5/1-c"}, {"id": "KLV-014", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "SMK m.6/1'e dayanan bir itirazda başvuru sahibi, itiraz sahibinden kullanım ispatı isteyebilmek için hangi koşulun varlığına dayanır?", "options": ["İtiraz gerekçesi markanın Türkiye'de en az üç yıldır tescilli olması", "İtiraz gerekçesi markanın, itiraza konu başvurunun başvuru veya rüçhan tarihinde Türkiye'de en az beş yıldır tescilli olması", "İtiraz sahibinin yabancı uyruklu olması", "İtirazın m.6/9'a da dayanması", "Kurumun resen kullanım ispatı istemiş olması"], "answer": 1, "why": ["Yanlış. Kanundaki süre beş yıldır.", "Doğru. m.19/2 bu koşulu arar ve kullanım ispatı başvuru sahibinin talebiyle istenir.", "Yanlış. Uyrukla ilgili bir koşul yoktur.", "Yanlış. Kullanım ispatı m.6/1 itirazlarına özgüdür.", "Yanlış. İspat, başvuru sahibinin talebi üzerine istenir; Kurum resen istemez."], "ref": "SMK m.19/2"}, {"id": "KLV-015", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Kötü niyetli marka başvurularına ilişkin SMK düzenlemesi hakkında hangisi doğrudur?", "options": ["Kötü niyet m.5'te mutlak ret nedeni olarak düzenlenmiş ve resen incelenir.", "Kanun kötü niyeti ayrıntılı biçimde tanımlar.", "Kötü niyet iddiası yalnızca hükümsüzlük davasında ileri sürülebilir.", "Kötü niyetli başvurular m.6/9 uyarınca itiraz üzerine reddedilir.", "Kötü niyetli sonraki tescil, beş yıllık sessiz kalma nedeniyle hükümsüzlükten korunur."], "answer": 3, "why": ["Yanlış. SMK'da kötü niyet m.6/9'da nispi ret nedenidir.", "Yanlış. SMK kötü niyeti tanımlamaz; içerik uygulamayla belirlenir.", "Yanlış. Yayıma itiraz aşamasında da ileri sürülebilir (m.18, m.6/9).", "Doğru. m.6/9'un lafzı budur.", "Yanlış. m.25/6 sessiz kalma kuralını sonraki tescilin kötü niyetli olmaması şartına bağlar."], "ref": "SMK m.6/9, m.25/6"}, {"id": "KLV-016", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Karıştırılma ihtimalinin değerlendirilmesinde esas alınan tüketiciyle ilgili hangisi doğrudur?", "options": ["Ölçüt, ilgili mal/hizmetin makul düzeyde bilgili ve dikkatli ortalama tüketicisidir ve dikkat düzeyi mala göre değişir.", "Ölçüt her zaman ilgili sektördeki uzmanlardır.", "Tüketicinin markaları her zaman yan yana görüp karşılaştırdığı varsayılır.", "Dikkat düzeyi tüm mallar için aynı kabul edilir.", "Yüksek dikkat düzeyi karıştırılma ihtimalini her durumda ortadan kaldırır."], "answer": 0, "why": ["Doğru. Bu, yerleşik ölçüttür.", "Yanlış. Profesyonel kullanıcıya yönelik mallar dışında ölçüt uzman değil, ortalama tüketicidir.", "Yanlış. Tüketici çoğu zaman belleğindeki kusurlu hatıraya güvenir.", "Yanlış. Günlük tüketim mallarında dikkat düşük, pahalı mallarda yüksektir.", "Yanlış. Yüksek dikkat düzeyi riski azaltır ama kendiliğinden ortadan kaldırmaz."], "ref": "SMK m.6/1"}, {"id": "KLV-017", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Yayımlanmış bir marka başvurusuna, başvurunun m.5/1-c kapsamında tanımlayıcı olduğu gerekçesiyle itiraz etmek isteyen kişi için hangisi doğrudur?", "options": ["Mutlak ret nedenlerine yalnızca Kurum dayanabileceği için itiraz edilemez.", "İtiraz süresi yayımdan itibaren üç aydır.", "İtiraz yayımdan itibaren iki ay içinde yazılı ve gerekçeli olarak yapılır; ücret de bu süre içinde ödenmelidir.", "İtiraz yalnızca m.6'ya dayanarak yapılabilir.", "İtiraz edebilmek için itiraz sahibinin tescilli bir markası olmalıdır."], "answer": 2, "why": ["Yanlış. m.18/1, m.5'e dayanan itirazlara açıkça izin verir.", "Yanlış. Süre iki aydır.", "Doğru. m.18/1 ve m.18/2 bu şartları düzenler.", "Yanlış. m.18/1 hem m.5'i hem m.6'yı sayar.", "Yanlış. Mutlak ret nedenine dayanan itiraz için tescilli marka sahibi olmak gerekmez."], "ref": "SMK m.18"}, {"id": "KLV-018", "exam": "marka", "topic": "Marka İnceleme Kılavuzu", "q": "Tescilli bir coğrafi işareti aynen içeren bir marka başvurusu SMK m.5/1'in hangi bendine göre reddedilir?", "options": ["(c) bendi", "(i) bendi", "(ğ) bendi", "(ç) bendi", "(e) bendi"], "answer": 1, "why": ["Yanlış. (c) bendi coğrafi kaynak belirten tanımlayıcı ibareleri genel olarak kapsar; tescilli coğrafi işaret için özel bent (i)'dir.", "Doğru. m.5/1-i, tescilli coğrafi işaretten oluşan veya tescilli coğrafi işaret içeren işaretleri düzenler.", "Yanlış. (ğ) bendi kamusal/tarihî işaretler ve armalarla ilgilidir.", "Yanlış. (ç) bendi önceki markalarla aynı veya ayırt edilemeyecek kadar benzer işaretlerle ilgilidir.", "Yanlış. (e) bendi şekil ve diğer özelliklerle ilgilidir."], "ref": "SMK m.5/1-i"}];
